      row('Tamanho', st.is_dir ? '<span id="pDu">—</span><button class="lnk" id="pCalc">calcular</button>' : fsize(st.size) + ' <span style="color:var(--dim)">(' + (st.size || 0).toLocaleString('pt-BR') + ' bytes)</span>') +
