      else { el = document.createElement('script'); el.src = url; el.async = false; }
      el.onload = res; el.onerror = () => { delete loaded[url]; rej(new Error('falha ao carregar ' + url)); };
      document.head.appendChild(el);
    });
    return loaded[url];
  }
