      ta = qs('textarea', bodyEl); ta.value = doc.content; ta.readOnly = !doc.writable; ta.focus();
      ta.addEventListener('input', setDirty);
      ta.addEventListener('keydown', ev => { if (ev.key === 'Tab') { ev.preventDefault(); const s = ta.selectionStart, en = ta.selectionEnd; ta.setRangeText(usesTabs ? '\t' : '    ', s, en, 'end'); setDirty(); } });
      const pos = () => { const t = ta.value.slice(0, ta.selectionStart).split('\n'); qs('#edPos', box).textContent = 'Ln ' + t.length + ', Col ' + (t[t.length - 1].length + 1); };
      ta.addEventListener('keyup', pos); ta.addEventListener('click', pos);
      qs('#edFind', box).disabled = true;
      qs('#edInfo', box).textContent = 'editor simples (sem internet para carregar o editor completo)';
    }
    const info = () => { const v = getVal(); qs('#edInfo', box).textContent = (ta ? qs('#edInfo', box).textContent.split(' · ').pop() + ' · ' : '') + v.split('\n').length + ' linhas · ' + fsize(new Blob([v]).size) + (doc.writable ? '' : ' · somente leitura'); };
    if (cm) info();
    ED = { dirty: () => getVal() !== clean, path };
    async function save(force) {
      if (saving || !doc.writable) return;
      saving = true; const b = qs('#edSave', box); b.disabled = true;
      const val = getVal();
      try {
        const d = await api('save', { path, content: val, enc, mtime, force: !!force });
        clean = val; mtime = d.mtime; setDirty(); if (cm) info(); toast('Salvo: ' + name);
        const it = S.items.find(i => i.path === path); if (it) { it.size = d.size; it.mtime = d.mtime; }
      } catch (e) {
        if (e.message === 'CONFLICT') {
          saving = false; b.disabled = false;
          if (await confirmDlg('Arquivo alterado por fora', 'O arquivo <b>' + E(name) + '</b> foi modificado no servidor depois que você abriu. Salvar mesmo assim e sobrescrever?', 'Sobrescrever', true)) return save(true);
          return;
        }
        fail(e);
      } finally { saving = false; b.disabled = false; (cm || ta).focus(); }
    }
    async function close() {
      if (ED && ED.dirty() && !(await confirmDlg('Descartar alterações?', 'Você tem alterações não salvas em <b>' + E(name) + '</b>.', 'Descartar', true))) return;
      document.removeEventListener('keydown', keys, true);
      box.remove(); ED = null; load(); body.focus();
    }
    const keys = ev => {
      if (!document.body.contains(box) || qs('.fm-ov')) return;
      if ((ev.ctrlKey || ev.metaKey) && ev.key.toLowerCase() === 's') { ev.preventDefault(); save(); }
      else if (ev.key === 'Escape' && !qs('.CodeMirror-dialog', box)) { ev.preventDefault(); close(); }
    };
    document.addEventListener('keydown', keys, true);
    qs('#edSave', box).onclick = () => save();
    qs('#edClose', box).onclick = close;
    qs('#edDl', box).onclick = () => download([{ path, type: 'file', name }]);
    qs('#edFind', box).onclick = () => cm && cm.execCommand('findPersistent');
    qs('#edWrap', box).classList.toggle('on', wrap);
    qs('#edWrap', box).onclick = () => { wrap = !wrap; ls.set('wrap', wrap); qs('#edWrap', box).classList.toggle('on', wrap); if (cm) cm.setOption('lineWrapping', wrap); else ta.classList.toggle('wrap', wrap); };
    if (!doc.writable) toast('Arquivo somente leitura', 'er');
  }

  /* ------------------------------------------------------------ visualizador */
  function viewImage(it) {
    const imgs = S.view.filter(isImg); let idx = Math.max(0, imgs.findIndex(i => i.path === it.path));
    const v = document.createElement('div'); v.className = 'fm-view';
    v.innerHTML = '<div class="vh"><span id="vName"></span><button class="ib" id="vDl" title="Baixar">' + svg('download') + '</button><button class="ib" id="vX" title="Fechar (Esc)">' + svg('x') + '</button></div>' +
      '<div class="vb"><img id="vImg" alt="">' + (imgs.length > 1 ? '<button class="nv p" id="vP">' + svg('chevL') + '</button><button class="nv n" id="vN">' + svg('chevR') + '</button>' : '') + '</div>';
    document.body.appendChild(v);
    const show = () => { const c = imgs[idx]; qs('#vImg', v).src = dlUrl(c.path, true); qs('#vName', v).textContent = c.name + '  ·  ' + fsize(c.size) + '  ·  ' + (idx + 1) + '/' + imgs.length; };
    const close = () => { v.remove(); document.removeEventListener('keydown', key, true); };
    const step = d => { idx = (idx + d + imgs.length) % imgs.length; show(); };
    const key = e => { if (e.key === 'Escape') { e.preventDefault(); close(); } else if (e.key === 'ArrowLeft') step(-1); else if (e.key === 'ArrowRight') step(1); };
    document.addEventListener('keydown', key, true);
    qs('#vX', v).onclick = close; qs('#vDl', v).onclick = () => download([imgs[idx]]);
    if (qs('#vP', v)) { qs('#vP', v).onclick = () => step(-1); qs('#vN', v).onclick = () => step(1); }
    qs('.vb', v).addEventListener('click', e => { if (e.target.classList.contains('vb')) close(); });
    show();
  }

  /* ------------------------------------------------------------ menu de contexto */
  function menu(x, y, entries) {
    closeMenu();
    const m = document.createElement('div'); m.className = 'fm-menu'; m.id = 'fmMenu';
    m.innerHTML = entries.map((e, i) => e === '-' ? '<hr>' : '<button data-k="' + i + '"' + (e.dis ? ' disabled' : '') + ' class="' + (e.danger ? 'danger' : '') + '">' + svg(e.i) + '<span>' + E(e.l) + '</span>' + (e.k ? '<kbd>' + e.k + '</kbd>' : '') + '</button>').join('');
    document.body.appendChild(m);
    const r = m.getBoundingClientRect();
    m.style.left = Math.max(6, Math.min(x, innerWidth - r.width - 6)) + 'px';
    m.style.top = Math.max(6, Math.min(y, innerHeight - r.height - 6)) + 'px';
    m.addEventListener('click', e => { const b = e.target.closest('button[data-k]'); if (!b || b.disabled) return; closeMenu(); entries[+b.dataset.k].fn(); });
  }
  function closeMenu() { const m = qs('#fmMenu'); if (m) m.remove(); }
  function itemMenu(e, it) {
    if (!S.sel.has(it.path)) { S.sel = new Set([it.path]); S.anchor = it.path; renderState(); }
    const sel = selItems(), one = sel.length === 1 ? sel[0] : null;
    const ent = [];
    if (one) {
      ent.push({ l: one.type === 'dir' ? 'Abrir' : isText(one) ? 'Editar' : isImg(one) ? 'Visualizar' : isArchive(one) ? 'Extrair…' : 'Abrir', i: one.type === 'dir' ? 'open' : isText(one) ? 'edit' : isArchive(one) ? 'unzip' : 'eye', k: 'Enter', fn: () => open(one) });
      if (one.type === 'file' && !isText(one) && !isImg(one)) ent.push({ l: 'Editar como texto', i: 'edit', fn: () => editFile(one.path) });
      if (S.search) ent.push({ l: 'Abrir local do arquivo', i: 'folderUp', fn: () => load(dirname(one.path), { select: [one.path] }) });
    }
    ent.push({ l: 'Baixar' + (sel.length > 1 || (one && one.type === 'dir') ? ' (.zip)' : ''), i: 'download', fn: () => download(sel) }, '-');
    ent.push({ l: 'Copiar', i: 'copy', k: 'Ctrl+C', fn: () => doClip('copy', sel) }, { l: 'Recortar', i: 'cut', k: 'Ctrl+X', fn: () => doClip('cut', sel) });
    if (one && one.type === 'dir' && S.clip) ent.push({ l: 'Colar dentro desta pasta', i: 'paste', fn: () => doPaste(one.path) });
    ent.push('-');
    ent.push({ l: 'Renomear', i: 'rename', k: 'F2', dis: !one, fn: () => doRename(one) }, { l: 'Permissões e dono', i: 'lock', fn: () => doPerm(sel) }, { l: 'Compactar (.zip)', i: 'zip', fn: () => doZip(sel) });
    if (one && isArchive(one)) ent.push({ l: 'Extrair', i: 'unzip', fn: () => doExtract(one) });
    ent.push('-');
    if (one) ent.push({ l: 'Copiar caminho', i: 'link', fn: () => copyText(one.path).then(() => toast('Caminho copiado')) });
    if (one && USER) ent.push({ l: 'Abrir no terminal', i: 'term', fn: () => goTerminal(one.type === 'dir' ? one.path : dirname(one.path)) });
    if (one) ent.push({ l: 'Propriedades', i: 'info', fn: () => doProps(one) });
    ent.push('-', { l: 'Excluir', i: 'trash', k: 'Del', danger: true, fn: () => doDelete(sel) });
    menu(e.clientX, e.clientY, ent);
  }
  function bgMenu(e) {
    if (S.sel.size) { S.sel.clear(); renderState(); }
    const ro = !!S.search;
    menu(e.clientX, e.clientY, [
      { l: 'Nova pasta', i: 'folderPlus', dis: ro, fn: doMkdir }, { l: 'Novo arquivo', i: 'filePlus', dis: ro, fn: doNewFile },
      { l: 'Enviar arquivos', i: 'upload', dis: ro, fn: () => qs('#fmFile').click() }, '-',
      { l: 'Colar', i: 'paste', k: 'Ctrl+V', dis: !S.clip || ro, fn: () => doPaste() }, { l: 'Selecionar tudo', i: 'selAll', k: 'Ctrl+A', fn: selectAll },
      { l: 'Atualizar', i: 'refresh', fn: () => load() }, '-',
      { l: 'Abrir no terminal', i: 'term', dis: !USER, fn: () => goTerminal(S.path) }, { l: 'Copiar caminho da pasta', i: 'link', fn: () => copyText(S.path).then(() => toast('Caminho copiado')) },
      { l: 'Propriedades da pasta', i: 'info', fn: () => doProps({ path: S.path, name: basename(S.path), type: 'dir' }) }
    ]);
  }
  function selectAll() { S.sel = new Set(S.view.map(i => i.path)); renderState(); }

  /* ------------------------------------------------------------ eventos */
  function editPath() {
    const c = qs('#fmCrumbs'); if (c.querySelector('input')) return;
    c.innerHTML = '<input value="' + E(S.path) + '" spellcheck="false" autocomplete="off">';
    const i = qs('input', c); i.focus(); i.select();
    let done = false;
    const end = async ok => { if (done) return; done = true; const v = i.value.trim(); c.innerHTML = ''; if (ok && v && v !== S.path) { if (!(await load(v.startsWith('/') ? v : pjoin(S.path, v)))) renderCrumbs(); } else renderCrumbs(); };
    i.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); end(true); } else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); end(false); } });
    i.addEventListener('blur', () => end(false));
  }

  const ACT = {
    back() { if (!S.back.length) return; S.fwd.push(S.path); load(S.back.pop(), { keepHistory: true }); },
    fwd() { if (!S.fwd.length) return; S.back.push(S.path); load(S.fwd.pop(), { keepHistory: true }); },
    up() { if (S.search) return endSearch(); if (S.path !== '/') load(dirname(S.path), { select: [S.path] }); },
    refresh() { S.search ? runSearch(S.search.q) : load(); },
    mkdir: doMkdir, newfile: doNewFile,
    upload() { qs('#fmFile').click(); }, uploadDir() { qs('#fmDir').click(); },
    copy() { doClip('copy'); }, cut() { doClip('cut'); }, paste() { doPaste(); }, clearClip() { S.clip = null; render(); },
    rename() { doRename(); }, perm() { doPerm(); }, zip() { doZip(); }, extract() { doExtract(); }, download() { download(); }, delete() { doDelete(); },
    hidden() { S.hidden = !S.hidden; ls.set('hidden', S.hidden); render(); },
    mode() { S.mode = S.mode === 'grid' ? 'list' : 'grid'; ls.set('mode', S.mode); render(); },
    selAll() { const all = S.view.length && S.view.every(i => S.sel.has(i.path)); if (all) S.sel.clear(); else selectAll(); renderState(); },
    endSearch
  };

  function bind() {
    root.addEventListener('click', e => {
      const a = e.target.closest('[data-a]');
      if (a && !a.disabled && ACT[a.dataset.a]) { e.preventDefault(); ACT[a.dataset.a](); return; }
      const g = e.target.closest('[data-go]');
      if (g && g.classList.contains('last')) { editPath(); return; }
      if (g) { load(g.dataset.go); return; }
      const so = e.target.closest('[data-sort]');
      if (so) { const k = so.dataset.sort; S.sort = { k, d: S.sort.k === k ? -S.sort.d : 1 }; ls.set('sort', S.sort); render(); return; }
      if (e.target.closest('#fmCrumbs') && !e.target.closest('.seg')) { editPath(); }
    });
    body.addEventListener('click', e => {
      const it = itemFromEl(e.target);
      if (!it) { if (!e.target.closest('.fm-head') && (S.sel.size)) { S.sel.clear(); renderState(); } return; }
      if (e.target.closest('.chk')) { selectClick(it, { toggle: true, shiftKey: e.shiftKey }); return; }
      if (coarse && !e.ctrlKey && !e.shiftKey && !S.sel.size) { open(it); return; }
      if (coarse && S.sel.size && !e.ctrlKey && !e.shiftKey) { selectClick(it, { toggle: true }); return; }
      selectClick(it, e);
    });
    body.addEventListener('dblclick', e => { const it = itemFromEl(e.target); if (it && !e.target.closest('.chk')) open(it); });
    body.addEventListener('contextmenu', e => { e.preventDefault(); const it = itemFromEl(e.target); it ? itemMenu(e, it) : bgMenu(e); });
    document.addEventListener('mousedown', e => { if (!e.target.closest('#fmMenu')) closeMenu(); }, true);
    window.addEventListener('blur', closeMenu);
    window.addEventListener('resize', closeMenu);
    body.addEventListener('scroll', closeMenu);

    // busca
    const si = qs('#fmSearch');
    si.addEventListener('input', () => { if (S.search) { S.search = null; } S.filter = si.value; render(); });
    si.addEventListener('keydown', e => {
      if (e.key === 'Enter') { e.preventDefault(); runSearch(si.value); }
      else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); si.value = ''; S.filter = ''; if (S.search) endSearch(); else render(); body.focus(); }
    });

    // arquivos para enviar
    qs('#fmFile').addEventListener('change', e => { startUpload([...e.target.files].map(f => ({ file: f, rel: '' }))); e.target.value = ''; });
    qs('#fmDir').addEventListener('change', e => {
      const list = [...e.target.files].map(f => { const p = f.webkitRelativePath || f.name; const i = p.lastIndexOf('/'); return { file: f, rel: i > 0 ? p.slice(0, i + 1) : '' }; });
      startUpload(list); e.target.value = '';
    });

    // arrastar arquivos do computador / mover itens
    const main = qs('.fm-main', root), drop = qs('#fmDrop');
    let depth = 0, dragPaths = null;
    const isFiles = e => e.dataTransfer && [...e.dataTransfer.types].includes('Files') && !dragPaths;
    main.addEventListener('dragenter', e => { if (!isFiles(e) || S.search || S.error) return; depth++; drop.classList.add('on'); qs('#fmDropTo').textContent = 'para ' + S.path; });
    main.addEventListener('dragleave', e => { if (!isFiles(e)) return; depth = Math.max(0, depth - 1); if (!depth) drop.classList.remove('on'); });
    main.addEventListener('dragover', e => { if (isFiles(e)) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; } });
    main.addEventListener('drop', async e => {
      if (!isFiles(e)) return;
      e.preventDefault(); depth = 0; drop.classList.remove('on');
      if (S.search || S.error) return;
      startUpload(await entriesFromDrop(e.dataTransfer));
    });
    // mover arrastando itens
    root.addEventListener('dragstart', e => {
      const it = itemFromEl(e.target); if (!it) return;
      if (!S.sel.has(it.path)) { S.sel = new Set([it.path]); S.anchor = it.path; renderState(); }
      dragPaths = selItems().map(i => i.path);
      e.dataTransfer.effectAllowed = 'copyMove';
      e.dataTransfer.setData('application/x-lkm', JSON.stringify(dragPaths));
      e.dataTransfer.setData('text/plain', dragPaths.join('\n'));
    });
    root.addEventListener('dragend', () => { dragPaths = null; qsa('.drop', root).forEach(x => x.classList.remove('drop')); });
    const targetOf = e => {
      const el = e.target.closest('[data-i], [data-go]'); if (!el) return null;
      if (el.dataset.go) return { el, path: el.dataset.go };
      const it = S.view[+el.dataset.i]; return it && it.type === 'dir' ? { el, path: it.path } : null;
    };
    root.addEventListener('dragover', e => {
      if (!dragPaths) return;
      const t = targetOf(e); qsa('.drop', root).forEach(x => { if (!t || x !== t.el) x.classList.remove('drop'); });
      if (t && !dragPaths.includes(t.path)) { e.preventDefault(); e.dataTransfer.dropEffect = e.ctrlKey || e.altKey ? 'copy' : 'move'; t.el.classList.add('drop'); }
    });
    root.addEventListener('drop', e => {
      if (!dragPaths) return;
      const t = targetOf(e); e.preventDefault(); const paths = dragPaths; dragPaths = null;
      qsa('.drop', root).forEach(x => x.classList.remove('drop'));
      if (t && !paths.includes(t.path)) moveTo(paths, t.path, e.ctrlKey || e.altKey);
    });

    // teclado
    document.addEventListener('keydown', e => {
      if (!root.offsetParent || ED || qs('.fm-ov') || qs('.fm-view')) return;
      const tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || e.target.isContentEditable) return;
      const k = e.key, mod = e.ctrlKey || e.metaKey;
      const sel = selItems();
      if (k === 'Escape') { closeMenu(); if (S.sel.size) { S.sel.clear(); renderState(); } else if (S.search) endSearch(); }
      else if (mod && k.toLowerCase() === 'a') { e.preventDefault(); selectAll(); }
      else if (mod && k.toLowerCase() === 'c') { if (sel.length) { e.preventDefault(); doClip('copy'); } }
      else if (mod && k.toLowerCase() === 'x') { if (sel.length) { e.preventDefault(); doClip('cut'); } }
      else if (mod && k.toLowerCase() === 'v') { if (S.clip && !S.search) { e.preventDefault(); doPaste(); } }
      else if (mod && k.toLowerCase() === 'f') { e.preventDefault(); qs('#fmSearch').focus(); }
      else if (k === 'Delete') { if (sel.length) { e.preventDefault(); doDelete(); } }
      else if (k === 'F2') { if (sel.length === 1) { e.preventDefault(); doRename(); } }
      else if (k === 'Enter') { if (sel.length === 1) { e.preventDefault(); open(sel[0]); } }
      else if (k === 'Backspace' || (e.altKey && k === 'ArrowUp')) { e.preventDefault(); ACT.up(); }
      else if (e.altKey && k === 'ArrowLeft') { e.preventDefault(); ACT.back(); }
      else if (e.altKey && k === 'ArrowRight') { e.preventDefault(); ACT.fwd(); }
      else if ((k === 'ArrowDown' || k === 'ArrowUp') && S.view.length) {
        e.preventDefault();
        let i = S.view.findIndex(x => x.path === S.anchor);
        i = i < 0 ? 0 : Math.max(0, Math.min(S.view.length - 1, i + (k === 'ArrowDown' ? 1 : -1)));
        selectClick(S.view[i], { shiftKey: e.shiftKey });
        if (!e.shiftKey) S.anchor = S.view[i].path;
        const el = qs('[data-i="' + i + '"]', body); if (el) el.scrollIntoView({ block: 'nearest' });
      }
    });
  }

  /* ------------------------------------------------------------ inicialização */
  /* componentes compartilhados com as outras abas (sites.js) */
  window.UI = { E, qs, qsa, toast, fail, dialog, prompt, confirmDlg, menu, closeMenu, svg, IC, copyText, fsize, fdate, coarse };

  window.FM = {
    go(p) {
      if (!inited) { S.path = p; return; }
      load(p);
    },
    show() {
      if (!qs('#fm')) return;
      if (!USER) { qs('#fm').innerHTML = '<div class="card" style="max-width:640px;margin:40px auto">O gerenciador de arquivos está desativado. Rode o instalador do LK Monitor de novo e escolha <b>root</b> ou seu usuário na pergunta do terminal.</div>'; return; }
      if (!inited) { inited = true; build(); load(S.path).then(ok => { if (!ok && S.path !== HOME) { S.loaded = false; S.error = ''; load(HOME); } }); }
      else if (!S.busy && !ED) load(null);
    }
  };
  if (location.hash === '#arquivos') window.FM.show();
})();
LKM_EOF_FMJS
cat > "$DIR/fm.css" <<'LKM_EOF_FMCSS'
/* LK Monitor - gerenciador de arquivos */
#fm{height:calc(100vh - 92px);min-height:420px}
.fm{display:grid;grid-template-columns:210px minmax(0,1fr);gap:14px;height:100%}
#fm [hidden],.fm-ed [hidden],.fm-view [hidden]{display:none!important}
svg.i{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}

/* lateral */
.fm-side{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:12px 10px;display:flex;flex-direction:column;gap:2px;overflow:auto}
.fm-side h3{font-size:11px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--dim);padding:6px 10px 6px}
.fm-place{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;color:var(--mut);font-size:13.5px;cursor:pointer;border:1px solid transparent;user-select:none;white-space:nowrap}
.fm-place:hover{background:var(--bg2);color:var(--tx)}
.fm-place.on{background:#5b9cff1a;color:#2f8cdc;border-color:#5b9cff33}
.fm-place.drop{border-color:var(--cpu);background:#5b9cff22}
.fm-place small{margin-left:auto;color:var(--dim);font-size:11px;font-family:var(--mono);overflow:hidden;text-overflow:ellipsis}
.fm-disk{margin-top:auto;padding:12px 10px 4px;border-top:1px solid var(--line)}
.fm-disk .rl{font-size:12px;color:var(--mut);display:flex;flex-direction:column;gap:2px;margin-bottom:8px;white-space:nowrap}
.fm-disk .rl span:last-child{color:var(--tx);font-family:var(--mono);font-size:11px}
.fm-disk .bar{height:6px;background:var(--line);border-radius:4px;overflow:hidden}
.fm-disk .bar i{display:block;height:100%;background:var(--disk);border-radius:4px}

/* principal */
.fm-main{background:var(--card);border:1px solid var(--line);border-radius:var(--r);display:flex;flex-direction:column;min-width:0;min-height:0;position:relative;overflow:hidden}
.fm-top{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line)}
.fm-nav{display:flex;gap:2px}
.ib{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:32px;min-width:32px;padding:0 9px;border-radius:8px;border:1px solid transparent;background:none;color:var(--mut);font:500 13px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;white-space:nowrap}
.ib:hover:not(:disabled){background:var(--bg2);color:var(--tx);border-color:var(--line)}
.ib:disabled{opacity:.35;cursor:default}
.ib.pri{background:var(--pri);color:#fff}
.ib.pri:hover:not(:disabled){filter:brightness(1.1);background:var(--pri);color:#fff}
.ib.danger:hover:not(:disabled){color:#d93a2e;background:#ef44441a;border-color:#ef444444}
.ib.on{background:var(--line2);color:var(--tx)}
.ib .cnt{background:var(--pri);color:#fff;border-radius:999px;font-size:11px;padding:0 6px;line-height:16px}
.fm-crumbs{flex:1;min-width:0;display:flex;align-items:center;height:34px;background:var(--bg2);border:1px solid var(--line);border-radius:9px;padding:0 6px;overflow:hidden;cursor:text}
.fm-crumbs .cr{display:flex;align-items:center;min-width:0;overflow-x:auto;scrollbar-width:none;white-space:nowrap}
.fm-crumbs .cr::-webkit-scrollbar{display:none}
.fm-crumbs .seg{padding:3px 7px;border-radius:6px;color:var(--mut);font-size:13px;cursor:pointer;border:1px solid transparent}
.fm-crumbs .seg:hover{background:var(--line);color:var(--tx)}
.fm-crumbs .seg.last{color:var(--tx);font-weight:600}
.fm-crumbs .seg.drop{border-color:var(--cpu);background:#5b9cff22}
.fm-crumbs .sl{color:var(--dim);font-size:12px}
.fm-crumbs input{flex:1;background:none;border:0;outline:none;color:var(--tx);font:13px var(--mono);height:100%;padding:0 6px}
.fm-search{position:relative;width:230px;flex:none}
.fm-search svg{position:absolute;left:10px;top:9px;color:var(--dim)}
.fm-search input{width:100%;height:34px;background:var(--bg2);border:1px solid var(--line);border-radius:9px;color:var(--tx);padding:0 10px 0 32px;font-size:13px;outline:none}
.fm-search input:focus,.fm-crumbs:focus-within{border-color:var(--cpu);box-shadow:0 0 0 3px #5b9cff22}
.fm-tools{display:flex;align-items:center;gap:2px;padding:6px 10px;border-bottom:1px solid var(--line);overflow-x:auto;scrollbar-width:thin}
.fm-tools .sep{width:1px;height:20px;background:var(--line);margin:0 6px;flex:none}
.fm-tools .sp{flex:1}

/* lista */
.fm-body{flex:1;overflow:auto;position:relative;min-height:0;outline:none}
.fm-load{position:absolute;top:0;left:0;height:2px;width:0;background:var(--cpu);z-index:3;transition:width .3s}
.fm-load.on{width:70%;transition:width 4s cubic-bezier(.1,.7,.2,1)}
.fm-head,.fm-row{display:grid;grid-template-columns:34px minmax(180px,1fr) 100px 150px 120px 140px;align-items:center}
.fm-head{position:sticky;top:0;z-index:2;background:var(--card);border-bottom:1px solid var(--line);font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--dim);height:34px}
.fm-head span{padding:0 10px;cursor:pointer;user-select:none;display:flex;align-items:center;gap:4px;height:100%}
.fm-head span:hover{color:var(--mut)}
.fm-head span.on{color:var(--tx)}
.fm-head .r,.fm-row .r{justify-content:flex-end;text-align:right}
.fm-row{height:38px;border-bottom:1px solid #e9ecef;font-size:13.5px;cursor:default;user-select:none}
.fm-row>span{padding:0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fm-row>span.c-chk,.fm-head>span:first-child{padding:0 0 0 10px;overflow:visible;text-overflow:clip;cursor:pointer}
.fm-row:hover{background:#f2f5f8}
.fm-row.sel{background:#5b9cff1f}
.fm-row.sel:hover{background:#5b9cff2a}
.fm-row.cut{opacity:.45}
.fm-row.drop{outline:2px solid var(--cpu);outline-offset:-2px;background:#5b9cff22}
.fm-row .c-name{display:flex;align-items:center;gap:10px;min-width:0}
.fm-row .nm{overflow:hidden;text-overflow:ellipsis}
.fm-row .lk{color:var(--dim);font-size:12px;overflow:hidden;text-overflow:ellipsis;flex:none;max-width:40%}
.fm-row .c-size,.fm-row .c-date,.fm-row .c-own{color:var(--mut);font-size:12.5px}
.fm-row .c-perm{font-family:var(--mono);font-size:12px;color:var(--mut)}
.fm-row .c-perm b{color:var(--tx);font-weight:500;margin-right:6px}
.fm-row .c-path{color:var(--dim);font-size:12px}
.chk{width:16px;height:16px;border:1.5px solid var(--line2);border-radius:4px;display:inline-block;position:relative;cursor:pointer;vertical-align:middle}
.sel .chk,.chk.on{background:var(--cpu);border-color:var(--cpu)}
.sel .chk::after,.chk.on::after{content:"";position:absolute;left:4px;top:1px;width:4px;height:8px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.chk.part{background:var(--cpu);border-color:var(--cpu)}
.chk.part::after{content:"";position:absolute;left:3px;top:6px;width:7px;height:2px;background:#fff}
.ico{width:22px;height:22px;flex:none;display:inline-flex;align-items:center;justify-content:center}
.ico svg{width:100%;height:100%}

/* grade */
.fm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:6px;padding:12px}
.fm-tile{display:flex;flex-direction:column;align-items:center;gap:8px;padding:12px 6px 10px;border-radius:10px;border:1px solid transparent;cursor:default;user-select:none;text-align:center;position:relative}
.fm-tile:hover{background:#f2f5f8}
.fm-tile.sel{background:#5b9cff1f;border-color:#5b9cff55}
.fm-tile.cut{opacity:.45}
.fm-tile.drop{border-color:var(--cpu);background:#5b9cff22}
.fm-tile .ico{width:56px;height:56px}
.fm-tile .thumb{width:72px;height:56px;object-fit:cover;border-radius:6px;background:var(--bg2)}
.fm-tile .nm{font-size:12.5px;line-height:1.3;word-break:break-word;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;max-width:100%}
.fm-tile .meta{font-size:11px;color:var(--dim)}
.fm-tile .chk{position:absolute;top:8px;left:8px;opacity:0}
.fm-tile:hover .chk,.fm-tile.sel .chk{opacity:1}

.fm-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:var(--dim);padding:70px 20px;text-align:center}
.fm-empty .ico{width:64px;height:64px;opacity:.5}
.fm-empty b{color:var(--mut);font-size:15px}
.fm-err{margin:20px;padding:14px 16px;border-radius:10px;background:#ef44441a;border:1px solid #ef444444;color:#d93a2e;font-size:13.5px}

.fm-status{display:flex;align-items:center;gap:14px;padding:8px 14px;border-top:1px solid var(--line);font-size:12.5px;color:var(--mut);min-height:38px;flex-wrap:wrap}
.fm-status .sp{flex:1}
.fm-status .clip{display:flex;align-items:center;gap:8px;background:var(--bg2);border:1px solid var(--line);border-radius:999px;padding:2px 4px 2px 12px}
.fm-status .clip button{background:none;border:0;color:var(--cpu);cursor:pointer;font-size:12.5px;padding:2px 8px;border-radius:999px}
.fm-status .clip button:hover{background:var(--line)}
.fm-status .srch{color:#2f8cdc}

/* arrastar e soltar */
.fm-drop{position:absolute;inset:8px;border:2px dashed var(--cpu);border-radius:12px;background:#ffffffd9;display:none;align-items:center;justify-content:center;flex-direction:column;gap:10px;z-index:6;color:#1f6fb5;font-size:15px;pointer-events:none}
.fm-drop.on{display:flex}
.fm-drop svg.i{width:40px;height:40px;color:var(--cpu)}
.fm-drop small{color:var(--mut)}

/* menu de contexto */
.fm-menu{position:fixed;z-index:90;min-width:220px;background:#ffffff;border:1px solid var(--line2);border-radius:10px;padding:5px;box-shadow:0 18px 50px #0000002e;font-size:13.5px}
.fm-menu button{display:flex;align-items:center;gap:10px;width:100%;padding:7px 10px;background:none;border:0;color:var(--tx);border-radius:6px;cursor:pointer;text-align:left;font:inherit}
.fm-menu button:hover:not(:disabled){background:#5b9cff22}
.fm-menu button:disabled{opacity:.35;cursor:default}
.fm-menu button svg{color:var(--mut)}
.fm-menu button kbd{margin-left:auto;color:var(--dim);font:11px var(--mono)}
.fm-menu button.danger{color:#d93a2e}
.fm-menu button.danger svg{color:#d93a2e}
.fm-menu hr{border:0;border-top:1px solid var(--line);margin:4px 2px}

/* janelas */
.fm-ov{position:fixed;inset:0;z-index:95;background:#05070cb3;backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:16px;animation:fmf .15s ease}
@keyframes fmf{from{opacity:0}}
.fm-dlg{width:100%;max-width:440px;background:#ffffff;border:1px solid var(--line2);border-radius:14px;box-shadow:0 30px 80px #00000030;display:flex;flex-direction:column;max-height:calc(100vh - 32px);animation:fmu .18s ease}
@keyframes fmu{from{transform:translateY(8px);opacity:0}}
.fm-dlg.wide{max-width:560px}
.fm-dlg h4{font-size:16px;font-weight:600;padding:18px 20px 4px;display:flex;align-items:center;gap:10px}
.fm-dlg .db{padding:10px 20px 6px;overflow:auto;font-size:13.5px;color:var(--mut);line-height:1.55}
.fm-dlg .db b{color:var(--tx);font-weight:600}
.fm-dlg .df{display:flex;justify-content:flex-end;gap:8px;padding:14px 20px 18px;flex-wrap:wrap}
.fm-dlg .df button{height:36px;padding:0 16px;border-radius:9px;border:1px solid var(--line2);background:var(--bg2);color:var(--tx);font-size:13.5px;font-weight:500;cursor:pointer}
.fm-dlg .df button:hover{border-color:var(--mut)}
.fm-dlg .df button.pri{background:var(--pri);border-color:var(--pri);color:#fff}
.fm-dlg .df button.pri:hover{filter:brightness(1.1)}
.fm-dlg .df button.danger{background:var(--bad);border-color:var(--bad);color:#fff}
.fm-dlg .df button:disabled{opacity:.6;cursor:wait}
.fm-in{width:100%;height:38px;background:var(--bg2);border:1px solid var(--line2);border-radius:9px;color:var(--tx);padding:0 12px;font-size:14px;outline:none;margin-top:8px}
.fm-in.mono{font-family:var(--mono);font-size:13px}
.fm-in:focus{border-color:var(--cpu);box-shadow:0 0 0 3px #5b9cff22}
.fm-dlg label.ck{display:flex;align-items:center;gap:8px;margin-top:12px;cursor:pointer;color:var(--tx)}
.fm-dlg label.ck input{accent-color:var(--cpu);width:16px;height:16px}
.fm-names{margin-top:10px;max-height:150px;overflow:auto;background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:6px 10px;font:12.5px var(--mono);color:var(--tx)}
.fm-names div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:2px 0}
.perm-grid{display:grid;grid-template-columns:auto repeat(3,1fr);gap:8px 10px;align-items:center;margin-top:12px;background:var(--bg2);border:1px solid var(--line);border-radius:10px;padding:12px 14px}
.perm-grid .h{font-size:11.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.05em;text-align:center}
.perm-grid .w{color:var(--tx);font-size:13px}
.perm-grid label{display:flex;justify-content:center;cursor:pointer}
.perm-grid input{accent-color:var(--cpu);width:17px;height:17px;cursor:pointer}
.perm-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:4px}
.perm-row div>span{font-size:12px;color:var(--dim)}
.perm-rwx{font:13px var(--mono);color:var(--tx);margin-left:8px}
.props{display:grid;grid-template-columns:auto 1fr;gap:8px 16px;margin-top:6px}
.props dt{color:var(--dim)}
.props dd{color:var(--tx);word-break:break-all;font-size:13px}
.props dd code{font-family:var(--mono);font-size:12.5px}
.props .lnk{background:none;border:0;color:var(--cpu);cursor:pointer;font-size:12.5px;padding:0;margin-left:6px}

/* upload */
.fm-up{position:fixed;right:18px;bottom:18px;z-index:55;width:340px;max-width:calc(100vw - 36px);background:#ffffff;border:1px solid var(--line2);border-radius:12px;box-shadow:0 20px 60px #0000002e;overflow:hidden}
.fm-up .uh{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;font-weight:600}
.fm-up .uh span{flex:1}
.fm-up .ul{max-height:240px;overflow:auto;padding:4px 0}
.fm-up .ui{padding:7px 12px;font-size:12.5px}
.fm-up .ui .t{display:flex;gap:8px;justify-content:space-between;margin-bottom:5px}
.fm-up .ui .t b{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--tx)}
.fm-up .ui .t small{color:var(--dim);flex:none}
.fm-up .ui .t small.er{color:#d93a2e}
.fm-up .ui .t small.ok{color:var(--ok)}
.fm-up .ui .bar{height:4px;background:var(--line);border-radius:3px;overflow:hidden}
.fm-up .ui .bar i{display:block;height:100%;width:0;background:var(--cpu);transition:width .2s}
.fm-up .ui.done .bar i{background:var(--ok)}
.fm-up .ui.err .bar i{background:var(--bad)}

/* toasts */
.fm-toasts{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:100;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}
.fm-toast{background:#ffffff;border:1px solid var(--line2);color:var(--tx);padding:10px 16px;border-radius:10px;font-size:13.5px;box-shadow:0 12px 40px #00000026;animation:fmu .2s ease;max-width:min(560px,90vw);display:flex;gap:10px;align-items:center}
.fm-toast.ok::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--ok);flex:none}
.fm-toast.er{border-color:#ef444466;background:#fdecea;color:#b3261e}
.fm-toast.er::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--bad);flex:none}

/* editor */
.fm-ed{position:fixed;inset:0;z-index:80;background:#0a0e17;display:flex;flex-direction:column}
.fm-ed .eh{display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--line);background:#0f1522}
.fm-ed .eh .ico{width:20px;height:20px}
.fm-ed .ep{flex:1;min-width:0;font:13px var(--mono);color:var(--mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;direction:rtl;text-align:left}
.fm-ed .ep b{color:var(--tx);font-weight:600}
.fm-ed .dirty{width:9px;height:9px;border-radius:50%;background:var(--warn);display:none;flex:none}
.fm-ed.is-dirty .dirty{display:block}
.fm-ed .badge{font-size:11px;padding:2px 8px;border-radius:999px;border:1px solid var(--line2);color:var(--mut)}
.fm-ed .eb{flex:1;min-height:0;position:relative}
.fm-ed .eb .CodeMirror{height:100%;font:13.5px/1.55 var(--mono)}
.fm-ed textarea.plain{width:100%;height:100%;background:#0b1020;color:#dbe4f3;border:0;outline:none;resize:none;padding:14px 16px;font:13.5px/1.55 var(--mono);tab-size:4;white-space:pre;overflow:auto}
.fm-ed textarea.plain.wrap{white-space:pre-wrap}
.fm-ed .ef{display:flex;gap:16px;align-items:center;padding:5px 14px;border-top:1px solid var(--line);font:12px var(--mono);color:var(--dim);background:#0f1522}
.fm-ed .ef .sp{flex:1}
.fm-ed .eload{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--mut);font-size:14px}

/* tema do CodeMirror */
.cm-s-lkm.CodeMirror{background:#0b1020;color:#dbe4f3}
.cm-s-lkm .CodeMirror-gutters{background:#0b1020;border-right:1px solid #1a2336}
.cm-s-lkm .CodeMirror-linenumber{color:#3f4b66}
.cm-s-lkm .CodeMirror-cursor{border-left:2px solid #5b9cff}
.cm-s-lkm div.CodeMirror-selected,.cm-s-lkm.CodeMirror-focused div.CodeMirror-selected{background:#28406f}
.cm-s-lkm .CodeMirror-line::selection,.cm-s-lkm .CodeMirror-line>span::selection,.cm-s-lkm .CodeMirror-line>span>span::selection{background:#28406f}
.cm-s-lkm .CodeMirror-activeline-background{background:#111a2e}
.cm-s-lkm .CodeMirror-activeline-gutter .CodeMirror-linenumber{color:#8592ad}
.cm-s-lkm .CodeMirror-matchingbracket{color:#fff!important;background:#2c3d63;outline:1px solid #5b9cff66}
.cm-s-lkm .cm-keyword{color:#c792ea}
.cm-s-lkm .cm-atom,.cm-s-lkm .cm-number{color:#f78c6c}
.cm-s-lkm .cm-def{color:#82aaff}
.cm-s-lkm .cm-variable{color:#dbe4f3}
.cm-s-lkm .cm-variable-2{color:#f07178}
.cm-s-lkm .cm-variable-3,.cm-s-lkm .cm-type{color:#ffcb6b}
.cm-s-lkm .cm-property{color:#80cbc4}
.cm-s-lkm .cm-operator{color:#89ddff}
.cm-s-lkm .cm-comment{color:#5c6a88;font-style:italic}
.cm-s-lkm .cm-string{color:#c3e88d}
.cm-s-lkm .cm-string-2{color:#f07178}
.cm-s-lkm .cm-meta,.cm-s-lkm .cm-qualifier{color:#ffcb6b}
.cm-s-lkm .cm-builtin{color:#82aaff}
.cm-s-lkm .cm-bracket{color:#89ddff}
.cm-s-lkm .cm-tag{color:#f07178}
.cm-s-lkm .cm-attribute{color:#ffcb6b}
.cm-s-lkm .cm-header{color:#82aaff;font-weight:600}
.cm-s-lkm .cm-link{color:#80cbc4;text-decoration:underline}
.cm-s-lkm .cm-error{color:#ff5370}
.cm-s-lkm .cm-searching{background:#ffcb6b44}
.CodeMirror-dialog{background:#131b2c!important;color:var(--tx);border-bottom:1px solid var(--line2)!important;padding:8px 12px!important;font-size:13px}
.CodeMirror-dialog input{background:var(--bg2);border:1px solid var(--line2)!important;border-radius:6px;color:var(--tx);padding:3px 8px;outline:none;font:13px var(--mono)}

/* visualizador de imagem */
.fm-view{position:fixed;inset:0;z-index:80;background:#05070cf2;display:flex;flex-direction:column}
.fm-view .vh{display:flex;align-items:center;gap:10px;padding:10px 14px;color:var(--tx);font-size:14px}
.fm-view .vh span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fm-view .vb{flex:1;display:flex;align-items:center;justify-content:center;min-height:0;position:relative;padding:10px 60px 30px}
.fm-view img{max-width:100%;max-height:100%;object-fit:contain;border-radius:6px;background:repeating-conic-gradient(#1a2336 0 25%,#121a2a 0 50%) 0 0/20px 20px}
.fm-view .nv{position:absolute;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;border:1px solid var(--line2);background:#131b2ccc;color:var(--tx);cursor:pointer;display:flex;align-items:center;justify-content:center}
.fm-view .nv:hover{background:var(--line2)}
.fm-view .nv.p{left:12px}.fm-view .nv.n{right:12px}

@media (max-width:1500px){.fm-tools .lbl{display:none}}
@media (max-width:900px){
  #fm{height:calc(100vh - 76px)}
  .fm{grid-template-columns:1fr;grid-template-rows:auto minmax(0,1fr);gap:8px}
  .fm-side{flex-direction:row;padding:6px;overflow-x:auto;gap:4px}
  .fm-side h3,.fm-disk,.fm-place small{display:none}
  .fm-search{width:150px}
  .fm-head,.fm-row{grid-template-columns:34px minmax(140px,1fr) 84px 0 0 0}
  .fm-head span:nth-child(n+4),.fm-row>span:nth-child(n+4){display:none}
}
@media (max-width:560px){
  .fm-top{flex-wrap:wrap}
  .fm-search{width:100%;order:3}
  .fm-row{height:44px}
  .fm-ed .eh .badge{display:none}
}
LKM_EOF_FMCSS
cat > "$DIR/app.css" <<'LKM_EOF_APPCSS'
/* LK Monitor - componentes das abas Sites e do app no celular */
.abtn{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:34px;padding:0 13px;border-radius:9px;border:1px solid var(--line2);background:var(--bg2);color:var(--tx);font:500 13px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;text-decoration:none;white-space:nowrap}
.abtn:hover{border-color:var(--mut)}
.abtn.pri{background:var(--pri);border-color:var(--pri);color:#fff}
.abtn.pri:hover{filter:brightness(1.1)}
.abtn.danger{background:var(--bad);border-color:var(--bad);color:#fff}
.abtn.sm{height:28px;padding:0 10px;font-size:12px;border-radius:7px}
.abtn:disabled{opacity:.5;cursor:default}
.abtn svg.i{width:15px;height:15px}
.lnk{background:none;border:0;color:var(--cpu);cursor:pointer;font:inherit;font-size:12.5px;padding:0}
.lnk:hover{text-decoration:underline}
.mono{font-family:var(--mono)}
code{font-family:var(--mono);font-size:.92em;background:var(--bg2);border:1px solid var(--line);border-radius:5px;padding:0 5px;color:var(--tx)}
select.fm-in{appearance:none;-webkit-appearance:none;padding-right:30px;background-image:linear-gradient(45deg,transparent 50%,var(--mut) 50%),linear-gradient(135deg,var(--mut) 50%,transparent 50%);background-position:calc(100% - 16px) 50%,calc(100% - 11px) 50%;background-size:5px 5px;background-repeat:no-repeat;cursor:pointer}
.fm-in.sm{height:32px;margin-top:0;font-size:12.5px;width:auto}
.seg{display:inline-flex;gap:3px;background:var(--bg2);border:1px solid var(--line);border-radius:9px;padding:3px;flex-wrap:wrap}
.seg button{background:none;border:0;color:var(--mut);font:500 12.5px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;padding:6px 11px;border-radius:6px;cursor:pointer}
.seg button:hover{color:var(--tx)}
.seg button.on{background:var(--line2);color:var(--tx)}
.seg button[hidden]{display:none}

/* sites */
#sites{display:grid;gap:16px}
.st{padding:0;overflow:hidden}
.st-top{display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.st-ttl{display:flex;align-items:baseline;gap:10px;flex:1;min-width:140px}
.st-ttl h2{font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--mut)}
.st-ttl span{font-size:12px;color:var(--dim)}
.st-ttl{flex-wrap:wrap;row-gap:2px}
.st-ttl h2{white-space:nowrap}
.st-tools{display:flex;align-items:center;gap:8px}
.st-search{position:relative;width:220px}
.st-search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--dim)}
.st-search input{width:100%;height:34px;background:var(--bg2);border:1px solid var(--line);border-radius:9px;color:var(--tx);padding:0 10px 0 32px;font-size:13px;outline:none}
.st-search input:focus{border-color:var(--cpu);box-shadow:0 0 0 3px #5b9cff22}
.st-ro{display:flex;gap:12px;align-items:flex-start;margin:14px 16px 0;padding:12px 14px;border-radius:10px;background:#f5b3011a;border:1px solid #f5b30144;color:#8a5a00;font-size:13px;line-height:1.5}
.st-ro svg{color:var(--warn);margin-top:2px}
.st-ro b{color:#6b4500}
.st-head,.st-row{display:grid;grid-template-columns:minmax(220px,1.7fr) minmax(170px,1fr) 100px 330px;align-items:center;gap:12px;padding:0 16px}
.st-head{height:34px;font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--dim);border-bottom:1px solid var(--line)}
.st-head .r,.st-row .r{text-align:right}
.st-head span:last-child{text-align:left;padding-left:8px}
.st-row{min-height:62px;border-bottom:1px solid #e9ecef;padding-top:8px;padding-bottom:8px}
.st-row:last-child{border-bottom:0}
.st-row:hover{background:#f5f7f9}
.st-site{display:flex;align-items:center;gap:12px;min-width:0}
.st-dot{width:9px;height:9px;border-radius:50%;background:var(--ok);box-shadow:0 0 8px #22c55e88;flex:none}
.st-row.off .st-dot{background:var(--dim);box-shadow:none}
.st-dn{min-width:0;display:flex;flex-direction:column;gap:2px}
.st-dn a{color:var(--tx);font-weight:600;font-size:14px;text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.st-dn a:hover{color:#2f8cdc;text-decoration:underline}
.st-row.off .st-dn a{color:var(--mut)}
.st-dn small{color:var(--dim);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.st-dn small .mono{font-size:11.5px}
.st-dn em{color:var(--warn);font-style:normal}
.st-tags{display:flex;gap:6px;flex-wrap:wrap}
.tag{font-size:11.5px;padding:2px 8px;border-radius:999px;border:1px solid var(--line2);color:var(--mut);background:var(--bg2);white-space:nowrap;max-width:160px;overflow:hidden;text-overflow:ellipsis}
.tag.t-laravel{color:#d4512f;border-color:#ff6b5a55;background:#ff6b5a14}
.tag.t-php{color:#5865d6;border-color:#8892f655;background:#8892f614}
.tag.t-proxy{color:#0f8a66;border-color:#2fd6a055;background:#2fd6a014}
.tag.t-ssl{color:#1b8a31;border-color:#22c55e55;background:#22c55e14}
.st-size{font-size:12.5px;color:var(--mut)}
.st-dim{color:var(--dim)}
.st-acts{display:flex;align-items:center;gap:2px;justify-content:flex-start}
.sw{display:inline-flex;align-items:center;gap:8px;background:none;border:1px solid transparent;border-radius:8px;color:var(--mut);font:500 12.5px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;padding:4px 8px;margin-right:4px;min-width:104px}
.sw i{width:30px;height:17px;border-radius:999px;background:var(--line2);position:relative;transition:background .2s;flex:none}
.sw i::after{content:"";position:absolute;left:2px;top:2px;width:13px;height:13px;border-radius:50%;background:#ffffff;transition:left .2s}
.sw.on{color:#1b8a31}
.sw.on i{background:var(--ok)}
.sw.on i::after{left:15px;background:#fff}
.sw:hover:not(:disabled){background:var(--bg2);border-color:var(--line)}
.sw:disabled{cursor:default;opacity:.7}
.st-empty{display:flex;flex-direction:column;align-items:center;gap:10px;padding:56px 20px;color:var(--dim);text-align:center;font-size:13.5px}
.st-empty svg.i{width:40px;height:40px;opacity:.5}
.st-empty b{color:var(--mut);font-size:15px}

/* diálogos de site */
.fm-dlg.nfd{max-width:500px}
.fm-dlg.xl{max-width:1100px;height:calc(100vh - 32px)}
.fm-dlg.xl .db{flex:1;min-height:0;display:flex;flex-direction:column}
.nf p{margin-bottom:10px}
.nf-l{color:var(--tx);font-size:13px;font-weight:600;margin-top:14px;display:flex;align-items:center;gap:8px}
.nf-l:first-child{margin-top:4px}
.nf-h{font-size:12.5px;color:var(--dim);margin-top:6px}
.nf-h.bad{color:#d93a2e}
.nf .seg{margin-top:8px}
.nf-err{color:#d93a2e;font-size:13px;margin-top:10px}
.nf-err:empty{display:none}
.nf-pre{margin-top:8px;max-height:180px;overflow:auto;background:#05070c;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:12px/1.5 var(--mono);color:#ffb4ab;white-space:pre-wrap;word-break:break-word}
.nf-box{margin-top:16px;padding:12px 14px;border:1px solid var(--line2);border-radius:10px;background:var(--bg2)}
.nf-box .nf-l:first-child{margin-top:0}
.nf-warn{display:flex;align-items:center;gap:8px;margin:8px 0 4px;color:var(--warn);font-size:12.5px}
.cpl{display:flex;align-items:center;gap:8px;margin-top:8px;background:#05070c;border:1px solid var(--line2);border-radius:9px;padding:6px 6px 6px 12px}
.cpl code{flex:1;min-width:0;background:none;border:0;padding:0;font-size:13px;overflow-x:auto;white-space:nowrap;color:#7ee787}
.cpl.col{flex-direction:column;align-items:stretch;padding:10px 12px}
.cpl pre{font:12.5px/1.6 var(--mono);color:#7ee787;white-space:pre-wrap;word-break:break-all}
.cpl.col .abtn{align-self:flex-end}

/* visualizador de logs */
.lv{display:flex;flex-direction:column;gap:10px;flex:1;min-height:0}
.lv-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.lv-bar .st-search{flex:1;min-width:150px;width:auto}
.lv-bar label.ck{margin-top:0}
.lv-file{font-size:12px;color:var(--dim);min-height:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lv-out{flex:1;min-height:200px;overflow:auto;margin:0;background:#05070c;border:1px solid var(--line);border-radius:10px;padding:10px 12px;font:12.5px/1.5 var(--mono);color:#cfd7e6;white-space:pre-wrap;word-break:break-word}
.lv-out .e{color:#ff8a80}
.lv-out .w{color:#ffd479}
.lv-out mark{background:#f5b30155;color:#fff;border-radius:2px}

/* instalar no celular */
.pw p{margin-bottom:10px}
.pw-step{display:flex;gap:12px;margin-top:14px}
.pw-step>b{flex:none;width:24px;height:24px;border-radius:50%;background:#5b9cff22;border:1px solid #5b9cff55;color:#2f8cdc;display:flex;align-items:center;justify-content:center;font-size:12px}
.pw-step>div{flex:1;min-width:0}
.pw-t{color:var(--tx);font-weight:600;margin-bottom:6px}
.pw-tabs{display:inline-flex;margin:2px 0 8px}
.pw-p[hidden]{display:none}
.pw-note{font-size:12.5px;color:var(--dim);margin-top:8px}
.pw-urls>div{display:flex;align-items:center;gap:8px;justify-content:space-between;padding:4px 0}
.pw-urls a{color:#2f8cdc;font-family:var(--mono);font-size:13px;word-break:break-all}

/* deploy e tarefas em segundo plano */
.dp-opts{display:flex;flex-direction:column;gap:2px;margin-top:10px;border:1px solid var(--line);border-radius:10px;padding:4px;background:var(--bg2)}
.dp-opt{display:flex;gap:10px;align-items:flex-start;padding:8px 10px;border-radius:7px;cursor:pointer}
.dp-opt:hover{background:#f2f5f8}
.dp-opt>input{accent-color:var(--cpu);width:16px;height:16px;margin-top:2px;flex:none}
.dp-opt b{color:var(--tx);font-weight:600;font-family:var(--mono);font-size:13px}
.dp-opt small{display:block;color:var(--dim);font-size:12px}
.dp-opt .warn,.nf-h .warn{color:var(--warn)}
.fm-dlg label.ck.sub{margin-top:6px;font-size:12.5px;color:var(--mut)}
.dp-hist{display:flex;flex-direction:column;gap:4px;margin-top:8px;max-height:170px;overflow:auto}
.dp-h{display:flex;align-items:center;gap:10px;background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:6px 10px;color:var(--tx);font:13px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;text-align:left}
.dp-h:hover{border-color:var(--line2)}
.dp-h small{color:var(--dim);margin-left:auto;font-size:12px}
.jst{font-size:11.5px;font-weight:600;padding:2px 9px;border-radius:999px;border:1px solid var(--line2);color:var(--mut);white-space:nowrap}
.jst.running,.jst.queued{color:#2f8cdc;border-color:#5b9cff66;background:#5b9cff14}
.jst.ok{color:#1b8a31;border-color:#22c55e55;background:#22c55e14}
.jst.error,.jst.interrupted{color:#d93a2e;border-color:#ef444466;background:#ef444414}
.jv{display:flex;flex-direction:column;gap:10px;flex:1;min-height:0}
.jv-head{display:flex;align-items:center;gap:10px;font-size:12.5px}
.jv-res{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:9px;font-size:13.5px}
.jv-res.ok{background:#22c55e14;border:1px solid #22c55e55;color:#1b7a2c}
.jv-res.ok svg{color:var(--ok)}
.jv-res.error,.jv-res.interrupted{background:#ef444414;border:1px solid #ef444455;color:#b3261e}
.jv-res.error svg,.jv-res.interrupted svg{color:var(--bad)}
.jv-res b{color:inherit}
.jv-steps{display:flex;flex-wrap:wrap;gap:6px}
.jv .lv-out{white-space:pre;word-break:normal;overflow-x:auto}
.jstep{display:inline-flex;align-items:center;gap:7px;padding:4px 10px;border-radius:999px;border:1px solid var(--line);background:var(--bg2);font-size:12.5px;color:var(--mut)}
.jstep small{color:var(--dim)}
.jstep.running{color:#1f6fb5;border-color:#5b9cff66}
.jstep.ok{color:var(--tx)}.jstep.ok svg{color:var(--ok)}
.jstep.error{color:#d93a2e;border-color:#ef444466}.jstep.error svg{color:var(--bad)}
.jstep.skipped,.jstep.canceled{opacity:.6}
.jdot{width:8px;height:8px;border-radius:50%;border:1.5px solid var(--dim);display:inline-block}
.jdot.sk{background:var(--dim)}
.jspin{width:12px;height:12px;border-radius:50%;border:2px solid #5b9cff44;border-top-color:var(--cpu);display:inline-block;animation:jsp .8s linear infinite}
@keyframes jsp{to{transform:rotate(360deg)}}

/* bancos */
#bancos{display:grid;gap:16px}
.db-row{grid-template-columns:minmax(220px,1.5fr) minmax(160px,1.3fr) 100px 190px}
.db-ico{width:30px;height:30px;border-radius:8px;background:#5b9cff1a;color:#2f8cdc;display:flex;align-items:center;justify-content:center;flex:none}
.db-ico.lite{background:#2fd6a01a;color:#0f8a66}
.db-name{background:none;border:0;padding:0;color:var(--tx);font:600 14px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.db-name:hover{color:#2f8cdc;text-decoration:underline}
.st-dn b.mono{font-size:13.5px;color:var(--tx)}
.tag svg.i{width:11px;height:11px;margin-right:4px;vertical-align:-1px}
.db-row .ib .lbl{font-size:12.5px}
.dbv{position:fixed;inset:0;z-index:70;background:#eef0f3;display:flex;flex-direction:column}
.dbv-h{display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--line);background:#f7f8fa;color:var(--mut)}
.dbv-t{display:flex;flex-direction:column;min-width:0;flex:1}
.dbv-t b{color:var(--tx);font-size:14.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dbv-t small{color:var(--dim);font-size:12px;font-family:var(--mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dbv-sel{display:none;max-width:45%}
.dbv-b{flex:1;min-height:0;display:grid;grid-template-columns:240px minmax(0,1fr)}
.dbv-side{border-right:1px solid var(--line);padding:10px;display:flex;flex-direction:column;gap:8px;min-height:0;background:#f7f8fa}
.dbv-side .st-search{width:auto}
.dbv-tl{overflow:auto;display:flex;flex-direction:column;gap:1px;min-height:0}
.dbv-ti{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:7px;border:1px solid transparent;background:none;color:var(--mut);font:13px system-ui,-apple-system,"Segoe UI",Roboto,Ubuntu,sans-serif;cursor:pointer;text-align:left}
.dbv-ti span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dbv-ti small{color:var(--dim);font-size:11.5px}
.dbv-ti:hover{background:var(--bg2);color:var(--tx)}
.dbv-ti.on{background:#5b9cff1a;border-color:#5b9cff44;color:#1f6fb5}
.dbv-main{display:flex;flex-direction:column;min-width:0;min-height:0;padding:10px 14px;gap:10px}
.dbv-tabs{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12.5px}
.dbv-pane{display:flex;flex-direction:column;gap:10px;flex:1;min-height:0}
.dbv-pane[hidden]{display:none}
.dbv-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.dbv-bar .st-search{flex:1;min-width:160px;width:auto}
.dbv-bar .sp{flex:1}
.dbv-pg{display:flex;align-items:center;gap:4px;font-size:12.5px;color:var(--mut)}
.dbv-grid{flex:1;min-height:0;overflow:auto;border:1px solid var(--line);border-radius:10px;background:var(--card)}
.dbv-grid.busy{opacity:.6}
.dbv-grid table{width:max-content;min-width:100%;font-size:12.5px}
.dbv-grid th{position:sticky;top:0;background:#f2f4f6;padding:8px 10px;border-bottom:1px solid var(--line2);text-transform:none;letter-spacing:0;font-size:12px;color:var(--mut);font-family:var(--mono)}
.dbv-grid th[data-sort]{cursor:pointer}
.dbv-grid th[data-sort]:hover{color:var(--tx)}
.dbv-grid td{padding:6px 10px;max-width:360px;overflow:hidden;text-overflow:ellipsis;font-family:var(--mono);font-size:12px;border-top:1px solid #e9ecef}
.dbv-grid tr:hover td{background:#f5f7f9}
.dbv-grid td.nul{color:var(--dim);font-style:italic}
.dbv-sql{width:100%;min-height:130px;height:24vh;resize:vertical;background:#05070c;border:1px solid var(--line2);border-radius:10px;color:#dbe4f3;padding:10px 12px;font:13px/1.5 var(--mono);outline:none;tab-size:2}
.dbv-sql:focus{border-color:var(--cpu);box-shadow:0 0 0 3px #5b9cff22}
.writing .dbv-sql{border-color:#ef444488}
.dbv-bar .abtn small{opacity:.7;font-size:11px}
.sw.danger.on{color:#d93a2e}.sw.danger.on i{background:var(--bad)}
.dbv-res{font-size:12.5px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.dbv-res.ok{color:#1b8a31}.dbv-res.warn{color:var(--warn)}.dbv-res.err .e{color:#d93a2e}
/* backups */
.bk-auto{display:flex;align-items:center;gap:10px;margin:12px 0;padding:10px 12px;border-radius:9px;background:var(--bg2);border:1px solid var(--line);font-size:13px;color:var(--mut)}
.bk-auto svg{color:var(--disk)}
.bk-auto span{flex:1}
.bk-list{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:10px;overflow:hidden;max-height:46vh;overflow-y:auto}
.bk-row{display:grid;grid-template-columns:minmax(0,1fr) auto 80px auto;align-items:center;gap:10px;padding:8px 8px 8px 12px;border-top:1px solid #e9ecef}
.bk-row:first-child{border-top:0}
.bk-row:hover{background:#f5f7f9}
.bk-main{display:flex;flex-direction:column;min-width:0}
.bk-main b{color:var(--tx);font-size:13.5px}
.bk-main small{color:var(--dim);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.bk-size{font-size:12.5px;color:var(--mut);text-align:right}
.bk-acts{display:flex;gap:2px}
a.ib{text-decoration:none}

/* config */
#config{display:grid;gap:16px}
.cf-grid{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(min(100%,480px),1fr));align-items:start}
.cf-card .ct h2{display:flex;align-items:center;gap:8px}
.cf-card .ct h2 svg{color:var(--mut)}
.cf-rule{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-top:1px solid var(--line)}
.cf-rule:first-child{border-top:0;padding-top:0}
.cf-rule .sw{margin:0;min-width:0;padding:2px 0;flex:none}
.cf-rt{color:var(--tx);font-size:13.5px;line-height:2.2}
.cf-rule small{display:block;color:var(--dim);font-size:12px;line-height:1.4}
.cf-num{width:64px;text-align:center;margin:0 2px;padding:0 6px;display:inline-block;height:30px;font-family:var(--mono)}
.fm-in.sm[type=time]{width:auto;display:inline-block;height:30px;margin:0 2px;color-scheme:dark}
.cf-rep{padding-top:10px;border-top:1px solid var(--line);color:var(--mut);font-size:13px;line-height:2.2}
.cf-ch{padding:12px 0;border-top:1px solid var(--line)}
.cf-ch:first-child{border-top:0;padding-top:0}
.cf-chh{display:flex;align-items:center;gap:10px;margin-bottom:6px}
.cf-chh .sw{margin:0;min-width:0;padding:2px 0}
.cf-chh b{flex:1;color:var(--tx);font-size:14px}
.cf-f{margin-top:8px;display:flex;flex-direction:column}
.cf-f label{font-size:12px;color:var(--mut)}
.cf-f label small{color:var(--dim)}
.cf-f .fm-in{margin-top:4px}
.cf-row{display:flex;gap:10px;flex-wrap:wrap}
.cf-ta{height:auto;padding:8px 12px;resize:vertical;line-height:1.5;font-size:12.5px}
.cf-h{display:block;margin-top:8px;color:var(--dim);font-size:12px;line-height:1.5}
.cf-alt{display:inline-block;margin-top:10px;font-size:12px}
#wGowa[hidden],#wHook[hidden]{display:none}
.wa-st{display:flex;align-items:center;flex-wrap:wrap;gap:6px 10px;margin:4px 0 2px;padding:9px 12px;border-radius:9px;background:var(--bg2);border:1px solid var(--line);font-size:13px;color:var(--mut)}
.wa-st>i{width:9px;height:9px;border-radius:50%;background:var(--dim);flex:none}
.wa-st b{color:var(--tx);font-weight:600}
.wa-st a{color:#2f8cdc;font-size:12.5px}
.wa-st .lnk{margin-left:auto;color:var(--mut);display:inline-flex}
.wa-st small{flex-basis:100%;color:var(--dim);font-size:12px}
.wa-st.ok{border-color:#22c55e55;background:#22c55e10}.wa-st.ok>i{background:var(--ok);box-shadow:0 0 8px #22c55e88}.wa-st.ok b{color:#1b8a31}
.wa-st.er{border-color:#ef444455;background:#ef444410}.wa-st.er>i{background:var(--bad)}.wa-st.er b{color:#d93a2e}
.cf-save{display:flex;align-items:center;justify-content:flex-end;gap:12px}
.cf-save.in{margin-top:14px}
.cf-dirty{color:var(--warn);font-size:12.5px}.cf-ok{color:var(--ok);font-size:12.5px}
.cf-sites{display:flex;flex-wrap:wrap;gap:4px 18px}
.cf-sites label.ck{display:flex;align-items:center;gap:8px;margin-top:6px;cursor:pointer;color:var(--tx);font-size:13px}
.cf-sites input,.cf-hist input{accent-color:var(--cpu)}
.cf-hist{max-height:420px;overflow:auto;display:flex;flex-direction:column}
.cf-hi{display:flex;gap:10px;padding:8px 0;border-top:1px solid var(--line);font-size:13px;color:var(--tx)}
.cf-hi:first-child{border-top:0}
.cf-hi svg{flex:none;margin-top:2px}
.cf-hi.alert svg,.cf-hi.repeat svg{color:var(--bad)}.cf-hi.ok svg{color:var(--ok)}
.cf-hi small{color:var(--dim);font-size:11.5px}
.cf-hi small .ok{color:#1b8a31}.cf-hi small .er{color:#d93a2e}
@media (max-width:900px){
  .db-row{grid-template-columns:minmax(0,1fr) auto}
  .db-row .ib .lbl{display:none}
  .dbv-b{grid-template-columns:1fr}
  .dbv-side{display:none}
  .dbv-sel{display:block}
}
@media (max-width:560px){
  .st-tools{flex-wrap:wrap}
  .st-tools .seg{width:100%}
  .st-tools .seg button{flex:1}
  .dbv-main{padding:8px}
  .dbv-sel{max-width:50%}
}
@media (max-width:900px){
  .st-head{display:none}
  .st-row{grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"site size" "tags tags" "acts acts";gap:8px 12px;padding:12px 14px}
  .st-site{grid-area:site}.st-tags{grid-area:tags}.st-size{grid-area:size}.st-acts{grid-area:acts;justify-content:flex-start;flex-wrap:wrap}
  .sw{margin-right:auto;padding-left:0}
}
@media (max-width:560px){
  .st-top{padding:12px}
  .st-tools{width:100%}
  .st-search{flex:1;width:auto}
  .st-tools .abtn.pri span{display:none}
  .st-ro{margin:12px 12px 0}
  .fm-dlg.xl{height:calc(100vh - 16px)}
  .fm-ov{padding:8px}
  .lv-bar .seg{width:100%}
  .bk-row{grid-template-columns:minmax(0,1fr) auto;row-gap:4px}
  .bk-row .tag{justify-self:start}
}
@media (max-width:600px){#fm{height:calc(100vh - 122px)}}

/* ------------------------------------------------------------ terminal completo (term.js) */
#v-terminal{align-content:start;grid-template-columns:minmax(0,1fr)}
#v-terminal>*{min-width:0}
#xt[hidden],#tSimple[hidden]{display:none!important}
.tmode{font-size:11px;font-weight:500;color:var(--dim);text-transform:none;letter-spacing:0;margin-left:6px}
#term .ct{gap:10px}#term .ct .ubadge{margin-left:auto}
.xt{display:flex;flex-direction:column;min-width:0;width:100%;background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;min-height:260px;height:calc(100vh - 110px)}
.xt.xt-full{position:fixed;left:0;right:0;top:0;z-index:40;border-radius:0;border:0;height:100vh}
body.xt-noscroll{overflow:hidden}
.xt-bar{display:flex;align-items:center;gap:2px;min-width:0;padding:6px 8px;border-bottom:1px solid var(--line);background:var(--bg2);min-height:44px}
.xt-bar .sp{flex:1}
.xt-bar .ib.on{background:var(--line2);color:var(--tx)}
.xt-tabs{display:flex;gap:4px;min-width:0;overflow-x:auto;scrollbar-width:none}
.xt-tabs::-webkit-scrollbar{display:none}
.xt-tab{display:flex;align-items:center;gap:7px;height:30px;padding:0 4px 0 10px;border-radius:8px;border:1px solid transparent;color:var(--mut);font:12.5px var(--mono);cursor:pointer;white-space:nowrap;max-width:240px;flex:none;user-select:none}
.xt-tab span{overflow:hidden;text-overflow:ellipsis}
.xt-tab:hover{color:var(--tx);background:var(--card)}
.xt-tab.cur{background:#05070c;border-color:var(--line2);color:var(--tx)}
.xt-tab .d{width:7px;height:7px;border-radius:50%;flex:none;background:var(--dim)}
.xt-tab .d.on{background:var(--ok);box-shadow:0 0 6px #22c55e88}
.xt-tab .d.wait{background:var(--warn)}
.xt-tab .d.off{background:var(--bad)}
.xt-tab .x{width:22px;height:22px;border:0;background:none;color:var(--dim);border-radius:6px;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0}
.xt-tab .x:hover{background:#ef444422;color:#ff8a80}
.xt-tab .x svg{width:13px;height:13px}
.xt-new{flex:none}
.xt-wrap{flex:1;min-height:0;position:relative;background:#05070c}
.xt-host{position:absolute;inset:0}
.xt-term{position:absolute;inset:6px 4px 4px 10px;visibility:hidden}
.xt-term.on{visibility:visible}
.xt-term .xterm{height:100%}
.xt-term .xterm-viewport{scrollbar-width:thin;scrollbar-color:#283654 transparent}
.xt-term .xterm-viewport::-webkit-scrollbar{width:9px}
.xt-term .xterm-viewport::-webkit-scrollbar-thumb{background:#283654;border-radius:6px}
.xt-msg{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#05070cd9;z-index:3;padding:20px}
.xt-msg[hidden]{display:none}
.xt-mbox{background:var(--card);border:1px solid var(--line2);border-radius:12px;padding:18px 20px;max-width:420px;text-align:center;box-shadow:0 20px 60px #0009}
.xt-mbox p{color:var(--tx);margin-bottom:14px;line-height:1.5}
.xt-keys{display:none;gap:5px;min-width:0;padding:6px 8px;border-top:1px solid var(--line);background:var(--bg2);overflow-x:auto;scrollbar-width:none;flex:none}
.xt-keys::-webkit-scrollbar{display:none}
.xt-keys button{flex:none;min-width:40px;height:34px;padding:0 10px;border-radius:8px;border:1px solid var(--line2);background:var(--card);color:var(--tx);font:500 13px var(--mono);cursor:pointer;touch-action:manipulation}
.xt-keys button:active{background:var(--line2)}
.xt-keys button.on{background:var(--cpu);border-color:var(--cpu);color:#fff}
.xt-foot{display:flex;align-items:center;gap:10px;padding:6px 12px;border-top:1px solid var(--line);font-size:12px;color:var(--dim);flex:none;min-width:0}
.xt-foot .sp{flex:1}
.xt-foot .ubadge{flex:none}
.xt-hint{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.xt-load,.xt-fail{max-width:560px;margin:40px auto;color:var(--mut)}
.xt-fail b{display:block;color:var(--tx);margin-bottom:8px}
.xt-fail p{margin-bottom:14px;line-height:1.5}
.xt-paste{width:100%;min-height:150px;margin-top:10px;font:13px var(--mono);resize:vertical}
@media (pointer:coarse){.xt-keys{display:flex}}
@media (max-width:900px){.xt-bar .ib .lbl{display:none}.xt-hint{display:none}}
@media (max-width:600px){.xt{border-radius:10px}.xt-bar{padding:5px 6px}.xt-tab{max-width:150px;padding-left:8px}.xt-term{inset:4px 2px 2px 6px}}

/* ações do sistema (Painel) */
.sysact{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}
.sysact .abtn svg.i{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.sysact .sy-off:hover:not(:disabled){border-color:var(--bad);color:#d93a2e}
.sy-busy{font-size:12px;color:var(--warn)}
.sy-pre{margin:0;max-height:260px;overflow:auto;background:#05070c;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:12px/1.5 var(--mono);color:#ffb4ab;white-space:pre-wrap;word-break:break-word}
.sy-warn{margin-top:10px;padding:8px 10px;border-radius:8px;background:#f59e0b14;border:1px solid #f59e0b44;color:#9a6700;font-size:13px}
.sy-note{margin-top:10px;color:var(--mut);font-size:12.5px}
.sy-lbl{margin-top:14px;margin-bottom:6px;font-size:12px;color:var(--mut)}

/* App Store (aba Apps) — tabela no estilo clássico */
#apps{display:grid;gap:14px}
.ap{padding:0;overflow:hidden}
.ap-tabs{display:flex;flex-wrap:wrap;border-bottom:1px solid var(--line);padding:0 8px}
.ap-tabs button{background:none;border:0;border-bottom:2px solid transparent;padding:12px 12px 10px;cursor:pointer;color:var(--mut);font:inherit;font-size:13px;white-space:nowrap}
.ap-tabs button:hover{color:var(--tx)}
.ap-tabs button.on{color:var(--ok);border-bottom-color:var(--ok);font-weight:500}
.ap-tool{display:flex;align-items:center;gap:8px;padding:10px 16px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--mut);flex-wrap:wrap}
.ap-tool .sp{flex:1}
.ap-q{height:30px;border:1px solid var(--line2);border-radius:3px;padding:0 10px;font:inherit;font-size:13px;width:220px;max-width:100%;background:#fff;color:var(--tx);outline:none}
.ap-q:focus{border-color:var(--ok)}
#apMsg .st-ro,#apMsg .ap-busy{margin:12px 16px 0}
#apMsg:not(:empty){padding-bottom:12px;border-bottom:1px solid var(--line)}
.ap-busy{display:flex;align-items:center;gap:10px;padding:9px 14px;border-radius:3px;background:#ecf5fd;border:1px solid #a9cdee;font-size:13px}
.ap-busy span{flex:1}
.ap-tw{overflow-x:auto}
.ap-t{width:100%;border-collapse:collapse;font-size:13px}
.ap-t th{background:var(--bg2);color:var(--mut);font-weight:500;text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);white-space:nowrap;font-size:12.5px}
.ap-t th:first-child,.ap-t td:first-child{padding-left:16px}
.ap-t th:last-child,.ap-t td:last-child{padding-right:16px}
.ap-t td{padding:10px 12px;border-top:1px solid var(--line);vertical-align:middle}
.ap-t tbody tr:first-child td{border-top:0}
.ap-t tbody tr:hover td{background:#fafbfc}
.ap-t .r{text-align:right}
.ap-empty{padding:28px!important;text-align:center;color:var(--mut)}
.ap-n{display:flex;align-items:center;gap:10px;min-width:170px}
.ap-n b{font-weight:500;display:block;white-space:nowrap}
.ap-n small{display:block;color:var(--mut);font-size:11.5px;font-family:var(--mono)}
.ap-logo{width:34px;height:34px;border-radius:6px;flex:none;box-shadow:0 0 0 1px #0000000f;object-fit:cover}
.ap-logo.ini,.sw2 .ini{display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:13px}
.ap-d{color:var(--mut);min-width:260px;line-height:1.45}
.ap-note{margin-top:4px;font-size:12px;color:#1f6fb5}
.ap-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:6px}
.ap-st{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;color:var(--mut)}
.ap-st b{width:7px;height:7px;border-radius:50%}
.ap-st.on{color:var(--ok)}.ap-st.on b{background:var(--ok)}
.ap-st.off{color:var(--bad)}.ap-st.off b{background:var(--bad)}
.ap-st.ok{color:var(--ok)}
.ap-st.run{color:var(--cpu)}
.tag.ap-need{color:#9a6700;border-color:#f5cf8c;background:#fff6e5}
.tag.ap-fail{color:var(--bad);border-color:#f3c0bb;background:#fdecea;cursor:pointer;font-family:inherit}
.ap-acts{white-space:nowrap}
.ap-acts .lnk{background:none;border:0;padding:0;color:var(--cpu);cursor:pointer;font:inherit;font-size:13px;text-decoration:none}
.ap-acts .lnk:hover{text-decoration:underline}
.ap-acts .lnk:disabled{color:var(--dim);cursor:default;text-decoration:none}
.ap-sep{color:var(--line2);margin:0 7px}
@media (max-width:600px){.ap-q{width:100%}.ap-d{min-width:200px}}

/* áreas escuras (terminal, editor, visualizador): tokens do tema escuro */
.fm-ed,.fm-view,#xt,.xt-wrap,.term,.tin,.lv-out,.cpl,.nf-pre,.sy-pre{--bg:#0a0e17;--bg2:#0f1522;--card:#121a2a;--line:#1e2940;--line2:#283654;--tx:#e6ebf5;--mut:#8592ad;--dim:#56627d;color-scheme:dark}

/* aba Internet (Cloudflare Tunnel) */
#internet{display:grid;gap:14px}
.cf-step{display:flex;align-items:center;gap:14px;padding:12px 0;border-top:1px solid var(--line)}
.cf-step:first-child{border-top:0;padding-top:0}
.cf-n{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:none;background:var(--bg2);border:1px solid var(--line2);color:var(--mut);font-size:13px}
.cf-step.done .cf-n{background:var(--ok);border-color:var(--ok);color:#fff}
.cf-n svg{width:15px;height:15px}
.cf-sb{flex:1;min-width:0}
.cf-st{font-weight:600}
.cf-sd{color:var(--mut);font-size:13px}
.cf-sa{flex:none}
.cf-on{color:var(--ok);font-weight:500}.cf-off{color:var(--bad);font-weight:500}
.cf-tip{display:flex;gap:8px;align-items:flex-start;margin-top:10px;padding:9px 12px;border-radius:3px;background:#ecf5fd;border:1px solid #a9cdee;font-size:12.5px;color:#1f5f99}
.cf-tip svg{flex:none;width:15px;height:15px;margin-top:2px}
.cf-form{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.cf-form label{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--mut);min-width:0}
.cf-form label.grow{flex:1;min-width:220px}
.cf-form .fm-in{margin-top:0;height:34px;min-width:180px}
.cf-form label.grow .fm-in{width:100%}
#cfWarn .sy-warn,#cfWarn .cf-note{margin:0 0 12px}
.cf-tw{overflow-x:auto;margin:0 -16px -16px;border-top:1px solid var(--line)}
.cf-t{width:100%;border-collapse:collapse;font-size:13px}
.cf-t th{background:var(--bg2);color:var(--mut);font-weight:500;text-align:left;padding:8px 12px;border-bottom:1px solid var(--line);white-space:nowrap}
.cf-t td{padding:9px 12px;border-top:1px solid var(--line);vertical-align:middle}
.cf-t tbody tr:first-child td{border-top:0}
.cf-t th:first-child,.cf-t td:first-child{padding-left:16px}.cf-t th:last-child,.cf-t td:last-child{padding-right:16px}
.cf-t .r{text-align:right}
.cf-t small{display:block;color:var(--dim);font-size:11.5px}
.cf-host{color:var(--cpu);text-decoration:none;font-weight:500;word-break:break-all}.cf-host:hover{text-decoration:underline}
.cf-acts{white-space:nowrap}
.cf-acts .lnk,.cf-blk .lnk{background:none;border:0;padding:0;color:var(--cpu);cursor:pointer;font:inherit;font-size:13px}
.cf-acts .lnk.red{color:var(--bad)}
.cf-acts .lnk:disabled{color:var(--dim);cursor:default}
.cf-quick{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid #9ad3a6;background:#e9f6ec;border-radius:3px;margin-bottom:10px;flex-wrap:wrap}
.cf-quick .grow{flex:1;min-width:0;display:flex;flex-direction:column}
.cf-quick small{color:var(--mut);font-size:12px}
.cf-note{font-size:12.5px;color:var(--mut)}
.cf-blk{display:flex;align-items:center;gap:8px;padding:8px 12px;margin-bottom:10px;border-radius:3px;background:#fdecea;border:1px solid #f3c0bb;color:#b3261e;font-size:13px}
.cf-blk span{flex:1}.cf-blk svg{width:15px;height:15px}
.cf-ol{margin:0 0 14px;padding-left:20px;display:grid;gap:4px}
.cf-big{width:100%;height:42px;font-size:14px;margin-bottom:12px}
.cf-wait{display:flex;align-items:center;gap:10px;margin-bottom:10px;font-size:13px}
.cf-ok svg{color:var(--ok)}
@media (max-width:600px){.cf-step{flex-wrap:wrap}.cf-sa{width:100%;padding-left:42px}}
.cf-form label[hidden]{display:none}
#cfBlocked:empty{display:none}

/* 2FA */
.tfa-on,.tfa-off{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.tfa-on .grow,.tfa-off .grow{flex:1;min-width:240px;font-size:13px;color:var(--mut);line-height:1.5}
.tfa-on .grow b{color:var(--ok)}
.tfa-on .grow small{display:block;font-size:12px}
.tfa-on>svg{width:22px;height:22px;color:var(--ok);flex:none}
.tfa-qr{display:flex;justify-content:center;margin:4px 0 10px;min-height:120px;align-items:center}
.tfa-qr svg{width:200px;height:200px;max-width:100%;background:#fff;border:1px solid var(--line);border-radius:4px}
.tfa-key{display:flex;align-items:center;justify-content:center;gap:8px;margin:6px 0 14px;flex-wrap:wrap}
.tfa-key code{font-size:14px;padding:4px 8px;word-break:break-all}
.pw-l{display:block;font-size:12.5px;color:var(--mut);margin-bottom:10px}.pw-l input{width:100%;margin-top:4px}
.pw-c{display:flex;gap:8px;align-items:flex-start;font-size:13px;margin:4px 0 6px;line-height:1.45}
.tfa-in{text-align:center;font:600 22px var(--mono)!important;letter-spacing:.35em;height:46px!important}
.tfa-codes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}
.tfa-codes code{font-size:15px;padding:8px;text-align:center}
LKM_EOF_APPCSS
cat > "$DIR/sites.js" <<'LKM_EOF_SITESJS'
/* LK Monitor - aba Sites (VirtualHosts do Apache) */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const { E, qs, qsa, toast, fail, dialog, confirmDlg, menu, svg, copyText, fsize } = U;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const TOKEN = C0.token || '';
  const RW = C0.user === 'root';
  const TYPE = { php: 'PHP', laravel: 'Laravel', proxy: 'Proxy' };
  const S = { sites: [], php: [], mysql: false, ip: '', loaded: false, error: '', filter: '', sizes: {}, busy: false };
  let root, inited = false;

  async function api(act, body) {
    let r;
    try {
      r = await fetch('?sites=' + act, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': TOKEN }, body: JSON.stringify(body || {}) });
    } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do servidor (' + r.status + ')'); }
    if (!d.ok) { const er = new Error(d.error || 'Erro desconhecido'); er.detail = d.detail || ''; er.data = d; throw er; }
    return d;
  }
  const errHtml = e => E(e.message) + (e.detail ? '<pre class="nf-pre">' + E(e.detail) + '</pre>' : '');
  const siteUrl = s => (s.ssl ? 'https://' : 'http://') + s.domain + '/';
  const hostsLine = s => (S.ip || '127.0.0.1') + ' ' + s.domain + (s.aliases.includes('www.' + s.domain) ? ' www.' + s.domain : '');

  /* ------------------------------------------------------------ montagem */
  function build() {
    root = qs('#sites');
    const why = C0.user ? 'o painel roda comandos como <b>' + E(C0.user) + '</b> (sem root)' : 'o terminal do painel está desativado';
    root.innerHTML =
      '<div class="card st">' +
      '<div class="st-top"><div class="st-ttl"><h2>Sites</h2><span id="stCount"></span></div>' +
      '<div class="st-tools"><div class="st-search">' + svg('search') + '<input id="stQ" placeholder="Filtrar sites" spellcheck="false" autocomplete="off"></div>' +
      '<button class="abtn" data-a="reload" title="Atualizar">' + svg('refresh') + '</button>' +
      (RW ? '<button class="abtn pri" data-a="new">' + svg('plus') + '<span>Novo site</span></button>' : '') + '</div></div>' +
      (RW ? '' : '<div class="st-ro">' + svg('lock') + '<div><b>Somente leitura.</b> Como ' + why + ', os sites aparecem só para consulta. Para criar, ligar/desligar e remover sites por aqui, rode <code>sudo lk</code> › opção 33 › 1 e escolha <b>root</b> no acesso do terminal.</div></div>') +
      '<div class="st-head"><span>Site</span><span>Tipo</span><span class="r">Tamanho</span><span class="r">Ações</span></div>' +
      '<div id="stList" class="st-list"></div></div>';
    root.addEventListener('click', onClick);
    qs('#stQ').addEventListener('input', e => { S.filter = e.target.value.trim().toLowerCase(); render(); });
  }

  async function load(quiet) {
    if (S.busy) return;
    S.busy = true;
    if (!quiet && !S.loaded) qs('#stList').innerHTML = '<div class="st-empty">Carregando sites…</div>';
    try {
      const d = await api('list');
      Object.assign(S, { sites: d.sites, php: d.php, mysql: d.mysql, ip: d.ip, loaded: true, error: '' });
    } catch (e) { S.error = e.message; S.loaded = true; }
    finally { S.busy = false; }
    render();
  }

  function render() {
    const list = qs('#stList');
    if (!list) return;
    if (S.error) { list.innerHTML = '<div class="fm-err">' + E(S.error) + '</div>'; qs('#stCount').textContent = ''; return; }
    const v = S.sites.filter(s => !S.filter || (s.domain + ' ' + s.aliases.join(' ') + ' ' + s.root + ' ' + s.type).toLowerCase().includes(S.filter));
    const on = S.sites.filter(s => s.on).length;
    qs('#stCount').textContent = S.sites.length ? S.sites.length + (S.sites.length === 1 ? ' site' : ' sites') + ' · ' + on + ' ligado' + (on === 1 ? '' : 's') : '';
    if (!S.sites.length) {
      list.innerHTML = '<div class="st-empty">' + svg('globe') + '<b>Nenhum site criado ainda</b>' + (RW ? '<span>Crie o primeiro com o botão <b>Novo site</b>.</span><button class="abtn pri" data-a="new">' + svg('plus') + '<span>Novo site</span></button>' : '') + '</div>';
      return;
    }
    if (!v.length) { list.innerHTML = '<div class="st-empty">Nenhum site corresponde ao filtro.</div>'; return; }
    list.innerHTML = v.map(rowHtml).join('');
  }

  function rowHtml(s) {
    const al = s.aliases.filter(a => a !== s.domain);
    const size = S.sizes[s.name];
    const sizeHtml = size === 'busy' ? '<span class="st-dim">calculando…</span>' : size != null ? '<span class="num">' + fsize(size) + '</span>' : '<button class="lnk" data-a="size">calcular</button>';
    const tags = '<span class="tag t-' + s.type + '">' + TYPE[s.type] + '</span>' +
      (s.php ? '<span class="tag">PHP ' + E(s.php) + '</span>' : '') +
      (s.proxy ? '<span class="tag mono" title="' + E(s.proxy) + '">→ ' + E(s.proxy.replace(/^https?:\/\/(127\.0\.0\.1|localhost)/, '').replace(/\/$/, '')) + '</span>' : '') +
      (s.ssl ? '<span class="tag t-ssl">SSL</span>' : '');
    return '<div class="st-row' + (s.on ? '' : ' off') + '" data-n="' + E(s.name) + '">' +
      '<div class="st-site"><span class="st-dot" title="' + (s.on ? 'Ligado' : 'Desligado') + '"></span><div class="st-dn">' +
      '<a href="' + E(siteUrl(s)) + '" target="_blank" rel="noopener">' + E(s.domain) + '</a>' +
      '<small>' + (al.length ? E(al.join(', ')) + ' · ' : '') + '<span class="mono">' + E(s.root || '—') + '</span>' + (s.exists || s.type === 'proxy' ? '' : ' <em>(pasta não existe)</em>') + '</small></div></div>' +
      '<div class="st-tags">' + tags + '</div>' +
      '<div class="st-size r">' + sizeHtml + '</div>' +
      '<div class="st-acts">' +
      '<button class="sw' + (s.on ? ' on' : '') + '" data-a="toggle" title="' + (s.on ? 'Ligado: clique para desligar' : 'Desligado: clique para ligar') + '"' + (RW ? '' : ' disabled') + '><i></i><span>' + (s.on ? 'Ligado' : 'Desligado') + '</span></button>' +
      '<button class="ib" data-a="open" title="Abrir o site em nova aba">' + svg('open') + '</button>' +
      '<button class="ib" data-a="folder" title="Abrir a pasta no gerenciador de arquivos">' + svg('folder') + '</button>' +
      (RW && s.type === 'laravel' ? '<button class="ib" data-a="deploy" title="Deploy">' + svg('rocket') + '</button>' : '') +
      '<button class="ib" data-a="log" title="Ver logs">' + svg('log') + '</button>' +
      (RW ? '<button class="ib" data-a="backups" title="Backups">' + svg('archive') + '</button>' : '') +
      '<button class="ib" data-a="more" title="Mais ações">' + svg('more') + '</button>' +
      '</div></div>';
  }

  function siteOf(el) { const r = el.closest('[data-n]'); return r ? S.sites.find(s => s.name === r.dataset.n) : null; }

  function onClick(e) {
    const b = e.target.closest('[data-a]');
    if (!b || b.disabled) return;
    const a = b.dataset.a, s = siteOf(b);
    if (a === 'reload') return load();
    if (a === 'new') return newSite();
    if (!s) return;
    if (a === 'toggle') return toggle(s);
    if (a === 'open') return window.open(siteUrl(s), '_blank', 'noopener');
    if (a === 'folder') return openFolder(s);
    if (a === 'log') return viewLog(s);
    if (a === 'deploy') return deploy(s);
    if (a === 'backups') return backups(s);
    if (a === 'size') return calcSize(s);
    if (a === 'more') { const r = b.getBoundingClientRect(); return moreMenu(s, r.right - 230, r.bottom + 4); }
  }

  function moreMenu(s, x, y) {
    menu(Math.max(6, x), y, [
      { l: 'Abrir site', i: 'open', fn: () => window.open(siteUrl(s), '_blank', 'noopener') },
      { l: 'Abrir pasta', i: 'folder', dis: !s.root, fn: () => openFolder(s) },
      { l: 'Ver logs', i: 'log', fn: () => viewLog(s) },
      ...(s.type === 'laravel' ? [{ l: 'Deploy…', i: 'rocket', dis: !RW, fn: () => deploy(s) }] : []),
      { l: 'Backups…', i: 'archive', dis: !RW, fn: () => backups(s) },
      { l: 'Calcular tamanho', i: 'info', fn: () => calcSize(s) },
      { l: 'Copiar linha do arquivo hosts', i: 'copy', fn: () => copyText(hostsLine(s)).then(() => toast('Linha copiada: ' + hostsLine(s))) },
      '-',
      { l: s.on ? 'Desligar site' : 'Ligar site', i: 'power', dis: !RW, fn: () => toggle(s) },
      { l: 'Remover site…', i: 'trash', danger: true, dis: !RW, fn: () => removeSite(s) }
    ]);
  }

  /* ------------------------------------------------------------ ações */
  function openFolder(s) {
    if (!C0.user) return toast('O gerenciador de arquivos está desativado nesta instalação.', 'er');
    const p = s.exists ? s.root : '/var/www';
    if (window.FM) window.FM.go(p);
    location.hash = '#arquivos';
  }

  async function calcSize(s) {
    S.sizes[s.name] = 'busy'; render();
    try { const d = await api('size', { name: s.name }); S.sizes[s.name] = d.size; }
    catch (e) { delete S.sizes[s.name]; fail(e); }
    render();
  }

  async function toggle(s) {
    if (!RW) return;
    if (s.on && !(await confirmDlg('Desligar ' + s.domain + '?', 'O site para de responder, mas os arquivos continuam em <b>' + E(s.root) + '</b>. Dá para ligar de novo a qualquer momento.', 'Desligar', true))) return;
    try {
      const d = await api('toggle', { name: s.name, on: !s.on });
      Object.assign(s, d.site);
      toast(s.on ? 'Site ' + s.domain + ' ligado' : 'Site ' + s.domain + ' desligado');
    } catch (e) {
      dialog({ title: 'Não foi possível alterar o site', icon: 'warn', html: errHtml(e), wide: !!e.detail });
    }
    render();
  }

  async function removeSite(s) {
    if (!RW) return;
    const r = await dialog({
      title: 'Remover ' + s.domain, icon: 'trash',
      html: '<p>O site será desligado e a configuração dele no Apache será apagada' + (s.ssl ? ' (incluindo o SSL)' : '') + '.</p>' +
        (s.exists ? '<label class="ck"><input type="checkbox" id="rmFiles"> Apagar também os arquivos em <code>' + E(s.root) + '</code></label>' : '') +
        '<div class="nf-l">Para confirmar, digite <b>' + E(s.name) + '</b></div><input class="fm-in mono" id="rmConf" spellcheck="false" autocomplete="off" autocapitalize="off">' +
        '<div class="nf-err" id="rmErr"></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Remover', value: 'ok', kind: 'danger' }],
      onOpen(ov) {
        const i = qs('#rmConf', ov), b = qs('.df button.danger', ov);
        const chk = () => { b.disabled = i.value.trim() !== s.name; };
        i.addEventListener('input', chk); chk();
      },
      async validate(ov) {
        const conf = qs('#rmConf', ov).value.trim();
        if (conf !== s.name) return false;
        const files = !!(qs('#rmFiles', ov) && qs('#rmFiles', ov).checked);
        const b = qs('.df button.danger', ov); b.disabled = true; b.textContent = 'Removendo…';
        try { return { d: await api('remove', { name: s.name, confirm: conf, files }) }; }
        catch (e) { qs('#rmErr', ov).innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Remover'; return false; }
      }
    });
    if (!r || !r.d) return;
    toast('Site ' + s.domain + ' removido' + (r.d.notes && r.d.notes.length ? ' · ' + r.d.notes.join(' · ') : ''));
    S.sites = S.sites.filter(x => x !== s);
    render();
  }

  /* ------------------------------------------------------------ novo site */
  const normDom = v => v.trim().toLowerCase().replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
  const validDom = d => d.length <= 200 && /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(d);

  async function newSite() {
    if (!RW) return;
    if (!S.loaded) await load(true);
    const phpOpts = S.php.slice().reverse().map(v => '<option value="' + E(v) + '">PHP ' + E(v) + '</option>').join('');
    const r = await dialog({
      title: 'Novo site', icon: 'globe', cls: 'nfd',
      html: '<div class="nf">' +
        '<div class="nf-l">Domínio</div><input class="fm-in mono" id="nfDom" placeholder="meusite.test" spellcheck="false" autocomplete="off" autocapitalize="off">' +
        '<div class="nf-h" id="nfDomH">Para usar só na rede local, termine com <b>.test</b> (ex.: loja.test).</div>' +
        '<div class="nf-l">Tipo</div><div class="seg" id="nfType"><button type="button" data-t="php" class="on">PHP / HTML</button><button type="button" data-t="laravel">Laravel</button><button type="button" data-t="proxy">Proxy (Node / PM2)</button></div>' +
        '<div class="nf-h" id="nfTypeH"></div>' +
        '<div id="nfPhpW"><div class="nf-l">Versão do PHP</div>' + (phpOpts ? '<select class="fm-in" id="nfPhp">' + phpOpts + '</select>' : '<div class="nf-err">Nenhum PHP-FPM instalado. Instale o LAMP pelo lk (opção 1).</div>') + '</div>' +
        '<div id="nfPortW" hidden><div class="nf-l">Porta local do app</div><input class="fm-in mono" id="nfPort" inputmode="numeric" placeholder="3000" autocomplete="off"></div>' +
        '<label class="ck"><input type="checkbox" id="nfWww" checked> Responder também em <span class="mono" id="nfWwwD">www.</span></label>' +
        '<label class="ck" id="nfDbW"><input type="checkbox" id="nfDb"' + (S.mysql ? '' : ' disabled') + '> Criar banco de dados MySQL para o site' + (S.mysql ? '' : ' <small>(MySQL/MariaDB não encontrado)</small>') + '</label>' +
        '<div class="nf-err" id="nfErr"></div></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Criar site', value: 'ok', kind: 'pri' }],
      onOpen(ov) {
        let type = 'php';
        const dom = qs('#nfDom', ov), h = qs('#nfDomH', ov);
        const hint = () => {
          const d = normDom(dom.value) || 'dominio';
          qs('#nfWwwD', ov).textContent = 'www.' + d;
          qs('#nfTypeH', ov).innerHTML = type === 'php' ? 'Arquivos em <code>/var/www/' + E(d) + '/public_html</code>'
            : type === 'laravel' ? 'Projeto em <code>/var/www/' + E(d) + '</code>; o site aponta para a pasta <code>public/</code>'
              : 'Encaminha o domínio para um app rodando em <code>127.0.0.1:porta</code>';
          const v = normDom(dom.value);
          h.classList.remove('bad');
          if (!v) h.innerHTML = 'Para usar só na rede local, termine com <b>.test</b> (ex.: loja.test).';
          else if (/^[a-z0-9-]+$/.test(v)) h.innerHTML = 'Falta a terminação. Sugestão: <button type="button" class="lnk" data-sug="' + E(v) + '.test">' + E(v) + '.test</button>';
          else if (!validDom(v)) { h.classList.add('bad'); h.textContent = 'Domínio inválido: use letras, números, hífen e pontos (ex.: loja.test).'; }
          else h.innerHTML = /\.(test|local|lan|localhost)$/.test(v) ? 'Domínio local: lembre de adicionar no arquivo hosts do seu PC (mostramos a linha depois de criar).' : 'Para funcionar na internet, o DNS de <b>' + E(v) + '</b> precisa apontar para este servidor.';
        };
        dom.addEventListener('input', hint);
        h.addEventListener('click', e => { const b = e.target.closest('[data-sug]'); if (b) { dom.value = b.dataset.sug; hint(); dom.focus(); } });
        qsa('#nfType button', ov).forEach(b => b.onclick = () => {
          type = b.dataset.t; ov.dataset.type = type;
          qsa('#nfType button', ov).forEach(x => x.classList.toggle('on', x === b));
          qs('#nfPhpW', ov).hidden = type === 'proxy'; qs('#nfPortW', ov).hidden = type !== 'proxy'; qs('#nfDbW', ov).hidden = type === 'proxy';
          hint();
        });
        ov.dataset.type = 'php';
        hint();
      },
      async validate(ov) {
        const err = qs('#nfErr', ov), type = ov.dataset.type || 'php';
        const d = normDom(qs('#nfDom', ov).value);
        err.textContent = '';
        if (!validDom(d)) { err.textContent = d ? 'Domínio inválido. Exemplo: meusite.test' : 'Digite o domínio do site.'; qs('#nfDom', ov).focus(); return false; }
        if (S.sites.some(s => s.name === d)) { err.textContent = 'Já existe um site ' + d + '.'; return false; }
        const body = { domain: d, type, www: qs('#nfWww', ov).checked };
        if (type === 'proxy') {
          const p = +qs('#nfPort', ov).value;
          if (!(p >= 1 && p <= 65535)) { err.textContent = 'Informe a porta do app (ex.: 3000).'; qs('#nfPort', ov).focus(); return false; }
          body.port = p;
        } else {
          if (!qs('#nfPhp', ov)) { err.textContent = 'Nenhum PHP-FPM instalado.'; return false; }
          body.php = qs('#nfPhp', ov).value; body.db = qs('#nfDb', ov).checked;
        }
        const b = qs('.df button.pri', ov); b.disabled = true; b.textContent = 'Criando…';
        try { return { d: await api('create', body), type }; }
        catch (e) { err.innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Criar site'; return false; }
      }
    });
    if (!r || !r.d) return;
    created(r.d, r.type);
    load(true);
  }

  function created(d, type) {
    const s = d.site, url = siteUrl(s);
    const env = d.db ? 'DB_CONNECTION=mysql\nDB_HOST=127.0.0.1\nDB_PORT=3306\nDB_DATABASE=' + d.db.name + '\nDB_USERNAME=' + d.db.user + '\nDB_PASSWORD=' + d.db.pass : '';
    dialog({
      title: 'Site criado', icon: 'check', wide: true,
      html: '<div class="nf">' +
        '<p>O site <b>' + E(s.domain) + '</b> está ligado. Endereço: <a href="' + E(url) + '" target="_blank" rel="noopener">' + E(url) + '</a></p>' +
        (type === 'laravel' ? '<p class="nf-h">Coloque o projeto Laravel em <code>' + E(s.root) + '</code> (ex.: <code>git clone … ' + E(s.root) + '</code>) e depois corrija as permissões.</p>' : '') +
        '<div class="nf-l">Arquivo hosts do Windows</div>' +
        '<div class="nf-h">Para abrir pelo nome no seu PC, adicione esta linha em <code>C:\\Windows\\System32\\drivers\\etc\\hosts</code> (abra o Bloco de Notas como administrador):</div>' +
        '<div class="cpl"><code id="hl">' + E(d.hosts) + '</code><button type="button" class="abtn sm" data-copy="hl">' + svg('copy') + 'Copiar</button></div>' +
        (d.db ? '<div class="nf-box"><div class="nf-l">' + svg('db') + ' Banco de dados criado</div>' +
          '<div class="nf-warn">' + svg('warn') + 'Anote agora: a senha não será mostrada de novo.</div>' +
          '<dl class="props"><dt>Banco</dt><dd><code>' + E(d.db.name) + '</code></dd><dt>Usuário</dt><dd><code>' + E(d.db.user) + '</code></dd><dt>Senha</dt><dd><code>' + E(d.db.pass) + '</code></dd><dt>Servidor</dt><dd><code>127.0.0.1:3306</code></dd></dl>' +
          '<div class="nf-l">Linhas para o .env</div><div class="cpl col"><pre id="envl">' + E(env) + '</pre><button type="button" class="abtn sm" data-copy="envl">' + svg('copy') + 'Copiar .env</button></div></div>' : '') +
        (d.db_error ? '<div class="nf-err">' + E(d.db_error) + '</div>' : '') +
        '</div>',
      buttons: [{ label: 'Abrir site', value: 'open' }, { label: 'Concluir', value: true, kind: 'pri' }],
      onOpen(ov) { qsa('[data-copy]', ov).forEach(b => b.onclick = () => copyText(qs('#' + b.dataset.copy, ov).textContent).then(() => toast('Copiado'))); }
    }).then(v => { if (v === 'open') window.open(url, '_blank', 'noopener'); });
  }

  /* ------------------------------------------------------------ logs */
  function viewLog(s) {
    let which = s.type === 'laravel' ? 'laravel' : 'error', timer = null, alive = true, reqId = 0;
    const LBL = { error: 'Erros do Apache', access: 'Acessos', laravel: 'Laravel' };
    const hl = (txt, q) => {
      const lines = txt.split('\n');
      return lines.map(l => {
        let h = E(l);
        if (q) { const re = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'); h = h.replace(re, m => '<mark>' + m + '</mark>'); }
        const c = /\b(error|critical|emergency|alert|fatal|emerg|crit)\b/i.test(l) ? 'e' : /\b(warn|warning|notice)\b/i.test(l) ? 'w' : '';
        return c ? '<span class="' + c + '">' + h + '</span>' : h;
      }).join('\n');
    };
    dialog({
      title: 'Logs · ' + s.domain, icon: 'log', cls: 'xl',
      html: '<div class="lv">' +
        '<div class="lv-bar"><div class="seg" id="lvW">' + Object.keys(LBL).map(k => '<button type="button" data-w="' + k + '">' + LBL[k] + '</button>').join('') + '</div>' +
        '<div class="st-search">' + svg('search') + '<input id="lvQ" placeholder="Buscar no log" spellcheck="false" autocomplete="off"></div>' +
        '<select class="fm-in sm" id="lvN"><option value="100">100 linhas</option><option value="200" selected>200 linhas</option><option value="500">500 linhas</option><option value="1000">1000 linhas</option></select>' +
        '<label class="ck"><input type="checkbox" id="lvLive"> Ao vivo</label>' +
        '<button type="button" class="ib" id="lvR" title="Atualizar">' + svg('refresh') + '</button></div>' +
        '<div class="lv-file" id="lvF"></div><pre class="lv-out" id="lvO">Carregando…</pre></div>',
      buttons: [{ label: 'Fechar', value: null }],
      onOpen(ov) {
        const out = qs('#lvO', ov), q = qs('#lvQ', ov), n = qs('#lvN', ov), live = qs('#lvLive', ov);
        const fetchLog = async () => {
          const id = ++reqId, query = q.value.trim();
          const stick = out.scrollTop + out.clientHeight >= out.scrollHeight - 30;
          try {
            const d = await api('logs', { name: s.name, which, lines: +n.value, q: query });
            if (id !== reqId || !alive) return;
            qsa('#lvW button', ov).forEach(b => { b.hidden = !(d.avail || []).includes(b.dataset.w); b.classList.toggle('on', b.dataset.w === which); });
            qs('#lvF', ov).innerHTML = '<span class="mono">' + E(d.file) + '</span>' + (d.size != null ? ' · ' + fsize(d.size) : '') + (query ? ' · ' + d.matches + ' linha(s) com “' + E(query) + '”' : '');
            out.innerHTML = d.missing ? '<span class="st-dim">O arquivo ainda não existe (nenhum registro até agora).</span>' : d.text ? hl(d.text, query) : '<span class="st-dim">' + (query ? 'Nada encontrado.' : 'Log vazio.') + '</span>';
            if (stick || id === 1) out.scrollTop = out.scrollHeight;
          } catch (e) {
            if (id !== reqId || !alive) return;
            if (e.data && e.data.avail) {
              qsa('#lvW button', ov).forEach(b => { b.hidden = !e.data.avail.includes(b.dataset.w); });
              if (e.data.avail.length && !e.data.avail.includes(which)) { which = e.data.avail[0]; return fetchLog(); }
            }
            qs('#lvF', ov).textContent = '';
            out.innerHTML = '<span class="e">' + E(e.message) + '</span>';
          }
        };
        const setLive = () => { clearInterval(timer); timer = live.checked ? setInterval(() => { if (!document.hidden) fetchLog(); }, 3000) : null; };
        qsa('#lvW button', ov).forEach(b => b.onclick = () => { which = b.dataset.w; out.textContent = 'Carregando…'; reqId++; fetchLog(); });
        let qt; q.addEventListener('input', () => { clearTimeout(qt); qt = setTimeout(fetchLog, 350); });
        q.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); fetchLog(); } });
        n.onchange = fetchLog; live.onchange = setLive; qs('#lvR', ov).onclick = fetchLog;
        fetchLog();
      }
    }).then(() => { alive = false; clearInterval(timer); });
  }

  /* ------------------------------------------------------------ tarefas em segundo plano */
  async function jget(q) {
    let r;
    try { r = await fetch('?jobs=' + q, { credentials: 'same-origin', cache: 'no-store' }); } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    const d = await r.json();
    if (!d.ok) throw new Error(d.error || 'Erro');
    return d;
  }
  const ST = { queued: 'Na fila', running: 'Em andamento', ok: 'Concluído', error: 'Falhou', interrupted: 'Interrompido' };
  const fdt = t => { if (!t) return '—'; const d = new Date(t * 1000), p = n => String(n).padStart(2, '0'); return p(d.getDate()) + '/' + p(d.getMonth() + 1) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes()); };
  const fdur = s => s < 60 ? s + ' s' : Math.floor(s / 60) + ' min ' + (s % 60) + ' s';
  const jobBadge = J => '<span class="jst ' + J.state + '">' + (ST[J.state] || J.state) + '</span>';

  /** Acompanha uma tarefa: passos, log ao vivo e resultado final. */
  function jobView(id, title, icon) {
    let from = 0, timer = null, alive = true, J = null;
    const ico = { pending: '<i class="jdot"></i>', running: '<i class="jspin"></i>', ok: svg('check'), error: svg('x'), skipped: '<i class="jdot sk"></i>', canceled: '<i class="jdot"></i>' };
    return dialog({
      title: title || 'Tarefa', icon: icon || 'rocket', cls: 'xl',
      html: '<div class="jv"><div class="jv-head"><span id="jvS"></span><span id="jvT" class="st-dim"></span></div>' +
        '<div class="jv-res" id="jvR" hidden></div><div class="jv-steps" id="jvP"></div><pre class="lv-out" id="jvL"></pre></div>',
      buttons: [{ label: 'Baixar log', value: 'log' }, { label: 'Fechar', value: null, kind: 'pri' }],
      onOpen(ov) {
        const L = qs('#jvL', ov);
        const tick = async () => {
          if (!alive) return;
          try {
            const d = await jget('status&id=' + encodeURIComponent(id) + '&from=' + from);
            J = d.job;
            if (d.chunk) {
              const stick = L.scrollTop + L.clientHeight >= L.scrollHeight - 30;
              if (!from || d.from < from) L.textContent = '';
              L.textContent += d.chunk;
              if (stick || !from) L.scrollTop = L.scrollHeight;
            }
            from = d.size;
            qs('#jvS', ov).innerHTML = jobBadge(J);
            const t0 = J.started || J.created, t1 = J.ended || Math.floor(Date.now() / 1000);
            qs('#jvT', ov).textContent = 'iniciado ' + fdt(J.created) + ' · ' + fdur(Math.max(0, t1 - t0));
            qs('#jvP', ov).innerHTML = (J.steps || []).map(st => '<div class="jstep ' + st.state + '">' + (ico[st.state] || '') + '<span>' + E(st.label) + '</span>' +
              (st.ended && st.started ? '<small>' + fdur(st.ended - st.started) + '</small>' : st.state === 'skipped' ? '<small>ignorado</small>' : '') + '</div>').join('');
            if (['ok', 'error', 'interrupted'].includes(J.state)) {
              const R = qs('#jvR', ov); R.hidden = false; R.className = 'jv-res ' + J.state;
              R.innerHTML = J.state === 'ok' ? svg('check') + '<span><b>Concluído com sucesso</b>' + (J.ended ? ' em ' + fdur(J.ended - J.started) : '') + '</span>'
                : J.state === 'error' ? svg('warn') + '<span><b>Falhou</b> no passo <b>' + E(J.failed || '?') + '</b>. Veja o log abaixo.</span>'
                  : svg('warn') + '<span><b>Interrompido</b>: a tarefa parou sem terminar (servidor reiniciado?).</span>';
              return;
            }
          } catch (e) { qs('#jvT', ov).textContent = e.message; }
          timer = setTimeout(tick, 1000);
        };
        tick();
      }
    }).then(v => {
      alive = false; clearTimeout(timer);
      if (v === 'log') { location.href = '?jobs=log&id=' + encodeURIComponent(id); return jobView(id, title, icon); }
      if (J && ['queued', 'running'].includes(J.state)) toast('A tarefa continua em segundo plano');
      return J;
    });
  }
  window.JOBS = { view: jobView, get: jget, badge: jobBadge, fdt, fdur };

  /* ------------------------------------------------------------ backups */
  const KIND = { manual: 'manual', auto: 'automático', seguranca: 'antes de restaurar' };
  const fdtY = t => { const d = new Date(t * 1000), p = n => String(n).padStart(2, '0'); return p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + p(d.getHours()) + ':' + p(d.getMinutes()); };
  const dbLabel = db => !db || !db.type ? 'sem banco (só arquivos)' : db.type === 'mysql' ? 'MySQL · ' + db.name : 'SQLite · ' + db.path;

  async function backups(s) {
    let d;
    try { d = await api('backups', { name: s.name }); } catch (e) { return fail(e); }
    if (d.running) {
      const ttl = (d.running_type === 'restore' ? 'Restaurar · ' : d.running_type === 'deploy' ? 'Deploy · ' : 'Backup · ') + s.domain;
      await jobView(d.running, ttl, d.running_type === 'deploy' ? 'rocket' : 'archive');
      return backups(s);
    }
    const a = d.auto;
    const list = d.backups.length ? '<div class="bk-list">' + d.backups.map(m => '<div class="bk-row" data-f="' + E(m.file) + '">' +
      '<div class="bk-main"><b>' + fdtY(m.created) + '</b><small>' + E(dbLabel(m.db)) + '</small></div>' +
      '<span class="tag' + (m.kind === 'seguranca' ? ' t-laravel' : m.kind === 'auto' ? ' t-proxy' : '') + '">' + (KIND[m.kind] || m.kind) + '</span>' +
      '<span class="num bk-size">' + fsize(m.size) + '</span>' +
      '<div class="bk-acts"><a class="ib" title="Baixar" href="?fm=download&t=' + encodeURIComponent(TOKEN) + '&path=' + encodeURIComponent(m.path) + '">' + svg('download') + '</a>' +
      (RW ? '<button type="button" class="ib" data-b="restore" title="Restaurar este backup">' + svg('refresh') + '</button><button type="button" class="ib danger" data-b="del" title="Apagar">' + svg('trash') + '</button>' : '') +
      '</div></div>').join('') + '</div>' : '<div class="st-empty">' + svg('archive') + '<b>Nenhum backup ainda</b><span>Faça o primeiro com o botão abaixo.</span></div>';
    const r = await dialog({
      title: 'Backups · ' + s.domain, icon: 'archive', wide: true,
      html: '<div class="nf"><p class="nf-h">Banco: <b>' + E(dbLabel(d.db)) + '</b> · pasta <code>' + E(d.root) + '</code>. Ficam fora do arquivo: vendor, node_modules, caches, sessões e logs.</p>' +
        '<div class="bk-auto">' + svg('archive') + '<span>Backup automático: ' + (a.enabled ? 'diário às <b>' + E(a.time) + '</b>, mantém os últimos <b>' + a.keep + '</b> · este site <b>' + (a.on ? 'está incluído' : 'não está incluído') + '</b>' : '<b>desativado</b>') +
        '</span><button type="button" class="lnk" data-b="cfg">Configurar</button></div>' + list + '<div class="nf-err" id="bkErr"></div></div>',
      buttons: [{ label: 'Fechar', value: null }].concat(RW ? [{ label: 'Fazer backup agora', value: 'now', kind: 'pri' }] : []),
      onOpen(ov, close) {
        qsa('[data-b]', ov).forEach(b => b.onclick = () => {
          const f = b.closest('[data-f]');
          close({ act: b.dataset.b, file: f ? f.dataset.f : null });
        });
      }
    });
    if (!r) return;
    if (r === 'now' || r.act === 'now') {
      try { const j = await api('backup', { name: s.name }); await jobView(j.job, 'Backup · ' + s.domain, 'archive'); }
      catch (e) { if (e.data && e.data.running) await jobView(e.data.running, 'Tarefa · ' + s.domain); else fail(e); }
      return backups(s);
    }
    if (r.act === 'cfg') { location.hash = '#config'; return; }
    const m = d.backups.find(x => x.file === r.file);
    if (!m) return;
    if (r.act === 'del') {
      if (await confirmDlg('Apagar backup?', 'O backup de <b>' + fdtY(m.created) + '</b> (' + fsize(m.size) + ') será apagado de vez.', 'Apagar', true)) {
        try { await api('backup_delete', { name: s.name, file: m.file }); toast('Backup apagado'); } catch (e) { fail(e); }
      }
      return backups(s);
    }
    if (r.act === 'restore') {
      const ok = await dialog({
        title: 'Restaurar ' + s.domain, icon: 'refresh',
        html: '<p>Os arquivos do site e o banco vão voltar ao estado de <b>' + fdtY(m.created) + '</b> (' + E(dbLabel(m.db)) + ').</p>' +
          '<div class="nf-warn">' + svg('check') + 'Antes, é feito um backup de segurança do estado atual (aparece como “antes de restaurar”).</div>' +
          '<p class="nf-h">vendor, node_modules, caches e logs atuais são mantidos; se faltar vendor, roda composer install no final.</p>' +
          '<div class="nf-l">Para confirmar, digite <b>' + E(s.name) + '</b></div><input class="fm-in mono" id="rsC" spellcheck="false" autocomplete="off" autocapitalize="off"><div class="nf-err" id="rsErr"></div>',
        buttons: [{ label: 'Cancelar', value: null }, { label: 'Restaurar', value: 'ok', kind: 'danger' }],
        onOpen(ov) { const i = qs('#rsC', ov), b = qs('.df button.danger', ov); const c = () => { b.disabled = i.value.trim() !== s.name; }; i.addEventListener('input', c); c(); },
        async validate(ov) {
          const conf = qs('#rsC', ov).value.trim();
          if (conf !== s.name) return false;
          const b = qs('.df button.danger', ov); b.disabled = true; b.textContent = 'Iniciando…';
          try { return { job: (await api('restore', { name: s.name, file: m.file, confirm: conf })).job }; }
          catch (e) { qs('#rsErr', ov).innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Restaurar'; return false; }
        }
      });
      if (ok && ok.job) { await jobView(ok.job, 'Restaurar · ' + s.domain, 'refresh'); load(true); }
      return backups(s);
    }
  }

  /* ------------------------------------------------------------ deploy */
  async function deploy(s) {
    if (!RW) return;
    let info, hist;
    try { [info, hist] = await Promise.all([api('deploy_info', { name: s.name }), jget('list&type=deploy&site=' + encodeURIComponent(s.name))]); }
    catch (e) { return fail(e); }
    if (info.running) return jobView(info.running, 'Deploy · ' + s.domain).then(() => load(true));
    if (!info.laravel) {
      return dialog({ title: 'Deploy · ' + s.domain, icon: 'rocket', html: '<p>Não encontrei um projeto Laravel em <code>' + E(info.root) + '</code> (falta o arquivo <code>artisan</code>).</p><p class="nf-h">Coloque o projeto na pasta (ex.: <code>git clone … ' + E(info.root) + '</code>) e tente de novo.</p>' });
    }
    const npmOk = info.pkg && info.node;
    const opt = (k, label, desc, on, extra) => '<label class="dp-opt"><input type="checkbox" data-o="' + k + '"' + (on ? ' checked' : '') + '><div><b>' + label + '</b>' + (desc ? '<small>' + desc + '</small>' : '') + (extra || '') + '</div></label>';
    const histHtml = hist.jobs.length ? '<div class="nf-l">Últimos deploys</div><div class="dp-hist">' + hist.jobs.map(J => '<button type="button" class="dp-h" data-job="' + E(J.id) + '">' + jobBadge(J) + '<span>' + fdt(J.created) + '</span><small>' +
      (J.ended && J.started ? fdur(J.ended - J.started) : '') + (J.state === 'error' && J.failed ? ' · parou em ' + E(J.failed) : '') + '</small></button>').join('') + '</div>' : '';
    const r = await dialog({
      title: 'Deploy · ' + s.domain, icon: 'rocket', wide: true,
      html: '<div class="nf"><p class="nf-h">Pasta <code>' + E(info.root) + '</code> · PHP ' + E(info.php || '?') + '. Os comandos do artisan, composer e npm rodam como <b>www-data</b>.</p>' +
        '<div class="dp-opts">' +
        opt('hot', 'Remover public/hot', 'arquivo do servidor de desenvolvimento do Vite' + (info.hot ? ' · <span class="warn">existe agora</span>' : ''), true) +
        opt('perms', 'Corrigir dono e permissões', 'www-data em tudo; escrita em storage, bootstrap/cache e database', true) +
        opt('composer', 'composer install', info.composer ? (info.vendor ? '' : 'a pasta vendor ainda não existe') : '<span class="warn">Composer não instalado (lk, opção 16)</span>', info.composer,
          '<label class="ck sub"><input type="checkbox" data-o="nodev"> --no-dev (sem pacotes de desenvolvimento)</label>') +
        opt('migrate', 'php artisan migrate --force', 'aplica as migrations no banco', true) +
        opt('optimize', 'php artisan optimize:clear', 'limpa caches de config, rotas e views', true) +
        opt('storage', 'php artisan storage:link', 'cria o link public/storage', true) +
        (npmOk ? opt('npm', 'npm ci && npm run build', 'compila os assets (Vite)', false) : info.pkg ? '<div class="nf-h">npm: o Node.js não está instalado neste servidor (lk, opção 8).</div>' : '') +
        '</div>' + histHtml + '<div class="nf-err" id="dpErr"></div></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Iniciar deploy', value: 'ok', kind: 'pri' }],
      onOpen(ov, close) {
        qsa('[data-job]', ov).forEach(b => b.onclick = () => close({ view: b.dataset.job }));
        const c = qs('[data-o="composer"]', ov), nd = qs('[data-o="nodev"]', ov);
        const sync = () => { nd.disabled = !c.checked; if (!c.checked) nd.checked = false; };
        c.onchange = sync; sync();
      },
      async validate(ov) {
        const opts = {};
        qsa('[data-o]', ov).forEach(i => { opts[i.dataset.o] = i.checked; });
        if (!['hot', 'perms', 'composer', 'migrate', 'optimize', 'storage', 'npm'].some(k => opts[k])) { qs('#dpErr', ov).textContent = 'Marque pelo menos um passo.'; return false; }
        const b = qs('.df button.pri', ov); b.disabled = true; b.textContent = 'Iniciando…';
        try { return { job: (await api('deploy', { name: s.name, opts })).job }; }
        catch (e) {
          if (e.data && e.data.running) return { job: e.data.running };
          qs('#dpErr', ov).innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Iniciar deploy'; return false;
        }
      }
    });
    if (r && r.view) return jobView(r.view, 'Deploy · ' + s.domain).then(() => deploy(s));
    if (r && r.job) jobView(r.job, 'Deploy · ' + s.domain).then(() => load(true));
  }

  /* ------------------------------------------------------------ inicialização */
  window.SITES = {
    show() {
      if (!qs('#sites')) return;
      if (!inited) { inited = true; build(); load(); }
      else load(true);
    }
  };
  if (location.hash === '#sites') window.SITES.show();
})();
LKM_EOF_SITESJS
cat > "$DIR/db.js" <<'LKM_EOF_DBJS'
/* LK Monitor - aba Bancos (MySQL/MariaDB e SQLite) */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const { E, qs, qsa, toast, fail, dialog, confirmDlg, menu, svg, copyText, fsize } = U;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const TOKEN = C0.token || '';
  const ROOT = C0.user === 'root';
  const S = { tab: 'mysql', data: null, error: '', filter: '', busy: false };
  let root, inited = false;

  async function api(act, body, raw) {
    let r;
    try {
      r = await fetch('?db=' + act, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': TOKEN }, body: JSON.stringify(body || {}) });
    } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    if (raw && (r.headers.get('Content-Type') || '').startsWith('text/csv')) return r;
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do servidor (' + r.status + ')'); }
    if (!d.ok) { const er = new Error(d.error || 'Erro desconhecido'); er.detail = d.detail || ''; er.data = d; throw er; }
    return d;
  }
  const errHtml = e => E(e.message) + (e.detail ? '<pre class="nf-pre">' + E(e.detail) + '</pre>' : '');
  const envLines = d => 'DB_CONNECTION=mysql\nDB_HOST=127.0.0.1\nDB_PORT=3306\nDB_DATABASE=' + d.name + '\nDB_USERNAME=' + d.user + '\nDB_PASSWORD=' + d.pass;
  const num = n => n == null ? '—' : Number(n).toLocaleString('pt-BR');

  /* ------------------------------------------------------------ lista */
  function build() {
    root = qs('#bancos');
    if (!ROOT) {
      root.innerHTML = '<div class="card st"><div class="st-top"><div class="st-ttl"><h2>Bancos de dados</h2></div></div><div class="st-ro">' + svg('lock') +
        '<div><b>Indisponível nesta instalação.</b> Para ver e gerenciar os bancos, o painel precisa de acesso root (para entrar no MySQL pelo socket). Rode <code>sudo lk</code> › opção 33 › 1 e escolha <b>root</b> no acesso do terminal.</div></div><div class="st-empty"></div></div>';
      return;
    }
    root.innerHTML =
      '<div class="card st">' +
      '<div class="st-top"><div class="st-ttl"><h2>Bancos de dados</h2><span id="dbCount"></span></div>' +
      '<div class="st-tools"><div class="seg" id="dbTab"><button type="button" data-t="mysql" class="on">MySQL / MariaDB</button><button type="button" data-t="sqlite">SQLite</button></div>' +
      '<div class="st-search">' + svg('search') + '<input id="dbQ" placeholder="Filtrar" spellcheck="false" autocomplete="off"></div>' +
      '<button class="abtn" data-a="reload" title="Atualizar">' + svg('refresh') + '</button>' +
      '<button class="abtn pri" data-a="new" id="dbNew">' + svg('plus') + '<span>Novo banco</span></button></div></div>' +
      '<div id="dbMsg"></div><div id="dbList" class="st-list"></div></div>' +
      '<div class="card st" id="dbUsersCard"><div class="st-top"><div class="st-ttl"><h2>Usuários do MySQL</h2><span id="dbUCount"></span></div></div><div id="dbUsers" class="st-list"></div></div>';
    root.addEventListener('click', onClick);
    qs('#dbQ').addEventListener('input', e => { S.filter = e.target.value.trim().toLowerCase(); render(); });
    qsa('#dbTab button').forEach(b => b.onclick = () => { S.tab = b.dataset.t; qsa('#dbTab button').forEach(x => x.classList.toggle('on', x === b)); render(); });
  }

  async function load(quiet) {
    if (S.busy || !ROOT) return;
    S.busy = true;
    if (!quiet && !S.data) qs('#dbList').innerHTML = '<div class="st-empty">Carregando bancos…</div>';
    try { S.data = await api('overview'); S.error = ''; }
    catch (e) { S.error = e.message; }
    finally { S.busy = false; }
    render();
  }

  function render() {
    if (!root || !ROOT) return;
    const list = qs('#dbList'), msg = qs('#dbMsg'), d = S.data;
    qs('#dbNew').hidden = S.tab !== 'mysql';
    qs('#dbUsersCard').hidden = S.tab !== 'mysql' || !d || !d.mysql.ok;
    if (S.error) { list.innerHTML = '<div class="fm-err">' + E(S.error) + '</div>'; msg.innerHTML = ''; return; }
    if (!d) return;
    const f = S.filter;
    if (S.tab === 'mysql') {
      msg.innerHTML = d.mysql.ok ? '' : '<div class="st-ro">' + svg('warn') + '<div>' + E(d.mysql.error || 'MySQL indisponível') + '</div></div>';
      qs('#dbNew').disabled = !d.mysql.ok;
      const v = d.dbs.filter(x => !f || (x.name + ' ' + x.users.join(' ') + ' ' + x.sites.join(' ')).toLowerCase().includes(f));
      qs('#dbCount').textContent = d.mysql.ok ? d.dbs.length + (d.dbs.length === 1 ? ' banco' : ' bancos') + ' · ' + d.mysql.version : '';
      list.innerHTML = !d.mysql.ok ? '' : !d.dbs.length ? '<div class="st-empty">' + svg('db') + '<b>Nenhum banco criado ainda</b><span>Crie o primeiro com <b>Novo banco</b>.</span></div>'
        : !v.length ? '<div class="st-empty">Nada corresponde ao filtro.</div>' : v.map(rowMy).join('');
      const us = d.users.filter(u => !f || (u.user + ' ' + u.dbs.join(' ')).toLowerCase().includes(f));
      qs('#dbUCount').textContent = d.users.length ? d.users.length + (d.users.length === 1 ? ' usuário' : ' usuários') : '';
      qs('#dbUsers').innerHTML = us.length ? us.map(rowUser).join('') : '<div class="st-empty">Nenhum usuário além dos do sistema.</div>';
    } else {
      msg.innerHTML = '';
      const v = d.sqlite.filter(x => !f || (x.path + ' ' + x.site).toLowerCase().includes(f));
      qs('#dbCount').textContent = d.sqlite.length + (d.sqlite.length === 1 ? ' arquivo' : ' arquivos') + ' em /var/www';
      list.innerHTML = !d.sqlite.length ? '<div class="st-empty">' + svg('db') + '<b>Nenhum arquivo SQLite encontrado</b><span>Procuro arquivos .sqlite, .sqlite3 e .db dentro de /var/www (ex.: database/database.sqlite do Laravel).</span></div>'
        : !v.length ? '<div class="st-empty">Nada corresponde ao filtro.</div>' : v.map(rowLite).join('');
    }
  }

  function rowMy(x) {
    return '<div class="st-row db-row" data-db="' + E(x.name) + '">' +
      '<div class="st-site"><span class="db-ico">' + svg('db') + '</span><div class="st-dn"><button type="button" class="db-name" data-a="open">' + E(x.name) + '</button>' +
      '<small>' + (x.sites.length ? 'usado por ' + E(x.sites.join(', ')) : 'nenhum site usa este banco no .env') + '</small></div></div>' +
      '<div class="st-tags"><span class="tag">' + num(x.tables) + (x.tables === 1 ? ' tabela' : ' tabelas') + '</span>' + x.users.map(u => '<span class="tag mono">' + svg('users') + E(u) + '</span>').join('') + '</div>' +
      '<div class="st-size r num">' + fsize(x.size) + '</div>' +
      '<div class="st-acts"><button class="ib" data-a="open" title="Abrir tabelas e consultas">' + svg('table') + '<span class="lbl">Abrir</span></button>' +
      '<button class="ib" data-a="more" title="Mais ações">' + svg('more') + '</button></div></div>';
  }
  function rowUser(u) {
    return '<div class="st-row db-row" data-user="' + E(u.user) + '" data-host="' + E(u.host) + '">' +
      '<div class="st-site"><span class="db-ico">' + svg('users') + '</span><div class="st-dn"><b class="mono">' + E(u.user) + '<span class="st-dim">@' + E(u.host) + '</span></b>' +
      '<small>' + (u.sites.length ? 'no .env de ' + E(u.sites.join(', ')) : 'não aparece no .env de nenhum site') + '</small></div></div>' +
      '<div class="st-tags">' + (u.dbs.length ? u.dbs.map(b => '<span class="tag mono">' + E(b) + '</span>').join('') : '<span class="st-dim">sem banco</span>') + '</div><div></div>' +
      '<div class="st-acts">' + (u.host === 'localhost' ? '<button class="ib" data-a="pass" title="Trocar senha">' + svg('key') + '<span class="lbl">Trocar senha</span></button>' : '') + '</div></div>';
  }
  function rowLite(x) {
    const i = x.path.lastIndexOf('/');
    return '<div class="st-row db-row" data-path="' + E(x.path) + '">' +
      '<div class="st-site"><span class="db-ico lite">' + svg('db') + '</span><div class="st-dn"><button type="button" class="db-name" data-a="open">' + E(x.path.slice(i + 1)) + '</button>' +
      '<small class="mono">' + E(x.path.slice(0, i)) + '</small></div></div>' +
      '<div class="st-tags"><span class="tag">' + E(x.site) + '</span>' + (x.used ? '<span class="tag t-ssl">usado pelo .env</span>' : '') + '</div>' +
      '<div class="st-size r num">' + fsize(x.size) + '</div>' +
      '<div class="st-acts"><button class="ib" data-a="open" title="Abrir tabelas e consultas">' + svg('table') + '<span class="lbl">Abrir</span></button></div></div>';
  }

  function onClick(e) {
    const b = e.target.closest('[data-a]');
    if (!b || b.disabled) return;
    const a = b.dataset.a, row = b.closest('.db-row');
    if (a === 'reload') return load();
    if (a === 'new') return createDb();
    if (!row) return;
    const d = S.data;
    if (row.dataset.db) {
      const x = d.dbs.find(y => y.name === row.dataset.db);
      if (a === 'open') return viewer({ type: 'mysql', db: x.name }, x.name);
      if (a === 'more') {
        const r = b.getBoundingClientRect();
        return menu(Math.max(6, r.right - 240), r.bottom + 4, [
          { l: 'Abrir tabelas e consultas', i: 'table', fn: () => viewer({ type: 'mysql', db: x.name }, x.name) },
          ...x.users.map(u => ({ l: 'Trocar senha de ' + u, i: 'key', fn: () => changePass(d.users.find(z => z.user === u && z.host === 'localhost') || { user: u, sites: [] }) })),
          { l: 'Copiar nome', i: 'copy', fn: () => copyText(x.name).then(() => toast('Copiado')) },
          '-', { l: 'Apagar banco…', i: 'trash', danger: true, fn: () => dropDb(x) }
        ]);
      }
    } else if (row.dataset.user) {
      if (a === 'pass') return changePass(d.users.find(u => u.user === row.dataset.user && u.host === row.dataset.host));
    } else if (row.dataset.path) {
      if (a === 'open') return viewer({ type: 'sqlite', path: row.dataset.path }, row.dataset.path.split('/').pop());
    }
  }

  /* ------------------------------------------------------------ criar / apagar / senha */
  function credsHtml(d, title) {
    return '<div class="nf-box"><div class="nf-l">' + svg('db') + ' ' + title + '</div>' +
      '<div class="nf-warn">' + svg('warn') + 'Anote agora: a senha não será mostrada de novo.</div>' +
      '<dl class="props"><dt>Banco</dt><dd><code>' + E(d.name) + '</code></dd><dt>Usuário</dt><dd><code>' + E(d.user) + '</code></dd><dt>Senha</dt><dd><code>' + E(d.pass) + '</code></dd><dt>Servidor</dt><dd><code>127.0.0.1:3306</code></dd></dl>' +
      '<div class="nf-l">Linhas para o .env</div><div class="cpl col"><pre id="envl">' + E(envLines(d)) + '</pre><button type="button" class="abtn sm" data-copy="envl">' + svg('copy') + 'Copiar .env</button></div></div>';
  }
  const bindCopy = ov => qsa('[data-copy]', ov).forEach(b => b.onclick = () => copyText(qs('#' + b.dataset.copy, ov).textContent).then(() => toast('Copiado')));

  async function createDb() {
    const r = await dialog({
      title: 'Novo banco MySQL', icon: 'db', cls: 'nfd',
      html: '<div class="nf"><div class="nf-l">Nome do banco</div><input class="fm-in mono" id="cdN" placeholder="minha_loja" spellcheck="false" autocomplete="off" autocapitalize="off">' +
        '<div class="nf-h">Letras, números e _ (ex.: loja ou loja_producao).</div>' +
        '<div class="nf-l">Usuário</div><input class="fm-in mono" id="cdU" placeholder="igual ao nome do banco" spellcheck="false" autocomplete="off" autocapitalize="off">' +
        '<div class="nf-h">Recebe acesso total só a este banco. A senha é gerada automaticamente.</div><div class="nf-err" id="cdErr"></div></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Criar banco', value: 'ok', kind: 'pri' }],
      onOpen(ov) {
        const n = qs('#cdN', ov), u = qs('#cdU', ov);
        n.addEventListener('input', () => { const v = n.value.trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_'); if (v !== n.value) n.value = v; u.placeholder = v ? v.slice(0, 32) : 'igual ao nome do banco'; });
      },
      async validate(ov) {
        const name = qs('#cdN', ov).value.trim(), user = qs('#cdU', ov).value.trim(), err = qs('#cdErr', ov);
        if (!/^[A-Za-z0-9_]{1,64}$/.test(name)) { err.textContent = 'Nome inválido.'; return false; }
        if (user && !/^[A-Za-z0-9_]{1,32}$/.test(user)) { err.textContent = 'Usuário inválido.'; return false; }
        const b = qs('.df button.pri', ov); b.disabled = true; b.textContent = 'Criando…';
        try { return { d: await api('create', { name, user }) }; }
        catch (e) { err.innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Criar banco'; return false; }
      }
    });
    if (!r) return;
    load(true);
    dialog({ title: 'Banco criado', icon: 'check', wide: true, html: '<div class="nf">' + credsHtml(r.d.db, 'Credenciais') + '</div>', buttons: [{ label: 'Concluir', value: true, kind: 'pri' }], onOpen: bindCopy });
  }

  async function dropDb(x) {
    const r = await dialog({
      title: 'Apagar o banco ' + x.name, icon: 'trash',
      html: '<p>Todas as tabelas e dados de <b>' + E(x.name) + '</b> serão apagados. Antes disso é feito um backup automático (.sql.gz) em <code>/var/backups/lkmonitor/_bancos</code>.</p>' +
        (x.sites.length ? '<div class="nf-warn">' + svg('warn') + 'Usado pelo .env de ' + E(x.sites.join(', ')) + '.</div>' : '') +
        x.only.map(u => '<label class="ck"><input type="checkbox" data-u="' + E(u) + '"> Apagar também o usuário <code>' + E(u) + '</code> (só tem acesso a este banco)</label>').join('') +
        '<div class="nf-l">Para confirmar, digite <b>' + E(x.name) + '</b></div><input class="fm-in mono" id="ddC" spellcheck="false" autocomplete="off" autocapitalize="off"><div class="nf-err" id="ddErr"></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Apagar', value: 'ok', kind: 'danger' }],
      onOpen(ov) { const i = qs('#ddC', ov), b = qs('.df button.danger', ov); const c = () => { b.disabled = i.value.trim() !== x.name; }; i.addEventListener('input', c); c(); },
      async validate(ov) {
        const conf = qs('#ddC', ov).value.trim();
        if (conf !== x.name) return false;
        const users = qsa('[data-u]', ov).filter(i => i.checked).map(i => i.dataset.u);
        const b = qs('.df button.danger', ov); b.disabled = true; b.textContent = 'Fazendo backup…';
        try { return { d: await api('drop', { name: x.name, confirm: conf, users }) }; }
        catch (e) { qs('#ddErr', ov).innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Apagar'; return false; }
      }
    });
    if (!r) return;
    toast('Banco ' + x.name + ' apagado · backup em ' + r.d.backup);
    load(true);
  }

  async function changePass(u) {
    if (!u) return;
    const r = await dialog({
      title: 'Trocar senha de ' + u.user, icon: 'key', cls: 'nfd',
      html: '<div class="nf"><label class="ck"><input type="radio" name="pm" value="gen" checked> Gerar uma senha forte</label>' +
        '<label class="ck"><input type="radio" name="pm" value="typed"> Digitar a senha</label>' +
        '<input class="fm-in mono" id="cpP" placeholder="mínimo 8 caracteres" spellcheck="false" autocomplete="new-password" hidden>' +
        (u.sites && u.sites.length ? '<div class="nf-l">Sites que usam este usuário</div>' + u.sites.map(s => '<label class="ck"><input type="checkbox" data-s="' + E(s) + '" checked> Atualizar a senha no .env de <b>' + E(s) + '</b></label>').join('') +
          '<div class="nf-h">Depois de atualizar, roda <code>php artisan config:clear</code> no site.</div>' : '<div class="nf-h">Nenhum site usa este usuário no .env; lembre de atualizar onde ele for usado.</div>') +
        '<div class="nf-err" id="cpErr"></div></div>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Trocar senha', value: 'ok', kind: 'pri' }],
      onOpen(ov) { qsa('input[name=pm]', ov).forEach(i => i.onchange = () => { const t = qs('input[name=pm]:checked', ov).value === 'typed'; qs('#cpP', ov).hidden = !t; if (t) qs('#cpP', ov).focus(); }); },
      async validate(ov) {
        const typed = qs('input[name=pm]:checked', ov).value === 'typed', pass = typed ? qs('#cpP', ov).value : '';
        if (typed && (pass.length < 8 || /[\s'"\\`$]/.test(pass))) { qs('#cpErr', ov).textContent = 'Use pelo menos 8 caracteres, sem espaços, aspas, barra invertida, crase ou $.'; return false; }
        const sites = qsa('[data-s]', ov).filter(i => i.checked).map(i => i.dataset.s);
        const b = qs('.df button.pri', ov); b.disabled = true; b.textContent = 'Trocando…';
        try { return { d: await api('password', { user: u.user, pass, sites }) }; }
        catch (e) { qs('#cpErr', ov).innerHTML = errHtml(e); b.disabled = false; b.textContent = 'Trocar senha'; return false; }
      }
    });
    if (!r) return;
    dialog({
      title: 'Senha trocada', icon: 'check',
      html: '<div class="nf"><div class="nf-warn">' + svg('warn') + 'Anote agora: a senha não será mostrada de novo.</div>' +
        '<div class="cpl"><code id="np">' + E(r.d.pass) + '</code><button type="button" class="abtn sm" data-copy="np">' + svg('copy') + 'Copiar</button></div>' +
        (r.d.updated.length ? '<p class="nf-h">.env atualizado em: ' + E(r.d.updated.join(', ')) + '</p>' : '') + '</div>',
      buttons: [{ label: 'Concluir', value: true, kind: 'pri' }], onOpen: bindCopy
    });
  }

  /* ------------------------------------------------------------ visualizador */
  function viewer(src, label) {
    const kind = src.type;
    const V = { tables: [], table: null, tab: 'data', page: 1, q: '', sort: '', desc: false, write: false, lastSql: '' };
    const el = document.createElement('div');
    el.className = 'dbv';
    el.innerHTML =
      '<div class="dbv-h"><button class="ib" data-v="close" title="Fechar (Esc)">' + svg('back') + '</button>' + svg('db') +
      '<div class="dbv-t"><b>' + E(label) + '</b><small>' + (kind === 'mysql' ? 'MySQL / MariaDB' : E(src.path)) + '</small></div>' +
      '<select class="fm-in sm dbv-sel" id="vSel"></select></div>' +
      '<div class="dbv-b"><aside class="dbv-side"><div class="st-search">' + svg('search') + '<input id="vTQ" placeholder="Filtrar tabelas" spellcheck="false" autocomplete="off"></div><div class="dbv-tl" id="vTL"><div class="st-dim">Carregando…</div></div></aside>' +
      '<section class="dbv-main"><div class="dbv-tabs"><div class="seg" id="vTabs"><button type="button" data-t="data" class="on">Dados</button><button type="button" data-t="struct">Estrutura</button><button type="button" data-t="sql">Consulta SQL</button></div><span id="vInfo" class="st-dim"></span></div>' +
      '<div class="dbv-pane" id="pData"><div class="dbv-bar"><div class="st-search">' + svg('search') + '<input id="vQ" placeholder="Buscar em todas as colunas (Enter)" spellcheck="false" autocomplete="off"></div>' +
      '<div class="dbv-pg"><button class="ib" data-v="prev" title="Página anterior">' + svg('chevL') + '</button><span id="vPg" class="num"></span><button class="ib" data-v="next" title="Próxima página">' + svg('chevR') + '</button></div>' +
      '<button class="abtn sm" data-v="exptable">' + svg('download') + 'CSV</button></div><div class="dbv-grid" id="vGrid"></div></div>' +
      '<div class="dbv-pane" id="pStruct" hidden><div class="dbv-grid" id="vCols"></div></div>' +
      '<div class="dbv-pane" id="pSql" hidden><textarea class="dbv-sql" id="vSql" spellcheck="false" placeholder="SELECT * FROM tabela LIMIT 50"></textarea>' +
      '<div class="dbv-bar"><button class="abtn pri" data-v="run">' + svg('play') + 'Executar <small>Ctrl+Enter</small></button>' +
      '<button type="button" class="sw" id="vW" data-v="write"><i></i><span>Permitir alterações</span></button>' +
      '<span class="sp"></span><button class="abtn sm" data-v="expsql" disabled>' + svg('download') + 'Exportar CSV</button></div>' +
      '<div class="dbv-res st-dim" id="vRes">Somente leitura: SELECT, SHOW, DESCRIBE, EXPLAIN' + (kind === 'sqlite' ? ', PRAGMA' : '') + '. Até 1000 linhas na tela, 30 s por consulta.</div><div class="dbv-grid" id="vOut"></div></div>' +
      '</section></div>';
    document.body.appendChild(el);
    document.body.style.overflow = 'hidden';
    const $ = s => qs(s, el);
    const close = () => { el.remove(); document.body.style.overflow = ''; document.removeEventListener('keydown', key, true); };
    const key = e => { if (e.key === 'Escape' && !qs('.fm-ov') && !qs('#fmMenu')) { e.preventDefault(); close(); } };
    document.addEventListener('keydown', key, true);

    const grid = (cols, rows, sortable) => {
      if (!cols.length) return '<div class="st-empty">Nenhuma coluna.</div>';
      return '<table><thead><tr>' + cols.map(c => '<th' + (sortable ? ' data-sort="' + E(c) + '"' : '') + '>' + E(c) + (sortable && V.sort === c ? (V.desc ? ' ↓' : ' ↑') : '') + '</th>').join('') + '</tr></thead><tbody>' +
        (rows.length ? rows.map(r => '<tr>' + r.map(v => v === null ? '<td class="nul">NULL</td>' : '<td title="' + E(String(v).slice(0, 300)) + '">' + E(v) + '</td>').join('') + '</tr>').join('')
          : '<tr><td colspan="' + cols.length + '" class="st-dim">Nenhuma linha.</td></tr>') + '</tbody></table>';
    };

    async function loadTables() {
      try {
        V.tables = (await api('tables', { src })).tables;
        renderTables();
        $('#vSel').innerHTML = V.tables.map(t => '<option value="' + E(t.name) + '">' + E(t.name) + ' (' + (t.rows == null ? '?' : (t.exact ? '' : '~') + num(t.rows)) + ')</option>').join('');
        if (V.tables.length) pick(V.tables[0].name);
        else { $('#vGrid').innerHTML = '<div class="st-empty">' + svg('table') + '<b>Banco sem tabelas</b><span>Use a aba Consulta SQL ou rode as migrations do site.</span></div>'; setTab('sql'); }
      } catch (e) { $('#vTL').innerHTML = '<div class="fm-err">' + E(e.message) + '</div>'; }
    }
    function renderTables() {
      const f = $('#vTQ').value.trim().toLowerCase();
      const v = V.tables.filter(t => !f || t.name.toLowerCase().includes(f));
      $('#vTL').innerHTML = v.length ? v.map(t => '<button type="button" class="dbv-ti' + (t.name === V.table ? ' on' : '') + '" data-tb="' + E(t.name) + '">' + svg(t.view ? 'eye' : 'table') + '<span>' + E(t.name) + '</span><small class="num">' +
        (t.rows == null ? '' : (t.exact ? '' : '~') + num(t.rows)) + '</small></button>').join('') : '<div class="st-dim">Nenhuma tabela.</div>';
    }
    function pick(name) {
      V.table = name; V.page = 1; V.q = ''; V.sort = ''; V.desc = false; $('#vQ').value = '';
      $('#vSel').value = name; renderTables();
      if (!$('#vSql').value.trim()) $('#vSql').value = 'SELECT * FROM ' + (kind === 'mysql' ? '`' + name + '`' : '"' + name + '"') + ' LIMIT 50';
      if (V.tab === 'sql') setTab('data'); else refresh();
    }
    function setTab(t) {
      V.tab = t;
      qsa('#vTabs button', el).forEach(b => b.classList.toggle('on', b.dataset.t === t));
      $('#pData').hidden = t !== 'data'; $('#pStruct').hidden = t !== 'struct'; $('#pSql').hidden = t !== 'sql';
      if (t === 'sql') { $('#vInfo').textContent = ''; setTimeout(() => $('#vSql').focus(), 30); } else refresh();
    }
    async function refresh() {
      if (!V.table) return;
      const t = V.table;
      if (V.tab === 'data') {
        $('#vGrid').classList.add('busy');
        try {
          const d = await api('rows', { src, table: t, page: V.page, q: V.q, sort: V.sort, desc: V.desc });
          if (t !== V.table) return;
          $('#vGrid').innerHTML = grid(d.columns, d.rows, true);
          V.page = d.page; V.pages = d.pages;
          $('#vPg').textContent = d.page + ' / ' + d.pages;
          $('#vInfo').textContent = num(d.total) + (d.total === 1 ? ' linha' : ' linhas') + (V.q ? ' com “' + V.q + '”' : '') + ' · 50 por página';
          qs('[data-v=prev]', el).disabled = d.page <= 1; qs('[data-v=next]', el).disabled = d.page >= d.pages;
        } catch (e) { $('#vGrid').innerHTML = '<div class="fm-err">' + E(e.message) + '</div>'; }
        $('#vGrid').classList.remove('busy');
      } else if (V.tab === 'struct') {
        try {
          const d = await api('columns', { src, table: t });
          $('#vCols').innerHTML = grid(['Coluna', 'Tipo', 'Nulo', 'Chave', 'Padrão', 'Extra'], d.columns.map(c => [c.name, c.type, c.null ? 'sim' : 'não', c.key || '', c.default, c.extra || '']), false);
          $('#vInfo').textContent = d.columns.length + ' colunas';
        } catch (e) { $('#vCols').innerHTML = '<div class="fm-err">' + E(e.message) + '</div>'; }
      }
    }
    async function runSql() {
      const sql = $('#vSql').value.trim();
      if (!sql) return;
      const isWrite = /^\s*(insert|update|delete|replace)\b/i.test(sql.replace(/^(\s*(--[^\n]*\n|\/\*[\s\S]*?\*\/))*/, ''));
      if (isWrite && V.write && !(await confirmDlg('Executar alteração?', 'Este comando vai <b>alterar dados</b> em <b>' + E(label) + '</b> e não pode ser desfeito pelo painel:<pre class="nf-pre">' + E(sql.slice(0, 600)) + '</pre>', 'Executar', true))) return;
      const b = qs('[data-v=run]', el); b.disabled = true;
      $('#vRes').textContent = 'Executando…'; $('#vRes').className = 'dbv-res st-dim';
      try {
        const d = await api('query', { src, sql, write: V.write });
        if (d.affected != null && !d.columns.length) {
          $('#vRes').innerHTML = svg('check') + ' ' + num(d.affected) + (d.affected === 1 ? ' linha alterada' : ' linhas alteradas') + ' em ' + d.ms + ' ms';
          $('#vRes').className = 'dbv-res ok'; $('#vOut').innerHTML = ''; qs('[data-v=expsql]', el).disabled = true;
          const tb = await api('tables', { src }).catch(() => null); if (tb) { V.tables = tb.tables; renderTables(); }
        } else {
          $('#vRes').textContent = num(d.rows.length) + (d.rows.length === 1 ? ' linha' : ' linhas') + (d.more ? ' (mostrando as primeiras; exporte para ver mais)' : '') + ' em ' + d.ms + ' ms';
          $('#vRes').className = 'dbv-res';
          $('#vOut').innerHTML = grid(d.columns, d.rows, false);
          V.lastSql = sql; qs('[data-v=expsql]', el).disabled = false;
        }
      } catch (e) {
        $('#vRes').innerHTML = '<span class="e">' + E(e.message) + '</span>' + (e.data && e.data.needs_write ? ' <button type="button" class="lnk" data-v="write">Permitir alterações</button>' : '');
        $('#vRes').className = 'dbv-res err';
      }
      b.disabled = false;
    }
    async function exportCsv(body, name) {
      try {
        toast('Preparando o CSV…');
        const r = await api('export', Object.assign({ src }, body), true);
        if (!(r instanceof Response)) throw new Error('Falha ao exportar');
        const blob = await r.blob(), a = document.createElement('a');
        const cd = r.headers.get('Content-Disposition') || '', m = /filename="([^"]+)"/.exec(cd);
        a.href = URL.createObjectURL(blob); a.download = m ? m[1] : (name || 'resultado') + '.csv'; document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 4000);
        if (r.headers.get('X-LKM-More') === '1') toast('CSV com as primeiras 20.000 linhas', 'er');
      } catch (e) { fail(e); }
    }
    function setWrite(on) {
      V.write = on; const w = $('#vW');
      w.classList.toggle('on', on); w.classList.toggle('danger', on);
      $('#pSql').classList.toggle('writing', on);
      if (on) { $('#vRes').innerHTML = svg('warn') + ' Alterações liberadas: INSERT, UPDATE e DELETE pedem confirmação antes de rodar.'; $('#vRes').className = 'dbv-res warn'; }
      else { $('#vRes').textContent = 'Somente leitura.'; $('#vRes').className = 'dbv-res st-dim'; }
    }

    el.addEventListener('click', async e => {
      const t = e.target.closest('[data-tb]'); if (t) return pick(t.dataset.tb);
      const tab = e.target.closest('#vTabs button'); if (tab) return setTab(tab.dataset.t);
      const th = e.target.closest('th[data-sort]');
      if (th) { const c = th.dataset.sort; if (V.sort === c) V.desc = !V.desc; else { V.sort = c; V.desc = false; } V.page = 1; return refresh(); }
      const b = e.target.closest('[data-v]'); if (!b || b.disabled) return;
      const a = b.dataset.v;
      if (a === 'close') close();
      else if (a === 'prev' && V.page > 1) { V.page--; refresh(); }
      else if (a === 'next' && V.page < (V.pages || 1)) { V.page++; refresh(); }
      else if (a === 'run') runSql();
      else if (a === 'write') {
        if (V.write) return setWrite(false);
        if (await confirmDlg('Permitir alterações?', 'Libera <b>INSERT</b>, <b>UPDATE</b> e <b>DELETE</b> na consulta SQL deste banco. Cada comando ainda pede confirmação.', 'Permitir', true)) setWrite(true);
      } else if (a === 'exptable' && V.table) exportCsv({ table: V.table }, V.table);
      else if (a === 'expsql' && V.lastSql) exportCsv({ sql: V.lastSql }, 'consulta');
    });
    $('#vTQ').addEventListener('input', renderTables);
    $('#vSel').addEventListener('change', e => pick(e.target.value));
    $('#vQ').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); V.q = e.target.value.trim(); V.page = 1; refresh(); } });
    $('#vSql').addEventListener('keydown', e => {
      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); runSql(); }
      else if (e.key === 'Tab') { e.preventDefault(); const t = e.target, p = t.selectionStart; t.value = t.value.slice(0, p) + '  ' + t.value.slice(t.selectionEnd); t.selectionStart = t.selectionEnd = p + 2; }
    });
    loadTables();
  }

  /* ------------------------------------------------------------ inicialização */
  window.DB = {
    show() {
      if (!qs('#bancos')) return;
      if (!inited) { inited = true; build(); load(); }
      else load(true);
    }
  };
  if (location.hash === '#bancos') window.DB.show();
})();
LKM_EOF_DBJS
cat > "$DIR/config.js" <<'LKM_EOF_CONFJS'
/* LK Monitor - aba Config: alertas, canais (Telegram / WhatsApp), histórico de alertas e backup automático */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const { E, qs, qsa, toast, fail, confirmDlg, svg } = U;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const TOKEN = C0.token || '';
  const ROOT = C0.user === 'root';
  let root, inited = false, D = null, BK = null, waMode = 'webhook', waSeq = 0;

  async function req(url, body) {
    let r;
    try {
      r = await fetch(url, body === undefined ? { credentials: 'same-origin', cache: 'no-store' }
        : { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': TOKEN }, body: JSON.stringify(body) });
    } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do servidor (' + r.status + ')'); }
    if (!d.ok) { const er = new Error(d.error || 'Erro desconhecido'); er.data = d; throw er; }
    return d;
  }
  const p2 = n => String(n).padStart(2, '0');
  const fdt = t => { const d = new Date(t * 1000); return p2(d.getDate()) + '/' + p2(d.getMonth() + 1) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes()); };
  const sw = (id, on) => '<button type="button" class="sw' + (on ? ' on' : '') + '" id="' + id + '" data-sw><i></i></button>';
  const num = (id, v, min, max, w) => '<input type="number" class="fm-in sm cf-num" id="' + id + '" value="' + E(v) + '" min="' + min + '" max="' + max + '"' + (w ? ' style="width:' + w + 'px"' : '') + '>';

  function build() {
    root = qs('#config');
    root.innerHTML =
      '<section class="cf-grid">' +
      '<div class="card cf-card"><div class="ct"><h2>' + svg('bell') + 'Alertas</h2><span id="cfAct"></span></div><div id="cfRules"></div></div>' +
      '<div class="card cf-card"><div class="ct"><h2>' + svg('send') + 'Canais de aviso</h2></div><div id="cfCh"></div></div>' +
      '</section>' +
      '<div class="cf-save"><span id="cfMsg" class="st-dim"></span><button type="button" class="abtn pri" id="cfSave">' + svg('save') + 'Salvar alertas e canais</button></div>' +
      '<section class="cf-grid">' +
      '<div class="card cf-card"><div class="ct"><h2>' + svg('archive') + 'Backup automático</h2><span id="bkNext"></span></div><div id="cfBk"></div></div>' +
      '<div class="card cf-card"><div class="ct"><h2>' + svg('log') + 'Histórico de alertas</h2><button type="button" class="lnk" id="cfClr">limpar</button></div><div id="cfHist" class="cf-hist"></div></div>' +
      '</section>';
    qs('#cfSave').onclick = save;
    qs('#cfClr').onclick = clearHist;
    root.addEventListener('click', e => { const b = e.target.closest('[data-sw]'); if (b && !b.disabled) { b.classList.toggle('on'); dirty(); } });
    root.addEventListener('input', e => { if (e.target.closest('#cfRules,#cfCh')) dirty(); });
  }
  const dirty = () => { qs('#cfMsg').textContent = 'alterações não salvas'; qs('#cfMsg').className = 'cf-dirty'; };

  async function load() {
    try { D = await req('?cfg=get'); } catch (e) { qs('#cfRules').innerHTML = '<div class="fm-err">' + E(e.message) + '</div>'; return; }
    renderRules(); renderCh(); renderHist();
    qs('#cfMsg').textContent = ''; qs('#cfMsg').className = 'st-dim';
    loadBk();
  }

  function renderRules() {
    const r = D.settings.rules, act = D.active || [];
    qs('#cfAct').innerHTML = act.length ? '<span class="jst error">' + act.length + ' alerta' + (act.length > 1 ? 's' : '') + ' ativo' + (act.length > 1 ? 's' : '') + '</span>' : '<span class="jst ok">tudo normal</span>';
    const row = (k, html, hint) => '<div class="cf-rule">' + sw('r_' + k, r[k].on) + '<div><div class="cf-rt">' + html + '</div>' + (hint ? '<small>' + hint + '</small>' : '') + '</div></div>';
    qs('#cfRules').innerHTML =
      row('temp', 'Temperatura da CPU acima de ' + num('temp_l', r.temp.limit, 30, 150) + ' °C por ' + num('temp_m', r.temp.minutes, 1, 120) + ' min') +
      row('disk', 'Disco acima de ' + num('disk_l', r.disk.limit, 1, 100) + ' % de uso', 'vale para cada disco montado') +
      row('ram', 'Memória RAM acima de ' + num('ram_l', r.ram.limit, 1, 100) + ' % por ' + num('ram_m', r.ram.minutes, 1, 120) + ' min') +
      row('service', 'Serviço parado', D.services.length ? 'verifica: ' + E(D.services.join(', ')) : 'nenhum dos serviços conhecidos está instalado') +
      row('site', 'Site fora do ar', D.sites.length ? 'testa ' + D.sites.length + ' site' + (D.sites.length > 1 ? 's' : '') + ' ligado' + (D.sites.length > 1 ? 's' : '') + ' em 127.0.0.1 (sem resposta ou erro 5xx, 2 vezes seguidas)' : 'nenhum site ligado no momento') +
      row('ssh', 'Mais de ' + num('ssh_l', r.ssh.limit, 1, 100000, 76) + ' falhas de login no SSH em 10 min') +
      '<div class="cf-rep">Repetir o mesmo alerta a cada ' + num('repeat', D.settings.repeat, 5, 1440, 70) + ' min enquanto continuar. Quando volta ao normal, também avisa.</div>';
  }

  function renderCh() {
    const t = D.settings.telegram, w = D.settings.whatsapp;
    qs('#cfCh').innerHTML =
      '<div class="cf-ch"><div class="cf-chh">' + sw('t_on', t.on) + '<b>Telegram</b><button type="button" class="abtn sm" data-test="telegram">' + svg('send') + 'Enviar teste</button></div>' +
      '<div class="cf-f"><label>Token do bot</label><input class="fm-in mono" id="t_token" value="' + E(t.token) + '" placeholder="123456789:AA..." autocomplete="off" spellcheck="false"></div>' +
      '<div class="cf-f"><label>Chat id</label><input class="fm-in mono" id="t_chat" value="' + E(t.chat) + '" placeholder="ex.: 123456789 ou -100..." autocomplete="off"></div>' +
      '<small class="cf-h">Crie o bot com o <b>@BotFather</b>, mande uma mensagem para ele e pegue o seu chat id com o <b>@userinfobot</b>.' + (t.token_set ? ' O token salvo aparece mascarado; deixe como está para manter.' : '') + '</small></div>' +
      '<div class="cf-ch"><div class="cf-chh">' + sw('w_on', w.on) + '<b id="wTitle"></b><button type="button" class="abtn sm" data-test="whatsapp">' + svg('send') + 'Enviar teste</button></div>' +
      (D.gowa ? '<div id="wGowa"><div class="wa-st" id="waSt"><i></i><span>Verificando o número…</span></div>' +
        '<div class="cf-f"><label>Números de destino</label><input class="fm-in mono" id="w_numbers" value="' + E(w.numbers) + '" placeholder="5511999998888, 5521988887777" autocomplete="off" spellcheck="false" inputmode="tel"></div>' +
        '<small class="cf-h">Só dígitos, com código do país e DDD (55 para o Brasil). Para avisar mais de uma pessoa, separe por vírgula. As mensagens saem pelo número conectado neste servidor.</small>' +
        '<button type="button" class="lnk cf-alt" id="waHook">Usar outro gateway</button></div>' : '') +
      '<div id="wHook"><div class="cf-row"><div class="cf-f" style="flex:0 0 110px"><label>Método</label><select class="fm-in" id="w_method">' + ['POST', 'GET', 'PUT'].map(m => '<option' + (w.method === m ? ' selected' : '') + '>' + m + '</option>').join('') + '</select></div>' +
      '<div class="cf-f" style="flex:1"><label>URL do gateway</label><input class="fm-in mono" id="w_url" value="' + E(w.url) + '" placeholder="https://seu-gateway/api/send-message" autocomplete="off" spellcheck="false"></div></div>' +
      '<div class="cf-f"><label>Cabeçalhos <small>(um por linha)</small></label><textarea class="fm-in mono cf-ta" id="w_headers" rows="2" placeholder="Authorization: Bearer seu-token" spellcheck="false">' + E(w.headers) + '</textarea></div>' +
      '<div class="cf-f"><label>Corpo (JSON) <small>variáveis {phone} e {message}</small></label><textarea class="fm-in mono cf-ta" id="w_body" rows="3" spellcheck="false">' + E(w.body) + '</textarea></div>' +
      '<div class="cf-f"><label>Número de destino</label><input class="fm-in mono" id="w_phone" value="' + E(w.phone) + '" placeholder="5511999998888" autocomplete="off"></div>' +
      '<small class="cf-h">Funciona com Wablas, GOWA ou qualquer gateway que receba uma requisição HTTP. Valores dos cabeçalhos salvos aparecem mascarados; deixe a linha como está para manter.</small>' +
      (D.gowa ? '<button type="button" class="lnk cf-alt" id="waLocal">Usar o WhatsApp deste servidor</button>' : '') + '</div></div>';
    qsa('[data-test]', qs('#cfCh')).forEach(b => b.onclick = () => test(b));
    waMode = D.gowa && w.mode_eff === 'gowa' ? 'gowa' : 'webhook';
    if (D.gowa) {
      qs('#waHook').onclick = () => { setWa('webhook'); dirty(); };
      qs('#waLocal').onclick = () => { setWa('gowa'); dirty(); };
    }
    setWa(waMode);
  }

  /** Alterna o canal WhatsApp entre o serviço deste servidor e um gateway próprio (webhook). */
  function setWa(mode) {
    waMode = D.gowa ? mode : 'webhook';
    qs('#wTitle').textContent = waMode === 'gowa' ? 'WhatsApp deste servidor' : 'WhatsApp (gateway próprio)';
    if (qs('#wGowa')) qs('#wGowa').hidden = waMode !== 'gowa';
    qs('#wHook').hidden = waMode === 'gowa';
    if (waMode === 'gowa') waStatus();
  }

  async function waStatus() {
    const box = qs('#waSt'); if (!box) return;
    const seq = ++waSeq;
    box.className = 'wa-st'; box.innerHTML = '<i></i><span>Verificando o número…</span>';
    let d;
    let g = D.gowa || {};
    try { const r = await req('?cfg=wa_status'); d = r.st; g = r.gowa || g; } catch (e) { d = { ok: false, logged: null, error: e.message }; }
    if (seq !== waSeq || !qs('#waSt')) return;
    const host = location.hostname.includes(':') ? '[' + location.hostname + ']' : location.hostname;
    const page = g.page_port ? '<a href="http://' + E(host) + ':' + E(g.page_port) + '/" target="_blank" rel="noopener">Abrir página do WhatsApp</a>' : '';
    const st = d.logged === true ? ['ok', 'Conectado'] : d.ok ? ['er', 'Número desconectado'] : ['er', 'Serviço do WhatsApp parado'];
    box.className = 'wa-st ' + st[0];
    box.innerHTML = '<i></i><b>' + st[1] + '</b>' + page + '<button type="button" class="lnk" id="waRe" title="Verificar de novo">' + svg('refresh') + '</button>' +
      (d.logged !== true ? '<small>' + E(d.error || 'Abra a página do WhatsApp e leia o QR code com o celular.') + '</small>' : '');
    qs('#waRe').onclick = waStatus;
  }

  function collect() {
    const on = id => qs('#' + id).classList.contains('on'), v = id => qs('#' + id).value;
    return {
      repeat: +v('repeat'),
      rules: {
        temp: { on: on('r_temp'), limit: +v('temp_l'), minutes: +v('temp_m') }, disk: { on: on('r_disk'), limit: +v('disk_l') },
        ram: { on: on('r_ram'), limit: +v('ram_l'), minutes: +v('ram_m') }, service: { on: on('r_service') }, site: { on: on('r_site') }, ssh: { on: on('r_ssh'), limit: +v('ssh_l') }
      },
      telegram: { on: on('t_on'), token: v('t_token'), chat: v('t_chat') },
      whatsapp: Object.assign({ on: on('w_on'), mode: waMode, method: v('w_method'), url: v('w_url'), headers: v('w_headers'), body: v('w_body'), phone: v('w_phone') },
        qs('#w_numbers') ? { numbers: v('w_numbers') } : {})
    };
  }

  async function save() {
    const b = qs('#cfSave'); b.disabled = true;
    try {
      const d = await req('?cfg=save', { settings: collect() });
      D.settings = d.settings; renderRules(); renderCh();
      qs('#cfMsg').textContent = 'salvo'; qs('#cfMsg').className = 'cf-ok';
      toast('Alertas e canais salvos');
    } catch (e) { fail(e); }
    b.disabled = false;
  }

  async function test(b) {
    const ch = b.dataset.test, lbl = b.innerHTML;
    b.disabled = true; b.textContent = 'Enviando…';
    try { await req('?cfg=test', { channel: ch, settings: collect() }); toast('Mensagem de teste enviada pelo ' + (ch === 'telegram' ? 'Telegram' : 'WhatsApp')); }
    catch (e) { fail(e); }
    if (ch === 'whatsapp' && waMode === 'gowa') waStatus();
    b.disabled = false; b.innerHTML = lbl;
  }

  function renderHist() {
    const h = D.history || [];
    const ico = { alert: 'warn', repeat: 'warn', ok: 'check' };
    qs('#cfHist').innerHTML = h.length ? h.map(x => '<div class="cf-hi ' + x.kind + '">' + svg(ico[x.kind] || 'info') + '<div><div>' + E(x.msg) + '</div><small>' + fdt(x.t) + ' · ' +
      (x.sent && Object.keys(x.sent).length ? Object.entries(x.sent).map(([c, r]) => '<span class="' + (r === true ? 'ok' : 'er') + '" title="' + E(r === true ? 'enviado' : r) + '">' + (c === 'telegram' ? 'Telegram' : 'WhatsApp') + (r === true ? ' ✓' : ' ✗') + '</span>').join(' ') : 'nenhum canal ativo') +
      '</small></div></div>').join('') : '<div class="st-empty">' + svg('bell') + '<b>Nenhum alerta até agora</b><span>As regras são verificadas a cada minuto pelo coletor.</span></div>';
  }

  async function clearHist() {
    if (!(await confirmDlg('Limpar histórico?', 'Apaga a lista dos últimos alertas (as regras continuam valendo).', 'Limpar', true))) return;
    try { await req('?cfg=clear', {}); D.history = []; renderHist(); } catch (e) { fail(e); }
  }

  /* ------------------------------------------------------------ backup automático */
  async function loadBk() {
    const box = qs('#cfBk');
    if (!ROOT) { box.innerHTML = '<div class="st-ro" style="margin:0">' + svg('lock') + '<div>Precisa de acesso root no painel (sudo lk › 33 › 1 › escolha root).</div></div>'; return; }
    try { BK = await req('?sites=backup_cfg', {}); } catch (e) { box.innerHTML = '<div class="fm-err">' + E(e.message) + '</div>'; return; }
    const c = BK.cfg;
    qs('#bkNext').textContent = BK.next ? 'próxima: ' + fdt(BK.next) : '';
    box.innerHTML =
      '<div class="cf-rule">' + sw('b_on', c.enabled) + '<div><div class="cf-rt">Todo dia às <input type="time" class="fm-in sm" id="b_time" value="' + E(c.time) + '"> e manter os últimos ' + num('b_keep', c.keep, 1, 365, 64) + ' backups automáticos de cada site</div>' +
      '<small>Backups manuais e os feitos antes de restaurar não são apagados. Arquivos em /var/backups/lkmonitor/&lt;site&gt;/</small></div></div>' +
      '<div class="nf-l">Sites incluídos</div>' +
      (BK.sites.length ? '<div class="cf-sites">' + BK.sites.map(s => '<label class="ck"><input type="checkbox" data-bs="' + E(s) + '"' + (c.sites.includes(s) ? ' checked' : '') + '> ' + E(s) + '</label>').join('') + '</div>' : '<div class="st-dim">Nenhum site criado ainda.</div>') +
      '<div class="cf-save in"><span id="bkMsg" class="st-dim"></span><button type="button" class="abtn pri" id="bkSave">' + svg('save') + 'Salvar backup automático</button></div>';
    qs('#bkSave').onclick = async () => {
      const cfg = { enabled: qs('#b_on').classList.contains('on'), time: qs('#b_time').value, keep: +qs('#b_keep').value, sites: qsa('[data-bs]', box).filter(i => i.checked).map(i => i.dataset.bs) };
      const b = qs('#bkSave'); b.disabled = true;
      try { await req('?sites=backup_cfg_set', { cfg }); toast('Backup automático salvo'); await loadBk(); }
      catch (e) { fail(e); b.disabled = false; }
    };
  }

  window.CONF = {
    show() {
      if (!qs('#config')) return;
      if (!inited) { inited = true; build(); }
      load();
    }
  };
  if (location.hash === '#config') window.CONF.show();
})();
LKM_EOF_CONFJS
cat > "$DIR/term.js" <<'LKM_EOF_TERMJS'
/* LK Monitor - terminal completo (xterm.js + serviço lkmonitor-term)
 * Cada aba é um shell de verdade no servidor (nano, htop, o menu do lk, Ctrl+C...).
 * As sessões continuam vivas por um tempo quando a página fecha e voltam como estavam.
 */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const { E, qs, qsa, toast, svg } = U;
  const $ = id => document.getElementById(id);
  const coarse = U.coarse;
  const ls = {
    get(k, d) { try { const v = localStorage.getItem('lkm.term.' + k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem('lkm.term.' + k, JSON.stringify(v)); } catch (e) { } }
  };

  // ícones que o gerenciador de arquivos ainda não tem
  Object.assign(U.IC, {
    expand: '<path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/>',
    shrink: '<path d="M4 14h6v6M20 10h-6V4M14 10l7-7M3 21l7-7"/>',
    minus: '<path d="M5 12h14"/>',
    zap: '<path d="M13 2 3 14h9l-1 8 10-12h-9z"/>'
  });

  /* ------------------------------------------------------------ xterm.js: cópia local (baixada pelo instalador) ou CDN */
  const XV = '5.5.0', FV = '0.10.0';
  const SOURCES = [
    { css: 'vendor/xterm/xterm.css?v=' + XV, js: 'vendor/xterm/xterm.js?v=' + XV, fit: 'vendor/xterm/addon-fit.js?v=' + FV },
    { css: 'https://cdn.jsdelivr.net/npm/@xterm/xterm@' + XV + '/css/xterm.css', js: 'https://cdn.jsdelivr.net/npm/@xterm/xterm@' + XV + '/lib/xterm.js', fit: 'https://cdn.jsdelivr.net/npm/@xterm/addon-fit@' + FV + '/lib/addon-fit.js' },
    { css: 'https://unpkg.com/@xterm/xterm@' + XV + '/css/xterm.css', js: 'https://unpkg.com/@xterm/xterm@' + XV + '/lib/xterm.js', fit: 'https://unpkg.com/@xterm/addon-fit@' + FV + '/lib/addon-fit.js' }
  ];
  function tag(url) {
    return new Promise((res, rej) => {
      let el;
      if (/\.css(\?|$)/.test(url)) { el = document.createElement('link'); el.rel = 'stylesheet'; el.href = url; }
      else { el = document.createElement('script'); el.src = url; el.async = false; }
      const t = setTimeout(() => { el.remove(); rej(new Error('demorou')); }, 10000);
      el.onload = () => { clearTimeout(t); res(el); };
      el.onerror = () => { clearTimeout(t); el.remove(); rej(new Error('falhou')); };
      document.head.appendChild(el);
    });
  }
  let libP = null;
  function loadLib() {
    if (window.Terminal) return Promise.resolve();
    if (libP) return libP;
    libP = (async () => {
      for (const s of SOURCES) {
        try {
          const css = await tag(s.css);
          try { await tag(s.js); await tag(s.fit).catch(() => null); } catch (e) { css.remove(); throw e; }
          if (window.Terminal) return;
        } catch (e) { /* tenta a próxima fonte */ }
      }
      libP = null;
      throw new Error('Não foi possível carregar o terminal (xterm.js). Atualize o LK Monitor com o servidor ligado à internet, ou use o modo simples.');
    })();
    return libP;
  }

  /* ------------------------------------------------------------ API do painel */
  async function api(act, body) {
    let r;
    try {
      r = await fetch('?term=' + act, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': C0.token || '' }, body: JSON.stringify(body || {}) });
    } catch (e) { const er = new Error('Sem conexão com o painel'); er.net = true; throw er; }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do painel (' + r.status + ')'); }
    if (!d.ok) { const er = new Error(d.error || 'Erro'); er.down = !!d.down; er.off = !!d.off; throw er; }
    return d;
  }

  /* ------------------------------------------------------------ estado */
  const THEME = {
    background: '#05070c', foreground: '#cfd7e6', cursor: '#9cc2ff', cursorAccent: '#05070c', selectionBackground: '#5b9cff55',
    black: '#1e2940', red: '#ff7b72', green: '#7ee787', yellow: '#f5c542', blue: '#5b9cff', magenta: '#c08bff', cyan: '#22d3ee', white: '#cfd7e6',
    brightBlack: '#56627d', brightRed: '#ffa198', brightGreen: '#a5f0b0', brightYellow: '#ffd866', brightBlue: '#9cc2ff', brightMagenta: '#d7b8ff', brightCyan: '#67e8f9', brightWhite: '#ffffff'
  };
  const FONT = '"JetBrains Mono", "Cascadia Mono", ui-monospace, "SFMono-Regular", Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace';
  const QUICK = ['lk', 'htop', 'lk status', 'lk sites', 'df -h', 'free -h', 'ip -br a', 'systemctl --failed', 'journalctl -f -n 50', 'tail -f /var/log/apache2/error.log'];
  const S = { tabs: [], cur: null, built: false, mode: ls.get('mode', 'full'), fs: ls.get('fs', coarse ? 12 : 13), full: false, ctrl: false, alt: false, n: 0, error: '' };
  let root, host, visible = false;
  const canFull = () => !!(C0.user && C0.term);
  const active = () => visible && S.mode === 'full' && canFull() && !S.error;

  /* ------------------------------------------------------------ montagem */
  function build() {
    root = $('xt');
    root.innerHTML =
      '<div class="xt" id="xtBox">' +
      '<div class="xt-bar"><div class="xt-tabs" id="xtTabs"></div>' +
      '<button class="ib xt-new" data-x="new" title="Novo terminal">' + svg('plus') + '</button><span class="sp"></span>' +
      '<button class="ib" data-x="quick" title="Comandos rápidos">' + svg('zap') + '<span class="lbl">Comandos</span></button>' +
      '<button class="ib" data-x="copy" title="Copiar seleção (Ctrl+Shift+C)">' + svg('copy') + '<span class="lbl">Copiar</span></button>' +
      '<button class="ib" data-x="paste" title="Colar (Ctrl+Shift+V)">' + svg('paste') + '<span class="lbl">Colar</span></button>' +
      '<button class="ib" data-x="font-" title="Diminuir letra">' + svg('minus') + '</button>' +
      '<button class="ib" data-x="font+" title="Aumentar letra">' + svg('plus') + '</button>' +
      '<button class="ib" data-x="full" id="xtFullBtn" title="Tela cheia">' + svg('expand') + '</button>' +
      '<button class="ib" data-x="more" title="Mais opções">' + svg('more') + '</button></div>' +
      '<div class="xt-wrap"><div class="xt-host" id="xtHost"></div><div class="xt-msg" id="xtMsg" hidden></div></div>' +
      '<div class="xt-keys" id="xtKeys">' + KEYS.map(k => '<button type="button" data-k="' + E(k[0]) + '"' + (k[2] ? ' class="' + k[2] + '"' : '') + '>' + k[1] + '</button>').join('') + '</div>' +
      '<div class="xt-foot"><span class="ubadge' + (C0.user === 'root' ? ' root' : '') + '">' + E(C0.user === 'root' ? 'root · acesso total' : C0.user || '') + '</span><span id="xtSt"></span><span class="sp"></span>' +
      '<span class="xt-hint">Ctrl+C com texto selecionado copia · Ctrl+Shift+V cola · o terminal continua aberto se você sair da página</span></div>' +
      '</div>';
    host = $('xtHost');
    root.addEventListener('click', onBar);
    const keys = $('xtKeys');
    keys.addEventListener('pointerdown', e => { if (e.target.closest('button')) e.preventDefault(); }); // não fecha o teclado do celular
    keys.addEventListener('click', e => { const b = e.target.closest('button[data-k]'); if (b) key(b.dataset.k); });
    window.addEventListener('resize', fitSoon);
    if (window.visualViewport) window.visualViewport.addEventListener('resize', fitSoon);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) S.tabs.forEach(t => { if (t.state === 'off') connect(t); }); });
    window.addEventListener('online', () => S.tabs.forEach(t => { if (t.state === 'off') connect(t); }));
    S.built = true;
  }

  // teclas extras para o celular: [valor, rótulo, classe]
  const KEYS = [['esc', 'Esc'], ['tab', 'Tab'], ['ctrl', 'Ctrl', 'mod'], ['alt', 'Alt', 'mod'], ['up', '↑'], ['down', '↓'], ['left', '←'], ['right', '→'],
    ['|', '|'], ['/', '/'], ['-', '-'], ['~', '~'], ['home', 'Home'], ['end', 'End'], ['pgup', 'PgUp'], ['pgdn', 'PgDn'], ['^c', 'Ctrl+C'], ['^d', 'Ctrl+D'], ['^z', 'Ctrl+Z']];

  /* ------------------------------------------------------------ tamanho */
  let fitT = 0;
  function fitSoon() { clearTimeout(fitT); fitT = setTimeout(fit, 60); }
  function layout() {
    const box = $('xtBox'); if (!box || !visible) return;
    const vv = window.visualViewport;
    if (S.full) {                                     // tela cheia: acompanha o teclado do celular
      box.style.top = (vv ? vv.offsetTop : 0) + 'px';
      box.style.height = (vv ? vv.height : window.innerHeight) + 'px';
      return;
    }
    box.style.top = '';
    // altura que cabe na tela com a página no topo (não depende da rolagem, senão a caixa "anda" enquanto rola)
    const avail = vv ? vv.height : window.innerHeight;
    const top = box.getBoundingClientRect().top + window.scrollY;
    box.style.height = Math.max(260, Math.floor(avail - top - (innerWidth <= 600 ? 8 : 16))) + 'px';
  }
  function fit() {
    if (!visible || !S.cur) return;
    layout();
    const t = S.cur;
    if (t.fit) { try { t.fit.fit(); } catch (e) { } }
  }

  /* ------------------------------------------------------------ abas */
  function paintTabs() {
    const el = $('xtTabs'); if (!el) return;
    el.innerHTML = S.tabs.map((t, i) => {
      const st = t.state === 'on' ? 'on' : t.state === 'connecting' ? 'wait' : t.state === 'ended' ? 'end' : 'off';
      return '<div class="xt-tab' + (t === S.cur ? ' cur' : '') + '" data-i="' + i + '" title="' + E(t.title) + '"><i class="d ' + st + '"></i><span>' + E(short(t.title)) + '</span>' +
        '<button type="button" class="x" data-close="' + i + '" title="Fechar este terminal">' + svg('x') + '</button></div>';
    }).join('');
    const st = $('xtSt');
    if (st && S.cur) st.textContent = { on: 'conectado', connecting: 'conectando…', off: 'sem conexão · tentando de novo', ended: 'sessão encerrada', kicked: 'aberto em outra janela' }[S.cur.state] || '';
  }
  function short(title) {
    const m = /^[^@\s]+@[^:\s]+:\s*(.*)$/.exec(title || '');
    let s = m ? m[1] || '~' : title || 'Terminal';
    if (s.length > 28) s = '…' + s.slice(-27);
    return s;
  }
  function saveTabs() { ls.set('sids', S.tabs.filter(t => t.sid && t.state !== 'ended').map(t => t.sid)); }

  function newTab(sid, select) {
    const t = { sid: sid || '', title: 'Terminal ' + (++S.n), state: 'connecting', ws: null, retry: 0, timer: 0, queue: [], el: document.createElement('div') };
    t.el.className = 'xt-term';
    host.appendChild(t.el);
    t.term = new window.Terminal({
      fontFamily: FONT, fontSize: S.fs, lineHeight: 1.1, cursorBlink: true, scrollback: 5000, theme: THEME,
      allowProposedApi: false, macOptionIsMeta: true, rightClickSelectsWord: false, convertEol: false
    });
    const F = window.FitAddon && (window.FitAddon.FitAddon || window.FitAddon);
    if (typeof F === 'function') { t.fit = new F(); t.term.loadAddon(t.fit); }
    t.term.open(t.el);
    t.term.onData(d => input(t, d));
    if (t.term.onBinary) t.term.onBinary(d => { if (t.ws && t.ws.readyState === 1) t.ws.send(Uint8Array.from(d, c => c.charCodeAt(0) & 255)); });
    t.term.onResize(({ cols, rows }) => { if (t.ws && t.ws.readyState === 1) t.ws.send('r' + cols + ',' + rows); });
    t.term.onTitleChange(title => { if (title) { t.title = title; paintTabs(); } });
    t.term.attachCustomKeyEventHandler(ev => keyHandler(t, ev));
    t.el.addEventListener('contextmenu', ev => { if (t.term.hasSelection()) { ev.preventDefault(); copySel(); } });
    S.tabs.push(t);
    if (select !== false) pick(t);
    connect(t);
    return t;
  }

  function pick(t) {
    S.cur = t;
    S.tabs.forEach(x => x.el.classList.toggle('on', x === t));
    paintTabs();
    hideMsg();
    if (t.state === 'kicked') showMsg('Este terminal foi aberto em outra janela ou aparelho.', [['Usar aqui', () => { hideMsg(); connect(t); }]]);
    requestAnimationFrame(() => { fit(); if (!coarse || document.activeElement === document.body) t.term.focus(); });
  }

  function closeTab(t) {
    if (t.ws && t.ws.readyState === 1 && t.state === 'on') { try { t.ws.send('k'); } catch (e) { } }
    clearTimeout(t.timer);
    t.state = 'ended';
    if (t.ws) { try { t.ws.close(); } catch (e) { } }
    t.term.dispose();
    t.el.remove();
    const i = S.tabs.indexOf(t);
    S.tabs.splice(i, 1);
    saveTabs();
    if (S.cur === t) {
      if (S.tabs.length) pick(S.tabs[Math.max(0, i - 1)]);
      else { S.cur = null; newTab(); }
    } else paintTabs();
  }

  /* ------------------------------------------------------------ conexão */
  async function connect(t) {
    if (t.state === 'ended' || t.asking || (t.ws && t.ws.readyState <= 1)) return;
    clearTimeout(t.timer);
    t.state = 'connecting'; paintTabs();
    let d;
    t.asking = true;
    try {
      d = await api('ticket', { sid: t.sid, cols: t.term.cols, rows: t.term.rows });
    } catch (e) {
      t.asking = false;
      if (e.off) { fatal(e.message); return; }
      t.state = 'off'; paintTabs();
      if (t === S.cur && (e.down || t.retry > 1)) showMsg(e.message, [['Tentar de novo', () => { hideMsg(); t.retry = 0; connect(t); }]]);
      return retryLater(t);
    }
    t.asking = false;
    if (t.state === 'ended') return;
    const u = new URL('term-ws?t=' + d.ticket, location.href);
    u.protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
    let ws;
    try { ws = new WebSocket(u.href); } catch (e) { t.state = 'off'; return retryLater(t); }
    ws.binaryType = 'arraybuffer';
    t.ws = ws;
    t.reattach = !!t.sid;
    ws.onmessage = ev => {
      if (t.ws !== ws) return;
      if (typeof ev.data === 'string') { let m; try { m = JSON.parse(ev.data); } catch (e) { return; } control(t, m); }
      else t.term.write(new Uint8Array(ev.data));
    };
    ws.onclose = () => {
      if (t.ws !== ws) return;
      t.ws = null;
      if (t.state === 'ended' || t.state === 'kicked') { paintTabs(); return; }
      const was = t.state;
      t.state = 'off'; paintTabs();
      if (was === 'on') t.retry = 0;
      retryLater(t);
    };
  }
  function retryLater(t) {
    clearTimeout(t.timer);
    if (t.state === 'ended' || t.state === 'kicked') return;
    const wait = [500, 1500, 3000, 5000, 10000][Math.min(t.retry++, 4)];
    t.timer = setTimeout(() => { if (!document.hidden || t.retry < 3) connect(t); }, wait);
  }

  function control(t, m) {
    if (m.t === 'hello') {
      if (t.reattach) t.term.reset();
      t.sid = m.sid; t.state = 'on'; t.retry = 0;
      saveTabs(); paintTabs();
      if (t === S.cur) hideMsg();
      if (t.term.cols && t.ws) t.ws.send('r' + t.term.cols + ',' + t.term.rows);
      const q = t.queue.splice(0);
      q.forEach(s => send(t, s));
    } else if (m.t === 'exit') {
      t.state = 'ended'; t.sid = '';
      saveTabs(); paintTabs();
      t.term.write('\r\n\x1b[2m[sessão encerrada · tecle Enter para abrir outra]\x1b[0m\r\n');
    } else if (m.t === 'gone') {
      t.ws = null;                                    // o fechamento que vem a seguir não deve reconectar de novo
      t.sid = ''; t.reattach = false;
      t.term.reset();
      t.term.write('\x1b[2m[a sessão anterior foi encerrada no servidor · abrindo uma nova]\x1b[0m\r\n');
      t.state = 'off';
      setTimeout(() => connect(t), 50);
    } else if (m.t === 'kicked') {
      t.state = 'kicked'; paintTabs();
      if (t === S.cur) showMsg('Este terminal foi aberto em outra janela ou aparelho.', [['Usar aqui', () => { hideMsg(); t.state = 'off'; connect(t); }]]);
    } else if (m.t === 'error') {
      t.state = 'ended'; t.sid = ''; saveTabs(); paintTabs();
      toast(m.msg || 'Erro no terminal', 'er');
      t.term.write('\r\n\x1b[31m' + (m.msg || 'Erro') + '\x1b[0m\r\n');
    }
  }

  function send(t, s) {
    if (t.ws && t.ws.readyState === 1 && t.state === 'on') t.ws.send('i' + s);
    else { t.queue.push(s); if (t.state === 'off') connect(t); }
  }

  /* ------------------------------------------------------------ teclado */
  function input(t, d) {
    if (t.state === 'ended') {                       // Enter numa sessão encerrada abre outra no lugar
      if (d === '\r' || d === '\n') { t.state = 'off'; t.sid = ''; t.reattach = false; t.term.reset(); connect(t); }
      return;
    }
    if (S.ctrl && d.length === 1) {
      const c = d.toUpperCase().charCodeAt(0);
      if (c >= 64 && c <= 95) d = String.fromCharCode(c - 64);
      else if (d === '?') d = '\x7f';
      else if (d === ' ') d = '\x00';
      setMod('ctrl', false);
    }
    if (S.alt) { d = '\x1b' + d; setMod('alt', false); }
    send(t, d);
  }

  function keyHandler(t, ev) {
    if (ev.type !== 'keydown') return true;
    const k = ev.key.toLowerCase();
    if (ev.ctrlKey && ev.shiftKey && k === 'c') { copySel(); ev.preventDefault(); return false; }
    if (ev.ctrlKey && ev.shiftKey && k === 'v') return false;            // o navegador cola sozinho
    if (ev.ctrlKey && !ev.shiftKey && !ev.altKey && k === 'c' && t.term.hasSelection()) { copySel(); ev.preventDefault(); return false; }
    return true;
  }

  function setMod(m, on) {
    S[m] = on;
    const b = qs('#xtKeys [data-k="' + m + '"]'); if (b) b.classList.toggle('on', on);
  }

  function key(k) {
    const t = S.cur; if (!t) return;
    if (k === 'ctrl' || k === 'alt') { setMod(k, !S[k]); t.term.focus(); return; }
    const app = t.term.modes && t.term.modes.applicationCursorKeysMode;
    const cur = c => (app ? '\x1bO' : '\x1b[') + c;
    const map = {
      esc: '\x1b', tab: '\t', up: cur('A'), down: cur('B'), right: cur('C'), left: cur('D'),
      home: '\x1b[H', end: '\x1b[F', pgup: '\x1b[5~', pgdn: '\x1b[6~', '^c': '\x03', '^d': '\x04', '^z': '\x1a'
    };
    let d = map[k] != null ? map[k] : k;
    if (S.ctrl && k.length === 1) { input(t, k); t.term.focus(); return; }
    if (S.alt) { d = '\x1b' + d; setMod('alt', false); }
    if (S.ctrl) setMod('ctrl', false);
    if (t.state === 'ended') input(t, d); else send(t, d);
    t.term.focus();
  }

  /* ------------------------------------------------------------ ações da barra */
  function copySel() {
    const t = S.cur; if (!t) return;
    const s = t.term.getSelection();
    if (!s) return toast('Selecione um texto no terminal primeiro');
    U.copyText(s).then(() => { toast('Copiado'); t.term.clearSelection(); });
  }
  async function pasteText() {
    const t = S.cur; if (!t) return;
    if (navigator.clipboard && navigator.clipboard.readText && window.isSecureContext) {
      try { const s = await navigator.clipboard.readText(); if (s) { t.term.paste(s); t.term.focus(); } return; } catch (e) { }
    }
    const r = await U.dialog({
      title: 'Colar no terminal', icon: 'paste', wide: true,
      html: '<div>Cole o texto aqui (Ctrl+V ou segure e toque em Colar):</div><textarea class="fm-in xt-paste" spellcheck="false"></textarea>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Colar', value: 'ok', kind: 'pri' }],
      validate(ov) { const v = qs('textarea', ov).value; return v ? { v } : false; }
    });
    if (r && r.v) { t.term.paste(r.v); t.term.focus(); }
  }
  function setFont(d) {
    S.fs = Math.max(9, Math.min(24, S.fs + d));
    ls.set('fs', S.fs);
    S.tabs.forEach(t => { t.term.options.fontSize = S.fs; });
    fitSoon();
  }
  function toggleFull(on) {
    S.full = on == null ? !S.full : on;
    $('xtBox').classList.toggle('xt-full', S.full);
    document.body.classList.toggle('xt-noscroll', S.full);
    $('xtFullBtn').innerHTML = svg(S.full ? 'shrink' : 'expand');
    $('xtFullBtn').title = S.full ? 'Sair da tela cheia' : 'Tela cheia';
    fitSoon();
    if (S.cur) S.cur.term.focus();
  }
  function onBar(e) {
    const tb = e.target.closest('.xt-tab');
    const cl = e.target.closest('[data-close]');
    if (cl) {
      const t = S.tabs[+cl.dataset.close];
      if (!t) return;
      if (t.state === 'on' || t.state === 'off') {
        U.confirmDlg('Fechar este terminal?', 'O que estiver rodando nele será encerrado.', 'Fechar', true).then(ok => { if (ok) closeTab(t); });
      } else closeTab(t);
      return;
    }
    if (tb) { const t = S.tabs[+tb.dataset.i]; if (t && t !== S.cur) pick(t); else if (t) t.term.focus(); return; }
    const b = e.target.closest('[data-x]'); if (!b) return;
    const r = b.getBoundingClientRect();
    switch (b.dataset.x) {
      case 'new': if (S.tabs.length >= 8) return toast('Máximo de 8 terminais abertos', 'er'); newTab(); break;
      case 'copy': copySel(); break;
      case 'paste': pasteText(); break;
      case 'font-': setFont(-1); break;
      case 'font+': setFont(1); break;
      case 'full': toggleFull(); break;
      case 'quick':
        U.menu(r.left, r.bottom + 4, QUICK.map(c => ({ l: c, i: 'term', fn: () => run(c) })));
        break;
      case 'more':
        U.menu(r.right - 230, r.bottom + 4, [
          { l: 'Limpar a tela', i: 'refresh', fn: () => { if (S.cur) { S.cur.term.clear(); S.cur.term.focus(); } } },
          { l: 'Reconectar', i: 'refresh', fn: () => { const t = S.cur; if (!t) return; hideMsg(); if (t.ws) { try { t.ws.close(); } catch (er) { } } t.state = 'off'; t.retry = 0; setTimeout(() => connect(t), 100); } },
          '-',
          { l: 'Modo simples (o terminal antigo)', i: 'term', fn: () => setMode('simple') },
          '-',
          { l: 'Fechar todos os terminais', i: 'trash', danger: true, fn: closeAll }
        ]);
        break;
    }
  }
  async function closeAll() {
    if (!(await U.confirmDlg('Fechar todos os terminais?', 'Todas as sessões abertas no servidor serão encerradas.', 'Fechar todos', true))) return;
    S.tabs.slice().forEach(t => { if (t.ws && t.ws.readyState === 1) { try { t.ws.send('k'); } catch (e) { } } t.state = 'ended'; });
    S.tabs.slice().forEach(t => { if (t.ws) try { t.ws.close(); } catch (e) { } t.term.dispose(); t.el.remove(); });
    S.tabs = []; S.cur = null; saveTabs();
    newTab();
  }

  /* ------------------------------------------------------------ mensagens */
  function showMsg(text, btns) {
    const m = $('xtMsg'); if (!m) return;
    m.innerHTML = '<div class="xt-mbox"><p>' + E(text) + '</p><div>' + (btns || []).map((b, i) => '<button type="button" class="abtn' + (i ? '' : ' pri') + ' sm" data-m="' + i + '">' + E(b[0]) + '</button>').join(' ') + '</div></div>';
    m.hidden = false;
    qsa('[data-m]', m).forEach(b => b.onclick = () => btns[+b.dataset.m][1]());
  }
  function hideMsg() { const m = $('xtMsg'); if (m) m.hidden = true; }
  function fatal(msg) {
    S.error = msg;
    root.innerHTML = '<div class="card xt-fail"><b>Terminal completo indisponível</b><p>' + E(msg) + '</p><button type="button" class="abtn pri" id="xtUseSimple">Usar o modo simples</button></div>';
    $('xtUseSimple').onclick = () => setMode('simple');
    S.built = false; S.tabs = []; S.cur = null;
  }

  /* ------------------------------------------------------------ modo (completo / simples) */
  function setMode(m) {
    S.mode = m; ls.set('mode', m);
    if (m === 'full') { S.error = ''; }
    show();
  }
  function applyMode() {
    const full = S.mode === 'full' && canFull();
    $('xt').hidden = !full;
    $('tSimple').hidden = full;
    const b = $('tFull');
    if (b) { b.hidden = !canFull(); b.onclick = () => setMode('full'); }
    return full;
  }

  async function start() {
    if (S.built || S.error) return;
    root = $('xt');
    root.innerHTML = '<div class="card xt-load">Abrindo o terminal…</div>';
    try { await loadLib(); } catch (e) { fatal(e.message); return; }
    build();
    let sids = ls.get('sids', []);
    if (!Array.isArray(sids)) sids = [];
    let server = [];
    try { server = (await api('list')).sessions; } catch (e) { if (e.off) { fatal(e.message); return; } }
    const alive = new Set(server.map(s => s.id));
    // as abas desta janela + as que ficaram abertas sem ninguém olhando (ex.: começou no PC e abriu no celular)
    const want = sids.filter(id => alive.has(id));
    server.forEach(s => { if (!s.attached && !want.includes(s.id)) want.push(s.id); });
    if (want.length) want.forEach((id, i) => newTab(id, i === 0));
    else newTab();
    pending.splice(0).forEach(run);
  }

  const pending = [];
  function run(cmd) {
    if (!S.built) { pending.push(cmd); return; }
    let t = S.cur || newTab();
    if (t.state === 'ended') { t.state = 'off'; t.sid = ''; t.reattach = false; t.term.reset(); connect(t); }
    send(t, cmd + '\r');
    t.term.focus();
  }

  function show() {
    visible = true;
    if (!applyMode()) { setTimeout(() => $('tIn') && $('tIn').focus(), 50); return; }
    if (!S.built) { start(); return; }
    requestAnimationFrame(() => { fit(); if (S.cur) S.cur.term.focus(); });
    S.tabs.forEach(t => { if (t.state === 'off') connect(t); });
  }
  function hide() {
    visible = false;
    if (S.full) toggleFull(false);
  }

  window.TERM = {
    show, hide,
    active: () => active(),
    run(cmd) { if (!visible) location.hash = '#terminal'; run(cmd); }
  };
  if ((location.hash || '') === '#terminal') show();
})();
LKM_EOF_TERMJS
cat > "$DIR/sys.js" <<'LKM_EOF_SYSJS'
/* LK Monitor - ações do sistema no Painel: serviços (iniciar/parar/reiniciar), encerrar processo,
   modo servidor ↔ modo com tela, reiniciar e desligar o PC. Tudo passa por ?sys= (login + token) e vai para o cmd.log. */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const { E, qs, toast, dialog, menu, svg, IC } = U;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const TOKEN = C0.token || '';
  const ROOT = C0.user === 'root';
  const NEED_ROOT = 'Precisa do terminal do LK Monitor como root (sudo lk › 33 › instalar / atualizar e escolha root).';
  const PANEL = n => n === 'apache2' || /^php\d+\.\d+-fpm$/.test(n);
  const CRITICAL = ['systemd', 'init', 'sshd', 'dbus-daemon', 'systemd-journal', 'systemd-logind', 'apache2', 'php-fpm', 'mariadbd', 'mysqld', 'dockerd', 'containerd', 'Xorg', 'gnome-shell', 'gdm', 'gdm3'];
  let MODE = null, busy = false;

  Object.assign(IC, {
    play: '<path d="M7 4v16l13-8z"/>',
    stop: '<rect x="6" y="6" width="12" height="12" rx="1.5"/>',
    restart: '<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/>',
    monitor: '<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>',
    srv: '<rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/>',
    skull: '<path d="M12 3a8 8 0 0 0-5 14.2V20h10v-2.8A8 8 0 0 0 12 3z"/><path d="M9 12h.01M15 12h.01M10 20v-2M14 20v-2"/>'
  });

  async function api(act, body) {
    let r;
    try {
      r = await fetch('?sys=' + act, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': TOKEN }, body: JSON.stringify(body || {}) });
    } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do servidor (' + r.status + ')'); }
    if (!d.ok) throw new Error(d.error || 'Erro desconhecido');
    return d;
  }
  const refresh = () => { if (typeof tick === 'function') setTimeout(tick, 400); };
  const showErr = (title, e) => dialog({ title, icon: 'info', html: '<pre class="sy-pre">' + E(e.message || String(e)) + '</pre>', buttons: [{ label: 'Fechar', value: null }] });

  /* ------------------------------------------------------------ serviços */
  async function service(name, op) {
    const verb = { start: 'Iniciar', stop: 'Parar', restart: 'Reiniciar' }[op];
    if (op === 'stop' || (op === 'restart' && name === 'ssh')) {
      const warn = name === 'ssh' ? '<p class="sy-warn">Quem estiver conectado por SSH pode cair.</p>'
        : name === 'ufw' ? '<p class="sy-warn">Sem o ufw o firewall fica desligado.</p>'
        : /mariadb|mysql/.test(name) ? '<p class="sy-warn">Os sites que usam banco de dados vão dar erro enquanto estiver parado.</p>' : '';
      const ok = await dialog({ title: verb + ' ' + name + '?', icon: 'power', html: '<p>O serviço <b>' + E(name) + '</b> vai ' + (op === 'stop' ? 'parar' : 'reiniciar') + '.</p>' + warn,
        buttons: [{ label: 'Cancelar', value: null }, { label: verb, value: true, kind: op === 'stop' ? 'danger' : 'pri' }] });
      if (!ok) return;
    }
    toast(verb + ' ' + name + '…');
    try { const d = await api('service', { name, op }); toast(d.msg); refresh(); if (d.delayed) setTimeout(refresh, 4000); }
    catch (e) { showErr('Não foi possível ' + verb.toLowerCase() + ' ' + name, e); }
  }

  document.addEventListener('click', e => {
    const b = e.target.closest('#svcs .svc[data-svc]');
    if (!b) return;
    e.preventDefault();
    const name = b.dataset.svc, on = b.dataset.st === 'active', r = b.getBoundingClientRect();
    const ent = [
      { l: 'Iniciar', i: 'play', dis: on || !ROOT, fn: () => service(name, 'start') },
      { l: 'Reiniciar', i: 'restart', dis: !ROOT, fn: () => service(name, 'restart') },
      { l: PANEL(name) ? 'Parar (desligaria o painel)' : 'Parar', i: 'stop', danger: true, dis: !on || !ROOT || PANEL(name), fn: () => service(name, 'stop') }
    ];
    if (!ROOT) ent.push('-', { l: 'Precisa de root', i: 'lock', dis: true, fn() { } });
    menu(r.left, r.bottom + 4, ent);
  });

  /* ------------------------------------------------------------ processos */
  document.addEventListener('click', async e => {
    const b = e.target.closest('#procs .pk');
    if (!b) return;
    if (!ROOT) return toast(NEED_ROOT, 'er');
    const pid = +b.dataset.pid, name = b.dataset.name, user = b.dataset.user;
    const crit = CRITICAL.some(c => name === c || name.startsWith(c));
    const r = await dialog({
      title: 'Encerrar ' + name + '?', icon: 'trash',
      html: '<p>Processo <b>' + E(name) + '</b> · PID <code>' + pid + '</code> · usuário ' + E(user) + '</p>' +
        (crit ? '<p class="sy-warn">Este é um processo do sistema. Encerrar pode derrubar serviços, o SSH ou o próprio painel.</p>' : '') +
        '<p class="sy-note"><b>Encerrar</b> pede para o programa fechar (SIGTERM). <b>Forçar</b> mata na hora, sem salvar nada (kill -9).</p>',
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Forçar', value: 'KILL' }, { label: 'Encerrar', value: 'TERM', kind: 'danger' }]
    });
    if (!r) return;
    try { const d = await api('kill', { pid, name, sig: r }); toast(d.msg); refresh(); }
    catch (er) { showErr('Não foi possível encerrar ' + name, er); }
  });

  /* ------------------------------------------------------------ modo servidor e energia */
  function paint() {
    const box = qs('#sysAct'), lab = qs('#sysMode');
    if (!box) return;
    const m = MODE;
    if (lab) lab.textContent = !m ? '' : m.server ? (m.desktop_now ? 'modo servidor · tela ainda ligada' : 'modo servidor') : (m.desktop_now ? 'com área de trabalho' : 'normal · tela desligada agora');
    const dis = !ROOT || busy ? ' disabled' : '';
    const tip = ROOT ? '' : ' title="' + E(NEED_ROOT) + '"';
    const modeBtn = !m ? '' : m.server
      ? '<button class="abtn sm" data-a="desktop"' + dis + tip + '>' + svg('monitor') + 'Modo com tela</button>'
      : '<button class="abtn sm" data-a="server"' + dis + tip + '>' + svg('srv') + 'Modo servidor</button>';
    box.innerHTML = modeBtn +
      '<button class="abtn sm" data-a="reboot"' + dis + tip + '>' + svg('restart') + 'Reiniciar PC</button>' +
      '<button class="abtn sm sy-off" data-a="poweroff"' + dis + tip + '>' + svg('power') + 'Desligar</button>' +
      (busy ? '<span class="sy-busy">' + E(busy) + '</span>' : '');
  }

  async function loadMode() {
    try { MODE = (await api('status')).mode; } catch (e) { MODE = null; }
    paint();
  }

  async function setMode(to) {
    const srv = to === 'server';
    const html = (srv
      ? '<p>Desliga a área de trabalho (fica só o servidor), a tela apaga sozinha depois de 1 minuto, fechar a tampa não suspende e a suspensão fica bloqueada. Igual à opção 35 do <code>sudo lk</code>.</p>'
      : '<p>A área de trabalho volta a ligar, a tela, a tampa e a suspensão voltam ao padrão do sistema.</p>') +
      '<div class="sy-lbl">Quando aplicar</div><div class="seg sy-when">' +
      '<button type="button" data-w="agora" class="on">Agora</button><button type="button" data-w="reiniciar">Reiniciar o PC</button><button type="button" data-w="boot">Só no próximo boot</button></div>' +
      '<p class="sy-note" data-n="agora">' + (srv ? 'A tela do notebook vai para o modo texto. Programas abertos na área de trabalho são fechados.' : 'A tela de login aparece no notebook.') + ' O painel continua no ar.</p>' +
      '<p class="sy-note" data-n="reiniciar" hidden>O PC reinicia; o painel volta em 1 ou 2 minutos.</p>' +
      '<p class="sy-note" data-n="boot" hidden>Nada muda agora; vale quando o PC ligar de novo.</p>';
    const r = await dialog({
      title: srv ? 'Ativar modo servidor' : 'Voltar ao modo com tela', icon: 'server', html,
      buttons: [{ label: 'Cancelar', value: null }, { label: 'Aplicar', value: 'ok', kind: 'pri' }],
      onOpen(ov) {
        ov.dataset.w = 'agora';
        ov.querySelectorAll('.sy-when button').forEach(b => b.onclick = () => {
          ov.dataset.w = b.dataset.w;
          ov.querySelectorAll('.sy-when button').forEach(x => x.classList.toggle('on', x === b));
          ov.querySelectorAll('.sy-note[data-n]').forEach(n => n.hidden = n.dataset.n !== b.dataset.w);
        });
      },
      validate(ov) { return { when: ov.dataset.w }; }
    });
    if (!r) return;
    busy = 'Configurando… pode levar até 1 minuto'; paint();
    try {
      const d = await api('mode', { to, when: r.when });
      if (d.mode) MODE = d.mode;
      toast(d.msg);
      if (r.when === 'agora') setTimeout(loadMode, 6000);
    } catch (e) { showErr('Falha ao trocar o modo', e); }
    busy = false; paint();
  }

  async function power(op) {
    const off = op === 'poweroff';
    const ok = await dialog({
      title: off ? 'Desligar o PC?' : 'Reiniciar o PC?', icon: 'power',
      html: off ? '<p>O servidor <b>' + E(C0.host || '') + '</b> vai desligar. Todos os sites e o painel saem do ar.</p><p class="sy-warn">Para ligar de novo, alguém precisa apertar o botão de ligar no PC.</p>'
        : '<p>O servidor <b>' + E(C0.host || '') + '</b> vai reiniciar. Os sites e o painel ficam fora do ar por 1 ou 2 minutos.</p>',
      buttons: [{ label: 'Cancelar', value: null }, { label: off ? 'Desligar' : 'Reiniciar', value: true, kind: 'danger' }]
    });
    if (!ok) return;
    try {
      const d = await api('power', { op });
      busy = off ? 'Desligando…' : 'Reiniciando… o painel volta sozinho'; paint();
      toast(d.msg);
      if (!off) waitBack();
    } catch (e) { showErr('Não foi possível ' + (off ? 'desligar' : 'reiniciar'), e); }
  }

  /* depois de reiniciar: espera o painel cair e voltar, então recarrega */
  function waitBack() {
    let down = false, n = 0;
    const t = setInterval(async () => {
      if (++n > 120) { clearInterval(t); busy = false; paint(); return; }
      try {
        const r = await fetch('?api=1', { cache: 'no-store', credentials: 'same-origin' });
        if (down && (r.ok || r.status === 401)) { clearInterval(t); location.reload(); }
      } catch (e) { down = true; }
    }, 5000);
  }

  document.addEventListener('click', e => {
    const b = e.target.closest('#sysAct button[data-a]');
    if (!b || b.disabled) return;
    const a = b.dataset.a;
    if (a === 'server' || a === 'desktop') setMode(a); else power(a);
  });

  /* o menu do fm.js só fecha sozinho depois que a aba Arquivos abre: fecha aqui também */
  document.addEventListener('mousedown', e => { if (!e.target.closest('#fmMenu')) U.closeMenu(); }, true);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') U.closeMenu(); });
  window.addEventListener('scroll', () => U.closeMenu(), true);
  window.addEventListener('blur', () => U.closeMenu());

  paint();
  loadMode();
})();
LKM_EOF_SYSJS
cat > "$DIR/apps.js" <<'LKM_EOF_APPSJS'
/* LK Monitor - aba Apps (App Store em tabela, estilo clássico) e a grade "Software" + números da visão geral do Painel.
   As instalações rodam como tarefa em segundo plano (job.php) e o log aparece ao vivo (window.JOBS). */
(function () {
  'use strict';
  const U = window.UI;
  if (!U) return;
  const { E, qs, toast, dialog, menu, svg } = U;
  const C0 = typeof CFG !== 'undefined' ? CFG : {};
  const TOKEN = C0.token || '';
  const S = { data: null, error: '', cat: 'all', q: '', loading: false };
  let root, inited = false, poll = null;
  const ls = { get(k, d) { try { const v = localStorage.getItem('lkm.apps.' + k); return v === null ? d : v; } catch (e) { return d; } }, set(k, v) { try { localStorage.setItem('lkm.apps.' + k, v); } catch (e) { } } };
  S.cat = ls.get('cat', 'all');

  async function post(route, act, body) {
    let r;
    try {
      r = await fetch('?' + route + '=' + act, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-LKM-Token': TOKEN }, body: JSON.stringify(body || {}) });
    } catch (e) { throw new Error('Sem conexão com o painel'); }
    if (r.status === 401) { location.reload(); throw new Error('Sessão expirada'); }
    let d; try { d = await r.json(); } catch (e) { throw new Error('Resposta inválida do servidor (' + r.status + ')'); }
    if (!d.ok) { const er = new Error(d.error || 'Erro desconhecido'); er.data = d; throw er; }
    return d;
  }
  const api = (act, body) => post('apps', act, body);
  const showErr = (title, e) => dialog({ title, icon: 'info', html: '<pre class="sy-pre">' + E(e.message || String(e)) + '</pre>', buttons: [{ label: 'Fechar', value: null }] });
  const byId = id => (S.data && S.data.apps.find(a => a.id === id)) || null;
  const url = a => a.path ? 'http://' + location.hostname + a.path : a.port ? (a.https ? 'https://' : 'http://') + location.hostname + ':' + a.port + '/' : null;
  const initials = n => n.replace(/[^A-Za-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase() || '?';
  const logo = (a, cls) => a.icon ? '<img class="' + cls + '" src="' + E(a.icon) + '" alt="" loading="lazy">'
    : '<span class="' + cls + ' ini" style="background:' + E(a.color) + '">' + E(initials(a.name)) + '</span>';
  const rw = () => S.data && S.data.root && C0.user === 'root';

  /* ------------------------------------------------------------ montagem */
  function build() {
    root = qs('#apps');
    root.innerHTML = '<div class="card ap"><div class="ap-tabs" id="apCats"></div>' +
      '<div class="ap-tool"><span id="apCount"></span><span class="sp"></span><input class="ap-q" id="apQ" placeholder="Buscar app" autocomplete="off" spellcheck="false" aria-label="Buscar app">' +
      '<button class="abtn sm" id="apRf" title="Atualizar">' + svg('refresh') + '</button></div><div id="apMsg"></div>' +
      '<div class="ap-tw"><table class="ap-t"><thead><tr><th>Nome</th><th>Descrição</th><th>Status</th><th class="r">Ação</th></tr></thead><tbody id="apGrid"></tbody></table></div></div>';
    qs('#apQ').oninput = e => { S.q = e.target.value.trim().toLowerCase(); render(); };
    qs('#apRf').onclick = () => load();
    qs('#apCats').onclick = e => { const b = e.target.closest('button[data-c]'); if (!b) return; S.cat = b.dataset.c; ls.set('cat', S.cat); render(); };
    qs('#apGrid').onclick = onClick;
    qs('#apMsg').onclick = onClick;
  }

  async function load(quiet) {
    if (S.loading) return;
    S.loading = true;
    if (!quiet && !S.data && root) qs('#apGrid').innerHTML = '<tr><td colspan="4" class="ap-empty">Carregando…</td></tr>';
    try { S.data = await api('list'); S.error = ''; }
    catch (e) { S.error = e.message; }
    S.loading = false;
    render();
    homeAt = Date.now(); paintHome();
    clearTimeout(poll);
    if (S.data && S.data.busy && location.hash === '#apps') poll = setTimeout(() => load(true), 4000);
  }

  function render() {
    if (!root) return;
    const d = S.data, msg = qs('#apMsg');
    msg.innerHTML = S.error ? '<div class="st-ro">' + svg('info') + '<div>' + E(S.error) + '</div></div>' : '';
    if (!d) { if (S.error) qs('#apGrid').innerHTML = ''; return; }
    if (!rw()) msg.innerHTML += '<div class="st-ro">' + svg('lock') + '<div>Só para ver. Para instalar e desinstalar, o terminal do LK Monitor precisa ser <b>root</b>: no servidor rode <b>sudo lk</b> › opção <b>33</b> › instalar / atualizar e escolha root.</div></div>';
    if (d.busy) msg.innerHTML += '<div class="ap-busy"><i class="jspin"></i><span><b>' + E(d.busy.title) + '</b> em andamento…</span><button class="abtn sm" data-a="watch" data-j="' + E(d.busy.id) + '">Ver andamento</button></div>';

    const n = d.apps.filter(a => a.installed).length;
    qs('#apCount').textContent = n + ' de ' + d.apps.length + ' instalados';
    const cats = [['all', 'Todos'], ['inst', 'Instalados']].concat(Object.entries(d.cats));
    if (!cats.some(c => c[0] === S.cat)) S.cat = 'all';
    qs('#apCats').innerHTML = cats.map(([k, l]) => '<button data-c="' + k + '" class="' + (k === S.cat ? 'on' : '') + '">' + E(l) + '</button>').join('');
    const list = d.apps.filter(a => (S.cat === 'all' || (S.cat === 'inst' ? a.installed : a.cat === S.cat)) &&
      (!S.q || (a.name + ' ' + a.desc).toLowerCase().includes(S.q)));
    qs('#apGrid').innerHTML = list.length ? list.map(row).join('') : '<tr><td colspan="4" class="ap-empty">Nenhum app encontrado.</td></tr>';
  }

  function row(a) {
    const d = S.data, ok = rw();
    const mine = d.busy && d.busy.app === a.id, other = d.busy && !mine;
    let st;
    if (mine) st = '<span class="ap-st run"><i class="jspin"></i>' + (a.job && a.job.op === 'remove' ? 'Removendo' : 'Instalando') + '</span>';
    else if (!a.installed) st = '<span class="ap-st">Não instalado</span>';
    else if (a.state === 'active') st = '<span class="ap-st on"><b></b>Rodando</span>';
    else if (a.state && a.state !== 'unknown') st = '<span class="ap-st off"><b></b>' + ({ inactive: 'Parado', exited: 'Parado', failed: 'Com erro', activating: 'Iniciando', created: 'Parado' }[a.state] || E(a.state)) + '</span>';
    else st = '<span class="ap-st ok">Instalado</span>';

    const need = a.needs ? d.apps.find(x => x.id === a.needs) : null;
    const tags = [];
    if (a.docker) tags.push('<span class="tag">Docker</span>');
    if (a.port) tags.push('<span class="tag mono">:' + a.port + '</span>');
    if (!a.installed && need && !a.needs_ok) tags.push('<span class="tag ap-need">requer ' + E(need.name) + '</span>');
    if (a.job && a.job.state === 'error' && !mine) tags.push('<button class="tag ap-fail" data-a="watch" data-j="' + E(a.job.id) + '">' + (a.job.op === 'remove' ? 'remoção' : 'instalação') + ' falhou · ver log</button>');

    const acts = [];
    const sep = '<span class="ap-sep">|</span>';
    if (mine) acts.push('<button class="lnk" data-a="watch" data-j="' + E(d.busy.id) + '">Ver andamento</button>');
    else if (!a.installed) {
      const dis = !ok || other || !a.needs_ok;
      const why = !ok ? 'Precisa de root' : other ? 'Espere a outra instalação terminar' : !a.needs_ok ? 'Instale ' + (need ? need.name : a.needs) + ' antes' : '';
      acts.push('<button class="abtn sm pri" data-a="install"' + (dis ? ' disabled title="' + E(why) + '"' : '') + '>Instalar</button>');
    } else {
      const u = url(a);
      if (u) acts.push('<a class="lnk" href="' + E(u) + '" target="_blank" rel="noopener">Abrir</a>');
      if (a.svc || a.docker) acts.push(a.state === 'active' ? '<button class="lnk" data-a="restart"' + (ok ? '' : ' disabled') + '>Reiniciar</button>'
        : '<button class="lnk" data-a="start"' + (ok ? '' : ' disabled') + '>Iniciar</button>');
      acts.push('<button class="lnk" data-a="more">Mais ▾</button>');
    }
    return '<tr class="ap-c' + (a.installed ? ' inst' : '') + '" data-id="' + E(a.id) + '">' +
      '<td><div class="ap-n">' + logo(a, 'ap-logo') + '<div><b>' + E(a.name) + '</b><small>' + (a.version ? 'v' + E(a.version) : '—') + '</small></div></div></td>' +
      '<td class="ap-d"><div>' + E(a.desc) + '</div>' + (a.installed && a.note ? '<div class="ap-note">' + E(a.note) + '</div>' : '') +
      (tags.length ? '<div class="ap-tags">' + tags.join('') + '</div>' : '') + '</td>' +
      '<td>' + st + '</td><td class="r ap-acts">' + acts.join(sep) + '</td></tr>';
  }

  /* ------------------------------------------------------------ Painel: grade "Software" e números */
  let homeBusy = false, homeAt = 0;
  async function count(route, act, pick, id) {
    const el = qs('#' + id); if (!el) return;
    try { el.textContent = pick(await post(route, act)); } catch (e) { el.textContent = '–'; el.title = e.message; }
  }
  async function home(force) {
    const soft = qs('#soft');
    if (!soft || homeBusy) return;
    if (!force && S.data && Date.now() - homeAt < 5000) return paintHome();
    homeBusy = true;
    try { if (!S.data || force) S.data = await api('list'); homeAt = Date.now(); paintHome(); }
    catch (e) { soft.innerHTML = '<div class="empty">' + E(e.message) + '</div>'; }
    homeBusy = false;
  }
  function paintHome() {
    const soft = qs('#soft'), d = S.data;
    if (!soft || !d) return;
    const inst = d.apps.filter(a => a.installed);
    const ov = qs('#ovApps'); if (ov) ov.textContent = inst.length;
    soft.innerHTML = inst.length ? inst.map(a => '<a class="sw2" href="#apps" data-cat="inst" title="' + E(a.name) + (a.version ? ' v' + E(a.version) : '') + '">' +
      (a.state && a.state !== 'unknown' ? '<span class="dot' + (a.state === 'active' ? '' : ' off') + '"></span>' : '') + logo(a, '') + '<span>' + E(a.name) + '</span></a>').join('')
      : '<div class="empty">Nenhum app instalado ainda. Abra a App Store.</div>';
  }
  document.addEventListener('click', e => { const a = e.target.closest('#soft a[data-cat]'); if (a) { S.cat = 'inst'; ls.set('cat', 'inst'); } });
  function homeAll() {
    if (!qs('#soft')) return;
    home(true);
    count('sites', 'list', d => d.sites.length, 'ovSites');
    count('db', 'overview', d => d.mysql && d.mysql.ok ? d.dbs.length : '–', 'ovDbs');
  }

  /* ------------------------------------------------------------ ações */
  async function watch(id, title) {
    if (!window.JOBS) return toast('Atualize a página', 'er');
    await window.JOBS.view(id, title || 'App Store', 'download');
    load(true);
  }

  async function start(a, op) {
    const rm = op === 'remove';
    if (rm) {
      const deps = S.data.apps.filter(x => x.installed && x.needs === a.id);
      const html = '<p><b>' + E(a.name) + '</b> será removido do servidor.</p>' +
        (a.docker ? '<p class="sy-note">O container é apagado, mas os dados ficam guardados nos volumes do Docker. Se instalar de novo, volta como estava.</p>' : '') +
        (deps.length ? '<p class="sy-warn">Estes apps usam ' + E(a.name) + ' e vão parar de funcionar: <b>' + deps.map(x => E(x.name)).join(', ') + '</b>.</p>' : '') +
        (a.id === 'node' ? '<p class="sy-warn">Os apps Node do PM2 param de funcionar.</p>' : '') +
        (a.id === 'composer' ? '<p class="sy-warn">O deploy dos sites Laravel usa o Composer.</p>' : '');
      const ok = await dialog({ title: 'Desinstalar ' + a.name + '?', icon: 'trash', html, buttons: [{ label: 'Cancelar', value: null }, { label: 'Desinstalar', value: true, kind: 'danger' }] });
      if (!ok) return;
    }
    try {
      const d = await api(op, { id: a.id });
      load(true);
      await watch(d.job, (rm ? 'Desinstalar ' : 'Instalar ') + a.name);
    } catch (e) {
      if (e.data && e.data.running) return watch(e.data.running);
      showErr('Não foi possível ' + (rm ? 'desinstalar ' : 'instalar ') + a.name, e);
    }
  }

  async function svc(a, op) {
    if (op === 'stop') {
      const ok = await dialog({ title: 'Parar ' + a.name + '?', icon: 'power', html: '<p>' + E(a.name) + ' vai parar até você iniciar de novo (ou até o PC reiniciar).</p>', buttons: [{ label: 'Cancelar', value: null }, { label: 'Parar', value: true, kind: 'danger' }] });
      if (!ok) return;
    }
    toast({ start: 'Iniciando ', stop: 'Parando ', restart: 'Reiniciando ' }[op] + a.name + '…');
    try { const d = await api('svc', { id: a.id, op }); toast(d.msg); load(true); }
    catch (e) { showErr('Falha em ' + a.name, e); }
  }

  function onClick(e) {
    const b = e.target.closest('[data-a]');
    if (!b || b.disabled) return;
    const c = b.closest('.ap-c'), a = c ? byId(c.dataset.id) : null;
    const act = b.dataset.a;
    if (act === 'watch') return watch(b.dataset.j, a ? a.name : null);
    if (!a) return;
    if (act === 'install') return start(a, 'install');
    if (act === 'start' || act === 'restart') return svc(a, act);
    if (act === 'more') {
      const ok = rw(), r = b.getBoundingClientRect(), ent = [];
      if (a.svc || a.docker) {
        ent.push({ l: 'Iniciar', i: 'power', dis: !ok || a.state === 'active', fn: () => svc(a, 'start') });
        ent.push({ l: 'Reiniciar', i: 'refresh', dis: !ok, fn: () => svc(a, 'restart') });
        ent.push({ l: 'Parar', i: 'x', dis: !ok || a.state !== 'active', fn: () => svc(a, 'stop') }, '-');
      }
      const u = url(a);
      if (u) ent.push({ l: 'Copiar endereço', i: 'link', fn: () => U.copyText(u).then(() => toast('Endereço copiado')) });
      if (a.job) ent.push({ l: 'Ver último log', i: 'log', fn: () => watch(a.job.id, a.name) });
      if (ent.length && ent[ent.length - 1] !== '-') ent.push('-');
      ent.push({ l: a.protect ? 'Desinstalar (bloqueado)' : 'Desinstalar', i: 'trash', danger: true, dis: !ok || !!a.protect || !!S.data.busy, fn: () => start(a, 'remove') });
      if (a.protect) ent.push({ l: a.protect.length > 46 ? a.protect.slice(0, 44) + '…' : a.protect, i: 'lock', dis: true, fn() { } });
      menu(Math.max(6, r.right - 230), r.bottom + 4, ent);
    }
  }

  window.APPS = {
    show() {
      if (!inited) { build(); inited = true; }
      load();
    },
    home: homeAll
  };
  window.addEventListener('hashchange', () => { if (location.hash !== '#apps') clearTimeout(poll); });
  if (location.hash === '#apps') window.APPS.show();
  homeAll();
  setInterval(() => { if (!document.hidden && qs('#v-painel.on')) homeAll(); }, 300000);
})();
LKM_EOF_APPSJS
